(131553, 'koKR', '고마워요!', '', 25549),
(131552, 'koKR', '사랑해요.', '', 25549),
(131551, 'koKR', '<당신과 함께 있어 굉장히 기뻐 보이는 아기 달빛야수>', '', 25549),
(131550, 'koKR', '해독제를 투여합니다.', '해독제를 투여합니다.', 25549),
