INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(130514, 'koKR', '병력 음향 효과', '', 25549),
(130513, 'koKR', '병력 음향 효과', '병력 음향 효과', 25549),
(130512, 'koKR', '멋의 대제전에 참여하고 싶습니다!', '멋의 대제전에 참여하고 싶습니다!', 25549),
(130511, 'koKR', '유물 지식을 만드는 데 필요한 자원을 제게 가져다주시면 지금 곧바로 유물 지식을 획득할 수 있습니다.', '유물 지식을 만드는 데 필요한 자원을 제게 가져다주시면 지금 곧바로 유물 지식을 획득할 수 있습니다.', 25549),
(130510, 'koKR', '제 장비의 형상을 변환하고 싶습니다.', '제 장비의 형상을 변환하고 싶습니다.', 25549),
(130509, 'koKR', '당신의 무기와 방어구의 외형을 변경하는 데 필요한 모든 도구가 제게 있습니다.\n\n시작하실까요?', '', 25549),
(130508, 'koKR', '대마법사 카드가 님께서 유물 지식 연구를 계속할 수 있는 단초를 발견하셨습니다. 부서진 해변의 구원의 거점에서 그분을 찾으십시오.', '대마법사 카드가 님께서 유물 지식 연구를 계속할 수 있는 단초를 발견하셨습니다. 부서진 해변의 구원의 거점에서 그분을 찾으십시오.', 25549),
(130507, 'koKR', '현재 우리가 달성할 수 있는 최대 유물 지식에 도달했습니다.', '현재 우리가 달성할 수 있는 최대 유물 지식에 도달했습니다.', 25549),
(130506, 'koKR', '연맹이 현재 자원을 공유 중이므로, 이제 유물 지식을 연구할 필요가 없습니다. 우린 매주 유물에 대한 새로운 지식을 얻을 수 있습니다.', '연맹이 현재 자원을 공유 중이므로, 이제 유물 지식을 연구할 필요가 없습니다. 우린 매주 유물에 대한 새로운 지식을 얻을 수 있습니다.', 25549),
(130505, 'koKR', '왜 유물 연구를 더 할 수 없습니까?', '왜 유물 연구를 더 할 수 없습니까?', 25549),
(130504, 'koKR', '무슨 일이 있어도 맞서야 합니다.', '', 25549),
(130503, 'koKR', '맛볼 살점이 더 있군!', '', 25549),
(130502, 'koKR', '네 살이 이곳을 영원히 풍요롭게 하리라!', '', 25549),
(130501, 'koKR', '이 족쇄가 네 살점을 원한다!', '', 25549),
(130500, 'koKR', '무릎을 꿇지 않겠다면 죽어라!', '', 25549),
(130499, 'koKR', '나약한 것! 감히 우리 둥지에 들어오다니!', '', 25549),
(130498, 'koKR', '너희의 쫄깃한 살점을 먹어주마!', '', 25549),
(130497, 'koKR', '오늘 바삭한 뼈를 실컷 먹겠구나!', '', 25549),
(130496, 'koKR', '너희의 영혼을 삼키겠다!', '', 25549),
(130483, 'koKR', '오만한 필멸자로군! 와라... 죽음을 맞이해라!', '', 25549),
(130482, 'koKR', '이쪽입니다. 조심스레 움직이십시오.', '', 25549),
(130481, 'koKR', '맞아요... 오늘의 테마는 자유분방입니다. 하고 싶은 건 다 하세요!', '', 25549),
(130480, 'koKR', '오늘은 티끌 하나 없이 하얀 로브와 반짝이는 장비가 유행이군요!', '', 25549),
(130479, 'koKR', '알다시피, 영웅급 장비는 언제나 보라색이죠. 무지개 제일 아래에 있는 색깔로 자신을 치장해 보세요!', '', 25549),
(130478, 'koKR', '농부일까요? 아니면 요리사? 과학자? 해적? 오우... 다들 어떤 의상을 입고 나올지 기대됩니다!', '', 25549),
(130477, 'koKR', '테라모어인가요? 키린 토인가요? 당신을 대표하는 휘장을 보여주세요!', '', 25549),
(130476, 'koKR', '축제를 즐기며 정신 나간 의상을 입어볼 시간입니다!', '', 25549),
(130475, 'koKR', '장비 잘 닦으시고 포즈 취할 준비하세요!', '', 25549),
(130474, 'koKR', '동물 가죽, 덩굴도 좋습니다! 당신의 야성적인 면모를 보여주세요.', '', 25549),
(130473, 'koKR', '호드를 위하여! 얼라이언스를 위하여! 진영의 색을 뽐내세요!', '', 25549),
(130472, 'koKR', '더 사악하게 멋을 내보세요!', '', 25549),
(130471, 'koKR', '극과 극은 끌린다고 하죠. 하지만 옷도 과연 그럴까요?', '', 25549),
(130470, 'koKR', '즐겨봐요! 상상할 수 있는 가장 현란한 복장을 입어봅시다!', '', 25549),
(130469, 'koKR', '용기를 냅시다! 살 좀 드러낸다고 안 죽어요!', '', 25549),
(130468, 'koKR', '화장은 지우고 전쟁용 치장을 하세요!', '', 25549),
(130467, 'koKR', '꽁꽁 싸매세요! 노스렌드의 꽁꽁 언 해변에선 뭘 입어야 하는지 보여 주세요!', '', 25549),
(130466, 'koKR', '', '오늘 대회의 테마는... "용사님 하고 싶은 거 다 해"입니다!', 25549),
(130465, 'koKR', '', '오늘 대회의 테마는... "빛의 용사들"입니다!', 25549),
(130464, 'koKR', '', '오늘 대회의 테마는... "보라색의 위엄"입니다!', 25549),
(130463, 'koKR', '', '오늘 대회의 테마는... "영웅의 일상"입니다!', 25549),
(130462, 'koKR', '', '오늘 대회의 테마는... "휘장의 멋이란 게 폭발했다"입니다!', 25549),
(130461, 'koKR', '', '오늘 대회의 테마는... "날 웃겨 봐"입니다!', 25549),
(130460, 'koKR', '', '오늘 대회의 테마는... "아제로스의 영웅들"입니다!', 25549),
(130459, 'koKR', '', '오늘 대회의 테마는... "원시적 본능"입니다!', 25549),
(130458, 'koKR', '', '오늘 대회의 테마는... "진영의 자부심"입니다!', 25549),
(130457, 'koKR', '', '오늘 대회의 테마는... "치명적인 어둠의 흑염룡"입니다!', 25549),
(130456, 'koKR', '', '오늘 대회의 테마는... "불과 얼음의 왕좌의 패션"입니다!', 25549),
(130455, 'koKR', '', '오늘 대회의 테마는... "패션의 부조화로 들어가시오"입니다!', 25549),
(130454, 'koKR', '', '오늘 대회의 테마는... "누구보다 재미있게 남들보다 과감하게"입니다!', 25549),
(130453, 'koKR', '', '오늘 대회의 테마는... "공격 준비 완료"입니다!', 25549),
(130452, 'koKR', '', '오늘 대회의 테마는... "그 겨울 패션이 분다"입니다!', 25549),
(130450, 'koKR', '약속한 거야! 까먹기만 해 봐!', '', 25549),
(130449, 'koKR', '걱정 마, 동생아. 이번 일이 끝나고, 네가 나이를 더 먹으면, 내가 칼 휘두르는 법을 가르쳐 줄게. 아버지가 나한테 가르쳐 주셨던 것처럼 말이야. 약속!', '', 25549),
(130448, 'koKR', '엄마! 미카 형은 싸우게 놔두면서!', '', 25549),
(130447, 'koKR', '', '얘야, 가만히 있으렴! 너한테 무슨 일이라도 생기면 아빠가 얼마나 속상해 하시겠니.', 25549),
(130446, 'koKR', '제발, 나도 싸울래요!', '', 25549),
(130445, 'koKR', '내가 죽었다면, 우리 가족은 누가 돌보지?', '내가 죽었다면, 우리 가족은 누가 돌보지?', 25549),
(130444, 'koKR', '난 죽을 수 없어... 누가 좀 도와 줘...', '난 죽을 수 없어... 누가 좀 도와 줘...', 25549),
(130443, 'koKR', '제발... 악몽을 멈춰 주십시오!', '제발... 악몽을 멈춰 주십시오!', 25549),
(130442, 'koKR', '여기가 어디죠? 어떻게 된 건지 기억이 나지 않습니다...', '여기가 어디죠? 어떻게 된 건지 기억이 나지 않습니다...', 25549),
(130441, 'koKR', '죽고 싶지 않아...', '죽고 싶지 않아...', 25549),
(130440, 'koKR', '어떻게 된 거죠? 제 몸은 어디 있나요?', '어떻게 된 거죠? 제 몸은 어디 있나요?', 25549),
(130439, 'koKR', '', '인사드릴 시간이네요. 다음에 또 뵙겠습니다!', 25549),
(130438, 'koKR', '', '이번에 상을 못 받았어도 계속 노력하세요. 언젠가는 1위를 할 수 있을 거예요.', 25549),
(130437, 'koKR', '', '마지막으로, 이 밤을 장식할 형상변환 1위입니다. $n 님 축하드려요!', 25549),
(130436, 'koKR', '2위는... $n 님! 정말 멋졌어요!', '', 25549),
(130435, 'koKR', '', '3위는... $n 님! 축하드립니다, $n 님!', 25549),
(130434, 'koKR', '오른편에는, 개성 넘치는 $n 님!', '', 25549),
(130433, 'koKR', '친절을 베풀어 주셔서 감사합니다. 절대 잊지 않겠습니다...', '친절을 베풀어 주셔서 감사합니다. 절대 잊지 않겠습니다...', 25549),
(130432, 'koKR', '스톰윈드에 봉사할 수 있어서... 국왕님을 섬길 수 있어서 영광이었습니다.', '스톰윈드에 봉사할 수 있어서... 국왕님을 섬길 수 있어서 영광이었습니다.', 25549),
(130431, 'koKR', '', '왼편에는, 화려한 $n 님입니다!', 25549),
(130430, 'koKR', '보입니다... 빛이 보여요... 감사합니다.', '보입니다... 빛이 보여요... 감사합니다.', 25549),
(130429, 'koKR', '당신을 섬길 수 있어 영광이었습니다, 국왕 폐하...', '당신을 섬길 수 있어 영광이었습니다, 국왕 폐하...', 25549),
(130428, 'koKR', '마침내, 이 악몽도 끝났군요...', '마침내, 이 악몽도 끝났군요...', 25549),
(130427, 'koKR', '감사합니다. 절대 잊지 않겠습니다...', '감사합니다. 절대 잊지 않겠습니다...', 25549),
(130426, 'koKR', '부디... 우릴 잊지 말아 주십시오. 우리 희생을 잊지 마세요...', '부디... 우릴 잊지 말아 주십시오. 우리 희생을 잊지 마세요...', 25549),
(130425, 'koKR', '', '불타는 군단이 아제로스로 다가오고 있어요. 우리 모두 자기 역할을 해야 해요!', 25549),
(130424, 'koKR', '|TInterface\\Icons\\ABILITY_WARLOCK_INFERNO.BLP:20|t%s|1이;가; 당신을 |cFFFF0000|Hspell:238430|h[폭발하는 공포의 불길]|h|r의 대상으로 지정합니다!', '|TInterface\\Icons\\ABILITY_WARLOCK_INFERNO:20|t%s|1이;가; 당신을 |cFFFF0000|Hspell:238430|h[폭발하는 공포의 불길]|h|r의 대상으로 지정합니다!', 25549),
(130423, 'koKR', '준비 됐습니다!', '준비 됐습니다!', 25549),
(130422, 'koKR', '', '$ct, 이 지역의 펠스코른 연금술사가 점점 더 공격적으로 변해가고 있어요. 최근에는 우리 맥주를 훔쳐가기도 했죠. 더 끔찍한 건, 놈들이 그 맥주를 변형시켜서 살포기를 통해 여기저기 마구 뿌려 대고 있다는 거예요! \n\n놈들을 막아야 하지만, 쉬운 일은 아닐 거예요. 다행히 원숭이 왕이 우리에게 지팡이를 빌려주었어요. 그걸 사용해서 놈들의 머리 위로 올라가, 하늘에서 죽음을 선물해 주세요!\n\n도와주실 거죠?', 25549),
(130421, 'koKR', '대회는 2분 뒤 시작합니다. 행운을 빌어요, 멋쟁이들!', '', 25549),
(130420, 'koKR', '', '머리를 손질하실 분들을 위해 미용실 의자도 마련했습니다.', 25549),
(130419, 'koKR', '', '의상을 준비할 시간을 조금 드릴 겁니다.', 25549),
(130418, 'koKR', '오우, 예쁜 반바지 너무 좋죠.', '', 25549),
(130417, 'koKR', '', '오늘 대회의 테마는... "네가 이번 여름에 입을 옷을 알고 있다"입니다!', 25549),
(130416, 'koKR', '여러 벌 가져오셨길 바라요, 오늘 대회의 열기가 장난 아니거든요!', '', 25549),
(130415, 'koKR', '', '서두르십시오! 적이 들이닥칩니다!', 25549),
(130414, 'koKR', '', '멋의 대제전에 오신 걸 환영합니다. 아제로스의 멋쟁이는 전부 여기 모이죠!', 25549),
(130413, 'koKR', '우리가 이 괴물을 함께 쓰러뜨릴 겁니다.', '', 25549),
(130412, 'koKR', '저 찬란한 모습을 보세요! 누구도 필연적인 운명으로부터 숨을 수는 없습니다!', '저 찬란한 모습을 보세요! 누구도 필연적인 운명으로부터 숨을 수는 없습니다!', 25549),
(130411, 'koKR', '눈을 뜨세요, $n 님! 당신 안에는 거짓밖에 없습니다. 진실은 하늘에 있어요!', '눈을 뜨세요, $n 님! 당신 안에는 거짓밖에 없습니다. 진실은 하늘에 있어요!', 25549),
(130410, 'koKR', '이곳에는 허황된 약속만이 만연합니다! 부귀는 당신을 구원하지 못합니다!', '이곳에는 허황된 약속만이 만연합니다! 부귀는 당신을 구원하지 못합니다!', 25549),
(130409, 'koKR', '소유란 무의미합니다! 하늘을 보세요! 끝이 다가옵니다!', '소유란 무의미합니다! 하늘을 보세요! 끝이 다가옵니다!', 25549),
(130408, 'koKR', '물질적인 것은 당신을 구원하지 못합니다, $n 님!', '물질적인 것은 당신을 구원하지 못합니다, $n 님!', 25549),
(130406, 'koKR', '위대한 진실이 모습을 드러냈어요!', '위대한 진실이 모습을 드러냈어요!', 25549),
(130405, 'koKR', '하늘을 봐요! 위대한 운명이 우리 앞에 모습을 드러냈어요!', '하늘을 봐요! 위대한 운명이 우리 앞에 모습을 드러냈어요!', 25549),
(130404, 'koKR', '두 팔을 벌려 운명을 맞이하세요.', '두 팔을 벌려 운명을 맞이하세요.', 25549),
(130403, 'koKR', '마침내 때가 왔어요! 이제 마지막 여정이 시작되는군요!', '마침내 때가 왔어요! 이제 마지막 여정이 시작되는군요!', 25549),
(130402, 'koKR', '이 순간을 오랜 시간 꿈꿔왔지만, 이렇게... 아름다울 줄은 상상도 못했어요.', '이 순간을 오랜 시간 꿈꿔왔지만, 이렇게... 아름다울 줄은 상상도 못했어요.', 25549),
(130401, 'koKR', '최근에 흥미로운 생물을 본 게 있습니까?', '최근에 흥미로운 생물을 본 게 있습니까?', 25549),
(130400, 'koKR', '보물관리인 이크스리기드이 당신에게 무례한 몸짓을 취합니다.', '', 25549),
(130399, 'koKR', '|TInterface\\ICONS\\INV_Artifact_PoweroftheDarkSide.blp:20|t 몰락한 화신이 |cFFFF0404|Hspell:242017|h[검은 바람]|h|r을 불러냅니다!', '|TInterface\\ICONS\\INV_Artifact_PoweroftheDarkSide.blp:20|t 몰락한 화신이 |cFFFF0404|Hspell:242017|h[검은 바람]|h|r을 불러냅니다!', 25549),
(130398, 'koKR', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE:20|t%s|1이;가; |cFFFF0000|Hspell:240910|h[아마겟돈]|h|r을 시전합니다!', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE:20|t%s|1이;가; |cFFFF0000|Hspell:240910|h[아마겟돈]|h|r을 시전합니다!', 25549),
(130397, 'koKR', '|TInterface\\Icons\\Ability_Socererking_arcanemines:20|t%s|1이;가; |cFFFF0000|Hspell:235059|h[특이점 파열]|h|r을 생성합니다!', '|TInterface\\Icons\\Ability_Socererking_arcanemines:20|t%s|1이;가; |cFFFF0000|Hspell:235059|h[특이점 파열]|h|r을 생성합니다!', 25549),
(130396, 'koKR', '뭔가 희귀한 거라도 찾으셨습니까?', '뭔가 희귀한 거라도 찾으셨습니까?', 25549),
(130395, 'koKR', '당장은 아무것도 없습니다.', '당장은 아무것도 없습니다.', 25549),
(130394, 'koKR', '그 자루 안에 희귀한 악마의 장신구가 있습니까?', '그 자루 안에 희귀한 악마의 장신구가 있습니까?', 25549),
(130393, 'koKR', '빛을 향해 가십시오, 친구여. 이제 편히 쉴 시간이 됐습니다.', '빛을 향해 가십시오, 친구여. 이제 편히 쉴 시간이 됐습니다.', 25549),
(130392, 'koKR', '아냐, 내가 죽을 리가 없어! 가족들은 어떻게 하고... 가족을 두고 떠날 순 없습니다! 가족들이 저 없이 어떻게 살겠습니까?', '아냐, 내가 죽을 리가 없어! 가족들은 어떻게 하고... 가족을 두고 떠날 순 없습니다! 가족들이 저 없이 어떻게 살겠습니까?', 25549),
(130391, 'koKR', '여긴 어딥니까? 부서진 해변에서 싸우고 있었는데... 제 말이 들립니까? 신이시여... 전... 죽은 겁니까?', '여긴 어딥니까? 부서진 해변에서 싸우고 있었는데... 제 말이 들립니까? 신이시여... 전... 죽은 겁니까?', 25549),
(130390, 'koKR', '제... 제 몸을 찾을 수가 없습니다. 영혼의 기계 안에 갇혔었는데, 지금은... 여긴 어디죠? 저에게 무슨 일이 있었던 겁니까?!', '제... 제 몸을 찾을 수가 없습니다. 영혼의 기계 안에 갇혔었는데, 지금은... 여긴 어디죠? 저에게 무슨 일이 있었던 겁니까?!', 25549),
(130380, 'koKR', '아! 상자에는 뭐가 있지?! 뭐가 있었던 거야?!', '', 25549),
(130379, 'koKR', '하하! 너무 늦었다, 필멸자!', '', 25549),
(130378, 'koKR', '또 너야? 내 보물을 가져갈 순 없다니까!', '', 25549),
(130377, 'koKR', '너무 늦었어! 좋은 건 내가 벌써 가져갔거든!', '', 25549),
(130376, 'koKR', '부서진 해변.', '부서진 해변.', 25549),
(130375, 'koKR', '고통에 온몸을 유린당한 %s|1이;가; 몸부림칩니다.', '고통에 온몸을 유린당한 %s|1이;가; 몸부림칩니다.', 25549),
(130374, 'koKR', '%s|1이;가; 고통에 몸부림칩니다.', '%s|1이;가; 고통에 몸부림칩니다.', 25549),
(130373, 'koKR', '페타 비 하이로스.', '', 25549),
(130371, 'koKR', '크로나 카이 크리스토르!', '', 25549),
(130370, 'koKR', '우리 의지는... 무너지지 않는다.', '', 25549),
(130369, 'koKR', '고통은... 잠깐뿐이다.', '', 25549),
(130368, 'koKR', '넌... 우릴... 굴복시킬 수 없다.', '', 25549),
(130367, 'koKR', '부서진 해변은 만신창이가 된 적막한 땅이에요. 제가 이곳을 직접 보는 게 얼마나 필요한 일이었는지, 이제야 알겠어요.', '', 25549),
(130362, 'koKR', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t 몰락한 화신이 |cFFFF0404|Hspell:234418|h[파괴자의 비]|h|r를 시전합니다!', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t 몰락한 화신이 |cFFFF0404|Hspell:234418|h[파괴자의 비]|h|r를 시전합니다!', 25549),
(130360, 'koKR', '군단 암살자들이 죽었습니다. 당분간은 안전합니다.', '군단 암살자들이 죽었습니다. 당분간은 안전합니다.', 25549),
(130359, 'koKR', '', '용서하세요. 시간이 나면 설명해 드릴게요.', 25549),
(130358, 'koKR', '알레리아?', '', 25549),
(130357, 'koKR', '', '여긴 안전하지 않아요. 가야 해요. 당장요.', 25549),
(130356, 'koKR', '', '예언자님!', 25549),
(130355, 'koKR', '|TInterface\\Icons\\spell_hunter_lonewolf:20|t %s|1이;가; |cFFFF0404|Hspell:241772|h[기이한 울음]|h|r을 시전합니다!', '', 25549),
(130354, 'koKR', '|TInterface\\Icons\\SPELL_WARLOCK_SOULBURN:20|t%s|1이;가; 당신을 |cFFFF0000|Hspell:236011|h[고통의 외침]|h|r의 대상으로 지정합니다!', '', 25549),
(130351, 'koKR', '좋습니다! 부서진 섬 길잡이 제1부와 제2부, 그리고 최종 직업 탈것을 주십시오!', '좋습니다! 부서진 섬 길잡이 제1부와 제2부, 그리고 최종 직업 탈것을 주십시오!', 25549),
(130350, 'koKR', '거기요! 부서진 섬에서의 비행 테스트를 도와 주시지 않겠습니까?\n\n거래를 좀 더 재미있게 하는 차원에서, 제가 당신에게 직업 탈것 퀘스트를 드리겠습니다!\n\n어떻습니까?', '', 25549),
(130349, 'koKR', '이 차가운 배낭 마음에 든다! 하하!', '', 25549),
(130348, 'koKR', '오우거 얼음과자로군! 하!', '', 25549),
(130347, 'koKR', '하하! 어리석은 얼음 오우거 같으니.', '', 25549),
(130346, 'koKR', '정말 이것을 제작하시겠습니까? 이 방어구 제작자의 훈장으로는 단 하나의 전설 아이템만 제작할 수 있습니다.', '정말 이것을 제작하시겠습니까? 이 방어구 제작자의 훈장으로는 단 하나의 전설 아이템만 제작할 수 있습니다.', 25549),
(130345, 'koKR', '판금 허리띠를 만들고 싶습니다.\n|TINTERFACE\\ICONS\\INV_Plate_DraenorCrafted_D_01Buckle.blp:32|t\n|Hitem:146667:0:0:0:0:0:0:0:110:0|h[레투의 사그라들지 않는 용기]|h', '판금 허리띠를 만들고 싶습니다.\n|TINTERFACE\\ICONS\\INV_Plate_DraenorCrafted_D_01Buckle.blp:32|t\n|Hitem:146667:0:0:0:0:0:0:0:110:0|h[레투의 사그라들지 않는 용기]|h', 25549),
(130344, 'koKR', '사슬 장갑을 만들고 싶습니다.\n|TINTERFACE\\ICONS\\INV_GAUNTLETS_PLATE_RAIDPALADIN_I_01.BLP:32|t\n|Hitem:146668:0:0:0:0:0:0:0:110:0|h[경계의 홰]|h', '사슬 장갑을 만들고 싶습니다.\n|TINTERFACE\\ICONS\\INV_GAUNTLETS_PLATE_RAIDPALADIN_I_01.BLP:32|t\n|Hitem:146668:0:0:0:0:0:0:0:110:0|h[경계의 홰]|h', 25549),
(130343, 'koKR', '가죽 장화를 만들고 싶습니다.\n|TINTERFACE\\ICONS\\INV_Leather_RaidDemonHunterMythic_Q_02Boots.blp:32|t\n|Hitem:146669:0:0:0:0:0:0:0:110:0|h[파수꾼의 영원한 안식처]|h', '가죽 장화를 만들고 싶습니다.\n|TINTERFACE\\ICONS\\INV_Leather_RaidDemonHunterMythic_Q_02Boots.blp:32|t\n|Hitem:146669:0:0:0:0:0:0:0:110:0|h[파수꾼의 영원한 안식처]|h', 25549),
(130342, 'koKR', '재봉 어깨덧옷을 만들고 싶습니다.\n|TINTERFACE\\ICONS\\INV_SHOULDER_CLOTH_RAIDWARLOCK_L_01.BLP:32|t\n|Hitem:146666:0:0:0:0:0:0:0:110:0|h[셀럼브라 - 밤의 두 얼굴]|h', '재봉 어깨덧옷을 만들고 싶습니다.\n|TINTERFACE\\ICONS\\INV_SHOULDER_CLOTH_RAIDWARLOCK_L_01.BLP:32|t\n|Hitem:146666:0:0:0:0:0:0:0:110:0|h[셀럼브라 - 밤의 두 얼굴]|h', 25549),
(130341, 'koKR', '가장 중요한 부분으로 넘어가세. 자네가 제작하고자 하는 방어구의 종류를 선택해야 하네. 고심해서 선택하게나. 자네의 훈장으로는 한 가지 가르침만 얻을 수 있으니.', '', 25549),
(130338, 'koKR', '나머지는 다들 대학으로 돌아갑시다. 아무래도 앞으로 수백 년은 더 가르침을 받아야 할 것 같으니까요.', '', 25549),
(130337, 'koKR', '', '으음... 제대로 된 각인사는 정말 좋다니까. 자주 부르렴.', 25549),
(130336, 'koKR', '그대는 보상을 받으실 자격이 있습니다! 자, 그대에게 도움이 되면 좋겠군요.', '', 25549),
(130335, 'koKR', '엘룬의 축복을! 영웅이여, 고맙습니다!', '', 25549),
(130334, 'koKR', '예쁜 새야, 반짝이는 금화가 갖고 싶니?', '예쁜 새야, 반짝이는 금화가 갖고 싶니?', 25549),
(130333, 'koKR', '물건 좀 보여주실래요?', '물건 좀 보여주실래요?', 25549),
(130332, 'koKR', '', '오오, 각인사인가? 나는 누군가 날 구속하는 계약서를 쓸 때가 가장 좋더구나. 난 알고 있는 비밀이 좀 있지. 아주 어두운 비밀 말이야.\n\n넌 입이 가벼운 편인가? 난 그런데.', 25549),
(130331, 'koKR', '자유는 나의 것이다! 엘프여, 날 모욕한 대가를 혹독히 치르게 될 것이다!', '', 25549),
(130319, 'koKR', '', '<그냥 자꾸 윙크를 합니다.>', 25549),
(130316, 'koKR', '', '으으... 너무 추워. 친절한 네가 몸에 불을 질러 날 따뜻하게 해주지 않겠어?', 25549),
(130314, 'koKR', '', '네가 가진 그 도덕심이란 거, 맛있어 보이는구나.', 25549),
(130312, 'koKR', '', '아, 너 좀 귀엽구나. 하지만 안타깝게도 난 이미 계약에 묶인 몸이야.', 25549),
(130311, 'koKR', '', '흐으으으음...? 흐으으으음.', 25549),
(130292, 'koKR', '아, 예, 그게 어디 있는지 잘 기억합니다. 카라잔이 무너지기 전에, 카드가와 전 제 성소에서 원반에 대한 연구를 조금 진행했습니다. 안타깝게도 시간이 많지 않아 원반에 대해 많을 걸 알아내진 못했지만요.$b$b평소에는 제 성소로 이동하는 게 어려운 일이 아니지만, 지금은 성소로 통하는 차원문으로 가는 길을 지하실에 있는 악마들이 막고 있습니다.$b$b놈들을 처치하고 지하실 끝으로 가면 차원문이 보일 겁니다. 삼각 원반은 아직 성소에 있을 겁니다.', '', 25549),
(130281, 'koKR', '화염의 삼각 원반에 대한 정보를 얻고자 이곳에 왔습니다.', '화염의 삼각 원반에 대한 정보를 얻고자 이곳에 왔습니다.', 25549),
(130257, 'koKR', '부디, 작은 보답을 받아 주십시오.', '부디, 작은 보답을 받아 주십시오.', 25549),
(130256, 'koKR', '그대에게 축복을! 당신 덕분에 살았습니다!', '그대에게 축복을! 당신 덕분에 살았습니다!', 25549),
(130255, 'koKR', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s|1이;가; |cFFFF0000|Hspell:233983|h[메아리치는 고뇌]|h|r를 시전합니다!', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s|1이;가; |cFFFF0000|Hspell:233983|h[메아리치는 고뇌]|h|r를 시전합니다!', 25549),
(130254, 'koKR', '잠깐 기다리게, $n. 먼저 만들고 있던 방어구를 마무리하는 게 좋겠어.', '', 25549),
(130253, 'koKR', '그래! 좋아, 이제 시작하자고. 자네가 늘 꿈꿔 왔던 전설 방어구 만드는 방법을 가르쳐 주겠네!', '', 25549),
(130252, 'koKR', '방어구 제작자의 훈장을 가져왔습니다.', '방어구 제작자의 훈장을 가져왔습니다.', 25549),
(130250, 'koKR', '실험 중...', '', 25549),
(130249, 'koKR', '용사여, 시간이 됐네. 아르거스로 가세.', '', 25549),
(130248, 'koKR', '엑소다르에 오신 것을 환영합니다, $p 님.', '', 25549),
(130247, 'koKR', '어서 가지.', '', 25549),
(130244, 'koKR', '정체가 발각되어 암살자들이 파견됐습니다.', '정체가 발각되어 암살자들이 파견됐습니다.', 25549),
(130243, 'koKR', '', '정말 고마워요! 이 상자를 받아 주세요. 그럴 자격이 있으니까요!', 25549),
(130242, 'koKR', '', '도와줘요! 놈들이 제 물자를 빼앗아 가려고 해요!', 25549),
(130241, 'koKR', '소로스 님은... 패배하지 않아...', '', 25549),
(130240, 'koKR', '공포마는 내 거다, 흑마법사여... 내 거!', '', 25549),
(130239, 'koKR', '박살내 주마, 이 벌레야!', '', 25549),
(130238, 'koKR', '건방진 짓거리의 대가를 치르게 될 거다, 흑마법사!', '', 25549),
(130237, 'koKR', '', '우리 숲을 침공해 온 괴물들에 맞서 싸우고 계시다는 건 알겠어요. 하지만 물 그 자체에서 더... 끈적이는 타락을 추출해 낼 수 있다면, 그 또한 놀라운 위업이 될 거예요! 낚싯대를 이용해 보시는 게 좋겠어요.', 25549),
(130236, 'koKR', '', '<손을 뻗어 물방울을 받았지만, 불쾌한 표정으로 고개를 돌리는 레이내>\n\n고마워요. 기꺼이 박살내 주겠어요.', 25549),
(130235, 'koKR', '', '타락 때문에 물의 숨이 막혔고, 한때 이곳에 번성했던 생태계도 모두 붕괴되고 말았어요. 맞서 싸워야 해요!', 25549),
(130234, 'koKR', '', '아! 가장 중요한 걸 말씀드릴게요. 잉어의 수가 너무 많아지고 있어요. 작은 물고기 몇 마리만 잡아주시면, 제가 강에 풀어놓을게요.\n\n그리고, 부디 수족관 관리인 매지쿠스를 조심하세요.', 25549),
(130233, 'koKR', '', '훌륭해요! 이제 물고기들을 제 마력 깃든 물방울에 넣어주시면, 제가 알아서 할게요.\n\n<샬레스는 작은 물고기들을 보는 데 정신이 팔린 듯합니다.>', 25549),
(130232, 'koKR', '', '추방되기 전, 저는 도시 수족관의 관리자였어요. 수족관 안의 생명들을 관리하는 건 여전히 제 책임이고, 그 아이들을 버릴 순 없어요!', 25549),
(130231, 'koKR', '코르빈이 발치의 반짝이는 조약돌을 본 다음, 물을 바라봅니다. 낚싯대로 건져 줘야겠다는 느낌이 듭니다.', '', 25549),
(130230, 'koKR', '코르빈이 기쁨으로 까악 거립니다.', '', 25549),
(130229, 'koKR', '까마귀가 당신을 바라보더니 고개를 갸웃합니다.', '', 25549),
(130228, 'koKR', '전 산산조각 난 그 토템의 수백, 어쩌면 수천 개의 조각들을 수집하고 있습니다. 낚시대로 그 조각을 건지는 행운이 당신에게 따를지도 모릅니다.', '', 25549),
(130227, 'koKR', '<조각들을 조심스럽게 살펴보는 아쿨레>\n\n맞습니다, 원래 토템의 일부가 맞습니다. 감사합니다, $c|1이여;여;.', '', 25549),
(130226, 'koKR', '오래 전에 의식 토템 하나가 번개를 맞고 산산조각이 되어 이 물속으로 사라졌습니다. 전 토템을 새로 만들어 선조들을 기리고자 합니다.', '', 25549),
(130225, 'koKR', '낚싯대로 해초 낚아라! 해초 임푸스에게 줘라! 대가는 없다!', '', 25549),
(130224, 'koKR', '임푸스는 하수인 솜씨가 마음에 든다.', '', 25549),
(130223, 'koKR', '안녕히.', '', 25549),
(130221, 'koKR', '임푸스가 배 만들고 있다. 너 도와라!', '', 25549),
(130220, 'koKR', '고맙다, 친구! 보답으로 내 힘을 조금 나눠 주지. 우리 적을 상대하는 데 도움이 되길 빈다.', '', 25549),
(130219, 'koKR', '', '내 화살은 반드시 목표를 찾지!', 25549),
(130218, 'koKR', '', '내 연사를 피할 순 없다!', 25549),
(130217, 'koKR', '내가 놈의 관심을 끌 테니 공격을 집중해.', '', 25549),
(130216, 'koKR', '나르탈라스를 위하여!', '나르탈라스를 위하여!', 25549),
(130215, 'koKR', '굳건히 버텨라, 어둠감시자들이여! 적이 다가온다!', '굳건히 버텨라, 어둠감시자들이여! 적이 다가온다!', 25549),
(130214, 'koKR', '반두 토리바스!', '반두 토리바스!', 25549),
(130213, 'koKR', '어둠감시자는 절대로 의무를 저버리지 않는다!', '어둠감시자는 절대로 의무를 저버리지 않는다!', 25549),
(130212, 'koKR', '무장하라, 어둠감시자여! 군단이 온다!', '무장하라, 어둠감시자여! 군단이 온다!', 25549),
(130211, 'koKR', '모두 죽여라!', '', 25549),
(130210, 'koKR', '아, 맙소사! 이런 건 수업 계획에 없었는데!', '', 25549),
(130209, 'koKR', '저와 모험하시겠습니까... 영원히?', '', 25549),
(130208, 'koKR', '서두르십시오! 영원토록 기다릴 수만은 없습니다!', '', 25549),
(130207, 'koKR', '거기 그대가 그 주문을 어떻게 시전하는지 시범을 보여 주십시오.', '', 25549),
(130206, 'koKR', '자, 지난 번 수업 시간에 졸지 않았다면, 이 악마가 불덩이가 되어 폭발하게 만들 수 있는 주문을 알고들 있을 겁니다.', '', 25549),
(130205, 'koKR', '걱정하지 마십시오, 학생 여러분. 이 악마는 비전 행렬 안에 완벽하게 갇혀 있습니다.', '', 25549),
(130204, 'koKR', '어... 그 주문, 어떻게 하는 거였더라? 루 샬로라... 음... 수리수리 마수리?', '어... 그 주문, 어떻게 하는 거였더라? 루 샬로라... 음... 수리수리 마수리?', 25549),
(130203, 'koKR', '강사님, 아무래도...', '강사님, 아무래도...', 25549),
(130201, 'koKR', '<차원문이 마력으로 고동칩니다. 비명과 또 다른 거북한 소음이 반대쪽에서 들려옵니다.>\n\n황천의 파편을 더 모은 후에 다시 돌아와야 합니다.', '', 25549),
(130200, 'koKR', '', '고마워요, $n 님! 딱 제가 찾던 거였어요.', 25549),
(130199, 'koKR', '멋의 대제전에 가고 싶습니다!', '멋의 대제전에 가고 싶습니다!', 25549),
(130198, 'koKR', '', '정말 예쁘지 않아요? 그 힘이 몸속을 흐르고 맥동하며, 우리 주위의 세상을 혼란시키는 것이 느껴지나요? 당신이 바란다면 그 힘을 내 뜻대로 부릴 수 있죠...', 25549),
(130197, 'koKR', '', '보호 마법이 조각나서 효과가 떨어지기 시작했어요. 이런 제안을 해서 마음 아프지만, 당신이라면 조각들을 낚싯대로 건져낼 수 있을 것 같아요.', 25549),
(130196, 'koKR', '무엇을 원하는가?', '', 25549),
(130195, 'koKR', '도움이 필요한가요?', '도움이 필요한가요?', 25549),
(130194, 'koKR', '용사 님, 파론디스 왕자님께서 전해주신 선물을 드릴게요. 제 주문은 당신을 한동안 더 강하고, 빠르고, 힘이 넘치게 만들 것입니다. 다가와서 축복을 받으세요.', '용사 님, 파론디스 왕자님께서 전해주신 선물을 드릴게요. 제 주문은 당신을 한동안 더 강하고, 빠르고, 힘이 넘치게 만들 것입니다. 다가와서 축복을 받으세요.', 25549),
(130193, 'koKR', '용사님께 에이르 님의 축복이 있길! 다가와서 그녀의 축복을 받으세요.', '용사님께 에이르 님의 축복이 있길! 다가와서 그녀의 축복을 받으세요.', 25549),
(130192, 'koKR', '죄송합니다. 그건 안 되겠네요...', '죄송합니다. 그건 안 되겠네요...', 25549),
(130191, 'koKR', '그러겠습니다!', '그러겠습니다!', 25549),
(130190, 'koKR', '저도 당신에 대해 똑같은 꿈을 꿨습니다!', '저도 당신에 대해 똑같은 꿈을 꿨습니다!', 25549),
(130189, 'koKR', '꼭 찾으시길 바랍니다.', '꼭 찾으시길 바랍니다.', 25549),
(130188, 'koKR', '...', '...', 25549),
