INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(123154, 'koKR', '야수 부르기를 사용하여 야수를 불러내십시오.', '', 25549),
(123152, 'koKR', '믿음직스러운 야수와 함께하는 당신은 환경의 지배자입니다. 야수 부르기를 사용하면 야수가 소환됩니다.', '', 25549),
(123151, 'koKR', '생존 사냥꾼은 근접 전투에 뛰어나며, 다양한 도구를 사용하여 난폭하게 사냥감을 제압합니다.', '', 25549),
(123150, 'koKR', '생존 사냥꾼은 근접 전투에 뛰어나며, 다양한 도구를 사용하여 난폭하게 사냥감을 제압합니다.', '', 25549),
(123149, 'koKR', '시간이 너무 없어! 이런 상황에서 어떻게 일을 하라고!', '시간이 너무 없어! 이런 상황에서 어떻게 일을 하라고!', 25549),
(123148, 'koKR', '이런 속도라면 페인트가 더 필요하겠어.', '이런 속도라면 페인트가 더 필요하겠어.', 25549),
(123147, 'koKR', '', '파론디스와는 화해할 수 없어요... 이 저주가 남아 있는 한!', 25549),
(123146, 'koKR', '', '우리의 저주는 파론디스 책임이에요... 대가를 치러야 해요!', 25549),
(123145, 'koKR', '주술의 분노를 사용하십시오!', '', 25549),
(123144, 'koKR', '', '주술의 분노를 사용하십시오!', 25549),
(123143, 'koKR', '메마른 자들을 뒤에 남겨 놓으면 길을 잃고 말 것입니다!', '메마른 자들을 뒤에 남겨 놓으면 길을 잃고 말 것입니다!', 25549),
(123142, 'koKR', '방문객 여러분께 알립니다. 죽어! 죽어! 죽어!', '', 25549),
(123141, 'koKR', '제거 완료!', '', 25549),
(123140, 'koKR', '과부하 발생. 준비- 척결하라! 척결하라!', '', 25549),
(123139, 'koKR', '관리인... 작동... 중지.', '', 25549),
(123138, 'koKR', '박물관을 안내... 제거하라! 제거하라!', '', 25549),
(123135, 'koKR', '비전주가 상했습니다... 다시 시작해야 합니다!', '비전주가 상했습니다... 다시 시작해야 합니다!', 25549),
(123134, 'koKR', '피의 향기가 바람에 실려 오는군.', '이게 당신 함선이오, $n. 빛이 당신과 함께하길.', 25549),
(123133, 'koKR', '부서진 해변 도입부를 건너뛰시겠습니까?\n이 퀘스트는 부서진 섬의 달라란에 있는 기록관 엘리시아나에게서 다시 받을 수 있습니다.', '부서진 해변 도입부를 건너뛰시겠습니까?\n이 퀘스트는 부서진 섬의 달라란에 있는 기록관 엘리시아나에게서 다시 받을 수 있습니다.', 25549),
(123132, 'koKR', '이 이야기는 전에 들어 본 적이 있습니다... <군단 도입부를 건너뛰고 달라란에서 모험을 시작합니다.>', '이 이야기는 전에 들어 본 적이 있어요... <군단 도입부를 건너뛰고 달라란에서 모험을 시작합니다.>', 25549),
(123126, 'koKR', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t 오딘이 룬을 대상으로 |cFFFF0404|Hspell:227503|h[마력 끌어내기]|h|r를 시작합니다!', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t 오딘이 룬을 대상으로 |cFFFF0404|Hspell:227503|h[마력 끌어내기]|h|r를 시작합니다!', 25549),
(123124, 'koKR', '', '가롫아옳.', 25549),
(123123, 'koKR', '', '아옳가롫롫.', 25549),
(123122, 'koKR', '', '아옳옳옳가롫롫롫아옳.', 25549),
(123121, 'koKR', '믿기 힘든 얘기군. 농담은 아니겠지?', '', 25549),
(123120, 'koKR', '', '아옳아옳.', 25549),
(123119, 'koKR', '그래, 지금껏 경험해 본 적 없는 일이 일어날 줄 알고 있었어. 그래도 이건 너무 엄청난데.', '', 25549),
(123118, 'koKR', '', '가롫롫롫롫롫롫.', 25549),
(123117, 'koKR', '아니, 전에 만난 적이 있던가?', '', 25549),
(123116, 'koKR', '', '아옳옳옳옳.', 25549),
(123115, 'koKR', '날 다른 사람으로 착각한 거 아냐?', '', 25549),
(123114, 'koKR', '그만! 너희 가치는 증명됐다! 너희가 내 용사가 되면, 헬리아는 쓰러지고 나는 마침내 날 구속한 저주에서 풀려날 거다!', '', 25549),
(123113, 'koKR', '저승바람 고개 위 달라란으로 가서 도움을 드릴 수 없겠습니다. 부서진 섬에 있는 달라란으로 바로 순간이동시켜 주십시오.', '저승바람 고개 위 달라란으로 가서 도움을 드릴 수 없겠어요. 부서진 섬에 있는 달라란으로 바로 순간이동시켜 주세요.', 25549),
(123112, 'koKR', '군단이 저승바람 고개 위의 달라란을 공격하고 있고, 공격의 강도가 심상치 않소.\n\n내가 이곳의 의식을 끝내는 대로 우리 다시 부서진 섬 상공에서 만나는 게 어떻겠소?', '', 25549),
(123111, 'koKR', '', '난 친구가 하나도 없어... 아, 너만 빼고 말이야, 갈린더.', 25549),
(123110, 'koKR', '', '누구나 하늘을 날 수 있어야 해! 근데, 마법사가 정말 날 초록색에서 벗어나게 할 수 있을까?', 25549),
(123109, 'koKR', '', '물론이지! 그런데 그 낡은 드레스는... 아, 저기 봐! 새로운 친구들이 찾아왔어.', 25549),
(123108, 'koKR', '', '엘피라, 이리 내려와! 저 끔찍한 원숭이 생물들처럼 날아다니면 어떡해!', 25549),
(123106, 'koKR', '준비되면 전투를 시작해라, 영웅들이여!', '', 25549),
(123105, 'koKR', '하임달! 히리아! 이 필멸자들의 힘을 시험해라. 앞으로의 일을 견뎌낼 수 있는 용기와 실력이 있는지 확인해야 한다.', '', 25549),
(123104, 'koKR', '용사들아! 너흰 헬리아의 하수인들의 피를 쏟았다. 이제 헬하임으로 직접 들어가, 그 바다 마녀의 공포 통치를 끝내야 한다. 하지만 그 전에... 최후의 시험이다!', '', 25549),
(123103, 'koKR', '잘했다... 지금까지는 말이야! 너희 가치는 내가 직접 심판해 주마!', '', 25549),
(123102, 'koKR', '너무 상냥하게 대해 준 모양이군. 이제부터 시작이다!', '', 25549),
(123101, 'koKR', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t%s|1이;가; |cFFFF0000|Hspell:227508|h[대규모 참회]|h|r를 시전합니다!', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t%s|1이;가; |cFFFF0000|Hspell:227508|h[대규모 참회]|h|r를 시전합니다!', 25549),
(123100, 'koKR', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t%s|1이;가; |cFFFF0000|Hspell:227789|h[신성한 대지]|h|r를 당신에게 시전합니다!', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t%s|1이;가; |cFFFF0000|Hspell:227789|h[신성한 대지]|h|r를 당신에게 시전합니다!', 25549),
(123099, 'koKR', '|cffADFF2F나이트폴른 평판 +$1i|r', '|cffADFF2F나이트폴른 평판 +$1i|r', 25549),
(123098, 'koKR', '놈들과 싸울 다른 방법을 찾아야 해.', '', 25549),
(123097, 'koKR', '아제로스에서 행군하는 병력은, 군단의 진짜 힘에 비하면 새발의 피야.', '', 25549),
(123096, 'koKR', '', '실패했습니다, 살게라스 님...', 25549),
(123095, 'koKR', '갈라지는 게 좋겠소. 나는 탑의 마법 방어를 우회하는 방법을 찾을 테니, 당신은... 물리력에 치중하는 방법을 찾으시오.', '', 25549),
(123078, 'koKR', '빨리 죽여 주마, 침입자여.', '빨리 죽여 주마, 침입자여.', 25549),
(123077, 'koKR', '이미 수백을 죽였다. 네가 죽어 봐야 내 허리띠의 표시가 하나 늘어날 뿐이야.', '이미 수백을 죽였다. 네가 죽어 봐야 내 허리띠의 표시가 하나 늘어날 뿐이야.', 25549),
(123076, 'koKR', '나머지 놈들의 피처럼, 네 피로 내 칼을 적셔 주지!', '나머지 놈들의 피처럼, 네 피로 내 칼을 적셔 주지!', 25549),
(123075, 'koKR', '너희는 여기서 환영받지 못해!', '너희는 여기서 환영받지 못해!', 25549),
(123074, 'koKR', '이 세상에 네 자리는 없다, 악마야!', '이 세계에 네 자리는 없다, 악마야!', 25549),
(123073, 'koKR', '더는 못 간다, 침입자야!', '더는 못 간다, 침입자야!', 25549),
(123072, 'koKR', '이 순간을 위해 훈련했다!', '이 순간을 위해 훈련했다!', 25549),
(123071, 'koKR', '침입자다! 경보를 울려!', '침입자다! 경보를 울려!', 25549),
(123069, 'koKR', '', '정말 엉망진창이네!', 25549),
(123068, 'koKR', '', '평생 처음으로, 기분이... 우낏해.', 25549),
(123067, 'koKR', '', '우낏한 머리가 어떻게 되기라도 한 거야?', 25549),
(123066, 'koKR', '', '쟨 좀 꾸미고 다니지.', 25549),
(123065, 'koKR', '', '엘레카모멘 오툰분투 로투 켈라라멘!', 25549),
(123064, 'koKR', '', '와서 내 하수인들의 소리를 들어 봐!', 25549),
(123063, 'koKR', '', '너도 하늘을 날아 보렴!', 25549),
(123062, 'koKR', '', '쓰러뜨려서 미안해!', 25549),
(123061, 'koKR', '', '나만 따라하면, 너도 유명해질 거야!', 25549),
(123060, 'koKR', '', '함께라면 우리에게 한계는 없어!', 25549),
(123055, 'koKR', '', '|TInterface\\Icons\\spell_arcane_arcanetorrent_nightborne:20|t갈린더가 |cFFFF0404|Hspell:227776|h[매우 멋진 마법]|h|r을 시전합니다! |TInterface\\Icons\\spell_priest_void blast:20|t|cFFFF0404|Hspell:227405|h[중력을 벗어나]|h|r의 소용돌이를 사용하여 피하십시오!', 25549),
(123054, 'koKR', '시작하시죠.', '시작하시죠.', 25549),
(123053, 'koKR', '', '시작할 준비는 되셨습니까?', 25549),
(123052, 'koKR', '저 사악한 노파 말이냐? 최악은 아니다. 더 끔찍한 마녀가 있었거든.', '', 25549),
(123051, 'koKR', '오늘 밤 아주 화끈한 공연이 펼쳐진다. 아주 우끼끼한 이야기지.', '', 25549),
(123050, 'koKR', '주둥이 닫아라, 시끄러운 녀석아! 원숭이 왕께 다른 계획이 있다 이거야!', '', 25549),
(123049, 'koKR', '신사 숙녀 여러분, 우리 공연에 잘-- 우욱!', '', 25549),
(123048, 'koKR', '임무가 뭔지 알려 주십시오.', '임무가 뭔지 알려 주십시오.', 25549),
(123047, 'koKR', '', '당신만 믿고 있어요, $n.', 25549),
(123046, 'koKR', '', '정말 아름다운... 비극이야.', 25549),
(123045, 'koKR', '', '이곳도 갈린더에게 어울리게 변해야겠지!', 25549),
(123044, 'koKR', '', '이제 아주 멋진 걸 보여줄까!', 25549),
(123043, 'koKR', '%s의 별자리가 만료되어 거대한 삼위 일체 효과가 발동합니다!', '%s의 별자리가 만료되어 거대한 삼위 일체 효과가 발동합니다!', 25549),
(123042, 'koKR', '%s|1과;와; $n|1이;가; 충돌하여 거대한 삼위 일체 효과가 발동합니다!', '%s|1과;와; $n|1이;가; 충돌하여 거대한 삼위 일체 효과가 발동합니다!', 25549),
(123040, 'koKR', '|cFFFF0404|Hspell:211901|h[융합 압착 장치]|h|r의 피해를 피하려면 뛰어 넘으십시오!', '|cFFFF0404|Hspell:211901|h[융합 압착 장치]|h|r의 피해를 피하려면 뛰어 넘으십시오!', 25549),
(123039, 'koKR', '<돈부리에 탑니다.>', '<돈부리에 탑니다.>', 25549),
(123038, 'koKR', '<당신을 조심스레 쳐다보는 돈부리>', '', 25549),
(123037, 'koKR', '사랑은 본능적 반응에서 생겨난 구닥다리 이상주의적 생각이지!', '사랑은 본능적 반응에서 생겨난 구닥다리 이상주의적 생각이지!', 25549),
(123036, 'koKR', '우편물실로 돌아갈 순 없지!', '우편물실로 돌아갈 순 없지!', 25549),
(123035, 'koKR', '월급도 쥐꼬리만큼 받는데 싸움까지 해야 돼?!', '월급도 쥐꼬리만큼 받는데 싸움까지 해야 돼?!', 25549),
(123033, 'koKR', '차원문 반대쪽에서 어떤 감당할 수 없는 존재가 한 순간 당신과 접촉하는 것이 느껴집니다...', '차원문 반대쪽에서 어떤 감당할 수 없는 존재가 한 순간 당신과 접촉하는 것이 느껴집니다...', 25549),
(123030, 'koKR', '비행 조련사의 호루라기가 또 있습니까?', '비행 조련사의 호루라기가 또 있나요?', 25549),
(123029, 'koKR', '101 레벨 미만 캐릭터만 군단 침공에 참여할 수 있습니다.', '101 레벨 미만 캐릭터만 군단 침공에 참여할 수 있습니다.', 25549),
(123028, 'koKR', '|TInterface\\Icons\\ability_mage_arcanebarrage_nightborne:20|t당신은 |cFFF00000|Hspell:220871|h[불안정한 마나]|h|r의 대상이 되었습니다!', '', 25549),
(123027, 'koKR', '저 괴수를 처치하려면 투기장 안으로 뛰어들어야 한다. 어머니 달이여, 힘을 주소서.', '', 25549),
(123026, 'koKR', '칠흑의 기사단은 영원할 것입니다. 그 누구도 우리 앞을 가로막고... 살아남진 못합니다.', '', 25549),
(123024, 'koKR', '대지 고리회가 함께합니다, 선견자여! 어떤 대가를 치르더라도 불타는 군단에 맞서 당신와 함께하겠습니다!', '', 25549),
(123023, 'koKR', '암흑의 수확 병력을 모집하고 싶습니다.', '암흑의 수확 병력을 모집하고 싶어요.', 25549),
(123021, 'koKR', '들어갑시다!', '들어가요!', 25549),
(123020, 'koKR', '투영관에 들어갈 준비가 됐나?', '', 25549),
(123019, 'koKR', '카라잔으로 갈 준비가 됐습니다.', '카라잔으로 갈 준비가 됐어요.', 25549),
(123018, 'koKR', '카드가와 함께 가서 창조의 근원들을 찾아내야 하네, $n!', '', 25549),
(123017, 'koKR', '마그니 님을 구합시다!', '마그니 님을 구하러 가요!', 25549),
(123016, 'koKR', '이제 이 방벽을 해제해도 되겠소?', '', 25549),
(123014, 'koKR', '브란 브론즈비어드? 이런, 놀랄 일이군.', '', 25549),
(123013, 'koKR', '우리에게 시간을 주시오, $n.$b$b군단으로부터 이 도시를 보호하고, 지도를 보며 적의 침공을 막아야 할 지점을 확인하시오.$b$b때가 되면 다시 당신을 부르겠소.', '', 25549),
(123012, 'koKR', '저도 어떻게든 돕겠습니다. 키린 토를 돕게 되어 영광입니다.', '', 25549),
(123011, 'koKR', '', '이렇게 짧은 기간 동안 달라란을 두 번이나 움직이는 건 전례가 없는 일이에요.', 25549),
(123010, 'koKR', '힘을 비축해야 하오. 이 도시를 움직이는 주문은 상당히 버거우니까.', '', 25549),
(123009, 'koKR', '이제 다른 방문객들을 맞이해야겠습니다. 행운을 빕니다, $n 님!', '', 25549),
(123008, 'koKR', '당신의 대장정에 도움이 될 강력한 유물이 있다는 소문을 들었습니다. 뭔가 실마리가 나타날 수도 있으니, 항상 주위를 살피십시오!', '', 25549),
(123007, 'koKR', '달라란의 모든 자원을 마음껏 사용하셔도 좋습니다. 이곳에서부터 얼라이언스와 호드의 영웅들이 함께 창조의 근원을 찾아낼 겁니다!', '', 25549),
(123006, 'koKR', '', '|TInterface\\Icons\\Spell_Shadow_Possession:20|t %s|1이;가; |cFFFF0000|Hspell:227233|h[타락한 고함]|h|r을 시전합니다. 조심하십시오!', 25549),
(123005, 'koKR', '한번 사냥해 봐라...', '', 25549),
(123004, 'koKR', '안녕히... 행운을 빕니다. 다음에 놈들을 만나면 목숨을 잘 구걸해 보십시오.', '', 25549),
(123003, 'koKR', '겁쟁이가 이끄는 한 우린 군단에게 승리할 수 없습니다.', '', 25549),
(123002, 'koKR', '어리석은 바보 같으니, 레이븐크레스트! 상관 없습니다. 배울 건 모두 배웠으니.', '', 25549),
(123001, 'koKR', '내 행동을 비판하는 것 말고 뭘 할 수 있습니까? 내 마법사들은 이 세계를 지키며 죽어갔습니다. 당신은 뭘 바쳤습니까? 뭘 희생했습니까?', '', 25549),
(123000, 'koKR', '단 한 번의 침공으로, 모두가 죽고 수라마르를 빼앗길 뻔했습니다.', '', 25549),
(122999, 'koKR', '우린 적어도 뭐요? 당신은 눈이 멀었습니다, 레이븐크레스트 경!', '', 25549),
(122998, 'koKR', '항상 선택의 길은 있다! 우린 적어도...', '', 25549),
(122997, 'koKR', '제가 어떻게 해야 합니까, 쿠르탈로스 경? 군단 대군주가 우리 세계를 잿더미로 만드는데, 웃으며 받아들여야 합니까?', '', 25549),
(122996, 'koKR', '저 괴물들보다 우리가 나을 게 없는 걸까요?', '', 25549),
(122995, 'koKR', '이토록 야만적이라니...', '', 25549),
(122994, 'koKR', '이럴 수가!', '', 25549),
(122993, 'koKR', '일리단, 안 돼!', '', 25549),
(122992, 'koKR', '어머니 달이시여, 저를 용서하시길...', '', 25549),
(122991, 'koKR', '어떻게든 해라, 일리단! 놈이 우릴 짓밟고 있다! 더는 견딜 수 없어!', '', 25549),
(122990, 'koKR', '내 모든 것을 던져 이 생물을 공격했지만 소용이 없다. 달빛 수호자에게 마지막으로 도움을 청해야겠어.', '', 25549),
(122989, 'koKR', '우리도 투기장 안으로 합류하겠다! 스톰레이지 대장, 돌진해라!', '', 25549),
(122988, 'koKR', '일리단이 궁정을 차지했다! 탑경비대, 전진!', '', 25549),
(122987, 'koKR', '나는 전 우주에서 가장 강한 마법사사냥꾼이다! 넌 내 상대가 아니다, 꼬마 엘프야!', '', 25549),
(122986, 'koKR', '훈련이 더 필요한가?', '', 25549),
(122985, 'koKR', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t%s|1이;가; |cFFFF0000|Hspell:199193|h[공포의 군주의 간계]|h|r를 시전합니다!', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t%s|1이;가; |cFFFF0000|Hspell:199193|h[공포의 군주의 간계]|h|r를 시전합니다!', 25549),
(122984, 'koKR', '', '걱정 말거라, 꼬마야. 난 너의 대족장이니.', 25549),
(122983, 'koKR', '', '이제 난 호드를 대표한다.', 25549),
(122982, 'koKR', '', '난 괜찮다, 대사. 꼬마야, 대족장의 짐은 가벼운 게 아니다. 하지만 난 그 짐을 짊어지기로 결정했지.', 25549),
(122981, 'koKR', '고아원에 있는 친구가 그랬어요. 당신은 항상 호드보다 포세이큰이 우선이어서, 우릴 버릴 거라고요. 정말이에요?', '', 25549),
(122980, 'koKR', '시작할 준비가 되면 내게 말하시오, $n.', '', 25549),
(122979, 'koKR', '고맙구나, 꼬마야. 네 말이 맞았으면 좋겠구나.', '', 25549),
(122978, 'koKR', '그분은 그냥 귀한 보석이 아니란다. 우리의 국왕이시지.', '', 25549),
(122977, 'koKR', '그분은 없단다, 꼬마야. 더 큰 일을 하러 떠나셨지.', '', 25549),
(122976, 'koKR', '어쨌든 그분은 다이아몬드니까 괜찮을 거예요. 다이아몬드는 강하잖아요!', '', 25549),
(122975, 'koKR', '다이아몬드가 혼자 걸어갔다고요?', '', 25549),
(122974, 'koKR', '그 큰 다이아몬드 어디 갔어요?', '', 25549),
(122973, 'koKR', '서둘러 찾아야 하네. 창조의 근원이 군단의 손에 들어가면, 우리 세계가 말로는 표현할 수 없는 파괴를 맞이해야 할 수도 있어. 행운을 빌겠네.', '', 25549),
(122972, 'koKR', '감사합니다, 수호자님. 다시 한 번 아제로스를 위해 봉사해 주셨군요.', '', 25549),
(122971, 'koKR', '', '그 정도면 어디부터 시작해야 할지는 알겠네요. 부서진 섬을 구석구석 찾아보겠습니다.', 25549),
(122970, 'koKR', '알았네. 그 당시에 나는 부서진 섬까지 그 유물들을 추적했었네. 정확한 위치는 찾아내지 못했지만, 그 고대의 땅 주민들의 손에 남아 있을 거라고 믿네.', '', 25549),
(122969, 'koKR', '반드시 그 유물들을 찾아내야 합니다. 살게라스의 무덤에 있는 군단의 차원문을 봉인할 수 있는 건 바로 그 창조의 근원뿐입니다.', '', 25549),
(122968, 'koKR', '당연하지! 창조의 근원은 태고의 힘을 상징하네. 수호자라고 해도 감히 함부로 다룰 수 없는 힘이지.', '', 25549),
(122967, 'koKR', '', '저희는 지금 창조의 근원이라는 고대 유물 다섯 개를 찾고 있습니다. 책에는 그 유물을 정확히 어디에서 찾아야 할지는 안 나와 있더군요. ', 25549),
(122966, 'koKR', '스톰하임이 보이지 않는 게 아쉽네.', '', 25549),
(122965, 'koKR', '내 책을 읽었다고? 젊은이들은 이제 책 같은 건 안 읽는 줄 알았는데... 시답잖은 놀이나 하고, 만날 모험, 모험만 찾고...', '', 25549),
(122964, 'koKR', '불타는 군단이 돌아왔습니다. 놈들을 막기 위해, 우린 카라잔의 도서관에서 당신이 쓰신 ''고대 아제로스의 주목할 만한 골동품''이라는 책을 찾았습니다.', '', 25549),
(122963, 'koKR', '내가 아는 얼굴이군. 내가 처음 짊어졌던 책임을 거부한 수련생 아닌가. 왜 나를 부른 거지?', '', 25549),
(122962, 'koKR', '안녕하십니까, 알로디 님. 전 키린 토의 대마법사 카드가라고--', '', 25549),
(122961, 'koKR', '소환이라니! 누군가 내게 도움을 청한 지도 참 오랜 세월이 흘렀구나.', '', 25549),
(122960, 'koKR', '첫 번째 수호자의 영혼을 소환하겠소!', '', 25549),
(122959, 'koKR', '마력이 거의 떨어졌다. 차원문을 찾아 쉬거나, 달빛 수호자의 정수를 흡수해야 한다.', '', 25549),
(122958, 'koKR', '이런 힘은 처음이다... 이런 고통도...', '', 25549),
(122957, 'koKR', '니힐람 차원문은 발라두르라는 에레다르가 지키고 있다. 놈에게 평범한 주문은 아무 쓸모가 없어. 우주의 격노를 방출해 차원문을 파괴해야 한다. 그러면 나와 그 악마 간의 싸움이 되리라.', '', 25549),
(122956, 'koKR', '악마가 너무 많아. 난... 달빛 수호자의 힘이 더 필요하다. 너무 지나친 걸까? 아냐, 집중해야 해! 내 동족의 미래가 내 손에 달렸다!', '', 25549),
(122955, 'koKR', '거대하게 불타는 어둠에 맞서려 하는구나! 하수인들아, "영웅"을 없애라!', '', 25549),
(122954, 'koKR', '수천 마리가 더 나타났군! 악마들이 아래쪽에 있는 차원문에서 나오는 것 같다. 살아남으려면 그걸 파괴해야 하지만, 달빛 수호자의 도움이 필요할 거야.', '', 25549),
(122953, 'koKR', '나는 일리단이다, 악마야! 내가 바로 너의 파멸이다!', '', 25549),
(122952, 'koKR', '내가 끝내야 해... 어떻게든!', '', 25549),
(122951, 'koKR', '이런 세력에 어떻게 맞설 수 있단 말인가?', '', 25549),
(122950, 'koKR', '저 관문을 닫을 방법을 찾아야 해!', '', 25549),
(122949, 'koKR', '하나를 처치할 때마다 둘이 나타나는군!', '', 25549),
(122948, 'koKR', '정말이지 끝이 없군!', '', 25549),
(122947, 'koKR', '바람에 안개가 걷혔는지도 모르지.', '', 25549),
(122946, 'koKR', '여기서 수라마르가 전부 보이잖아!', '', 25549),
(122945, 'koKR', '다시는 그러지 말죠!', '다시는 그러지 말죠!', 25549),
(122944, 'koKR', '나는 부주의한 탓에 물러나야 한다. 이번 패배를 교훈 삼아 다시 돌아오겠다.', '', 25549),
(122943, 'koKR', '말퓨리온이 첫 번째 드루이드가 되는 건, 성실한 제자이기 때문이다. 넌 그렇지 못하고.', '', 25549),
(122942, 'koKR', '내가 티리스팔의 첫 번째 수호자 알로디 님의 영혼을 소환하겠소. 시작할 준비가 되면 알려 주시오.', '', 25549),
(122941, 'koKR', '소환을 시작하십시오.', '소환을 시작하세요.', 25549),
(122940, 'koKR', '우린 군단에 맞서 다시 한 번 승리를 거둘 거요.', '', 25549),
(122939, 'koKR', '달라란은 무너지지 않을 거요, $n.', '', 25549),
(122938, 'koKR', '군단을 막아야 하오!', '', 25549),
(122937, 'koKR', '이건 절대로 나쁜 생각이 아니라고.', '이건 절대로 나쁜 생각이 아니라고.', 25549),
(122936, 'koKR', '여섯 눈의 주인이 네 운명을 봤다, $n! 네가 실패하면, 이 세계가 불타리라!', '', 25549),
(122935, 'koKR', '계속 대자연에 대해 배우고 싶다면, 네 형에게 가르침을 받아라.', '', 25549),
(122934, 'koKR', '투석기 도와 주려고 큰 돌 다 가져왔다. 그레그 호드에 들어가고 싶어!', '이게 네 함선이다, $n. 빛이 너와 함께하길.', 25549),
(122933, 'koKR', '$n|1이;가; 엄숙한 밤의 영약에 몰래 독을 더합니다.', '$n|1이;가; 엄숙한 밤의 영약에 몰래 독을 더합니다.', 25549),
(122932, 'koKR', '$n|1이;가; 비전 마력 수송관을 파괴하여 수호의 피조물을 과부하시킵니다.', '$n|1이;가; 비전 마력 수송관을 파괴하여 수호의 피조물을 과부하시킵니다.', 25549),
(122930, 'koKR', '$n|1이;가; 물에 젖은 두루마리를 해독하여 모두에게 이동 속도 증가 효과를 부여합니다.', '$n|1이;가; 물에 젖은 두루마리를 해독하여 모두에게 이동 속도 증가 효과를 부여합니다.', 25549),
(122929, 'koKR', '$n|1이;가; 마법 초롱을 수리해 모두에게 공격력 증가 효과를 부여합니다.', '$n|1이;가; 마법 초롱을 수리해 모두에게 공격력 증가 효과를 부여합니다.', 25549),
(122928, 'koKR', '$n|1이;가; 밤그늘 간식을 사용하여 모두에게 생명력 증가 효과를 부여합니다.', '$n|1이;가; 밤그늘 간식을 사용하여 모두에게 생명력 증가 효과를 부여합니다.', 25549),
(122927, 'koKR', '$n|1이;가; 그림자 꽃의 포자를 방출하여 모두에게 가속 증가 효과를 부여합니다.', '$n|1이;가; 그림자 꽃의 포자를 방출하여 모두에게 가속 증가 효과를 부여합니다.', 25549),
(122926, 'koKR', '$n|1이;가; 지옥 보주를 흡수하여 모두에게 치명타 및 극대화율 증가 효과를 부여합니다.', '$n|1이;가; 지옥 보주를 흡수하여 모두에게 치명타 및 극대화율 증가 효과를 부여합니다.', 25549),
(122925, 'koKR', '$n|1이;가; 지옥불 고서를 파괴하여 모두에게 받는 피해 감소 효과를 부여합니다.', '$n|1이;가; 지옥불 고서를 파괴하여 모두에게 받는 피해 감소 효과를 부여합니다.', 25549),
(122924, 'koKR', '$n|1이;가; 별빛 장미 차를 사용하여 모두에게 생명력과 마나 회복 효과를 부여합니다.', '$n|1이;가; 별빛 장미 차를 사용하여 모두에게 생명력과 마나 회복 효과를 부여합니다.', 25549),
(122923, 'koKR', '전투의 함성이 들리는가, $n? 자네를 부르고 있네!', '', 25549),
(122912, 'koKR', '전쟁이 어찌나 피를 끓게 하는지! $n, 그 도끼가 결투에 굶주리지 않았나?', '', 25549),
(122911, 'koKR', '피바람을 불러 일으키세, $n. 자네 함선과 영광의 승리가 기다리네.', '이게 당신 함선이오, $n. 빛이 당신과 함께하길.', 25549),
(122908, 'koKR', '흠... 뭔가 생각이 떠오르는데... 먼저 변형체들을 처리하고 나서 얘기합시다.', '', 25549),
(122907, 'koKR', '모데라와 난 계속 카라잔에서 찾은 고서를 살펴보겠소. 반드시 근원을 찾아내겠소, $n!', '', 25549),
(122906, 'koKR', '우리 모두 카라잔에서 무사히 빠져나올 수 있었다니 정말 다행이군.', '', 25549),
(122900, 'koKR', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t 히리아가 |cFFFF0404|Hspell:192206|h[신성화]|h|r를 시전합니다!', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t 히리아가 |cFFFF0404|Hspell:192206|h[신성화]|h|r를 시전합니다!', 25549),
(122899, 'koKR', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t 히리아가 |cFFFF0404|Hspell:192305|h[폭풍의 눈]|h|r을 시전합니다!', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t 히리아가 |cFFFF0404|Hspell:192305|h[폭풍의 눈]|h|r을 시전합니다!', 25549),
(122898, 'koKR', '네가 옳았다, 악마야. 지옥 마법이 비전보다 강하다. 하지만 넌 너무 서툴구나! 진짜 강자가 어떤 파괴를 불러올 수 있는지 보여주마!', '', 25549),
(122897, 'koKR', '', '감히 불타는 군단을 거역하느냐? 맞설 수 없는 지옥의 힘 앞에 무릎 꿇어라!', 25549),
(122896, 'koKR', '선택의 여지가 있겠는가? 내가 실패하면 수라마르는 사랑하는 티란데와 함께 붕괴되고 말 것이다. 당장 행동해야 돼!', '', 25549),
(122895, 'koKR', '그녀의 지옥 마법은 너무 강력하다. 달빛 수호자들에게서 마력을 흡수하고, 그걸로 이 악마를 처치할 수도 있지만, 그랬다간 우리 마법사들도 죽을 것이다.', '', 25549),
(122894, 'koKR', '대마법사님, 떠나야 합니다.', '대마법사님, 떠나야 해요.', 25549),
(122893, 'koKR', '명령에 따르겠습니다, 대장!', '명령에 따르겠습니다, 대장!', 25549),
(122892, 'koKR', '문을 내리고 공격에 대비하라! 수리검 투척기, 공격 준비!', '', 25549),
(122891, 'koKR', '준비됐습니다, 레이븐크레스트 군주시여! 문을 여십시오!', '', 25549),
(122890, 'koKR', '좋아! 차원문에 가까이 있으면 여기서 퍼져 나오는 힘이 내게 마력을 부여할 것이다. 지치면 언제든 이 차원문으로 돌아오면 되겠지.', '', 25549),
(122889, 'koKR', '일리단이 생각에 잠깁니다.', '', 25549),
(122888, 'koKR', '저 비활성화된 차원문을 수리할 수 있다면, 지원군과 내 마력을 보충할 힘의 원천을 확보할 수 있어.', '', 25549),
(122887, 'koKR', '총력을 기울여서야 겨우 저 보호의 방벽을 생성할 수 있었다. 달빛 수호자를 더 밀어붙였다가는, 모두 죽고 말 거야.', '', 25549),
(122886, 'koKR', '실망시키지 않겠습니다, 군주님!', '', 25549),
(122884, 'koKR', '내가... 그 방법을 찾겠다.', '', 25549),
(122883, 'koKR', '우린 파멸할 거야...', '', 25549),
(122882, 'koKR', '여기서 놈들을 물리친다고 해도, 아무 의미가 없어.', '', 25549),
(122881, 'koKR', '이 병력 너머... 수없이 많은... 적이 있다.', '', 25549),
(122880, 'koKR', '눈이... 우리를 기만한다.', '', 25549),
(122879, 'koKR', '아무리 저항해 봐야, 이 세계는 붕괴된다.', '', 25549),
(122878, 'koKR', '<고통스러운 비명>', '', 25549),
(122877, 'koKR', '군단의 힘을 봐라.', '', 25549),
(122876, 'koKR', '동생아-', '', 25549),
(122875, 'koKR', '이 길을 걸으려면 희생이 필요하다, 일리단... 네가 아직 배우지 못한 것이지.', '', 25549),
(122874, 'koKR', '존중하는 법을 배워라.', '', 25549),
(122873, 'koKR', '제가 스승이 아니라 초보자에게 배워야 한다는 겁니까?', '', 25549),
(122872, 'koKR', '그러면...', '', 25549),
(122871, 'koKR', '아니. 여기 머물러도 좋다. 하지만 난 네 스승이 되지 않겠다.', '', 25549),
(122870, 'koKR', '날 추방했잖습니까, 세나리우스 님!', '', 25549),
(122869, 'koKR', '일리단, 분노할 필요는 없다. 널 모욕한 게 아니야.', '', 25549),
(122868, 'koKR', '', '그래요. 이 아이는 위대하고 풍요로운 미래를 누릴 운명이에요. 아이 이름은... 일리단이죠.', 25549),
(122867, 'koKR', '저 아이는! 눈이 황금색이군요!', '', 25549),
(122866, 'koKR', '', '아름다워요. 거의 똑같아요. 하나만 빼고-', 25549),
(122865, 'koKR', '', '스톰레이지 쌍둥이예요.', 25549),
(122864, 'koKR', '둘이요?', '', 25549),
(122862, 'koKR', '', '도망쳐라, 레이븐크레스트, 도망쳐! 어딘가의 나무 속에서 벌벌 떨며, 사랑하는 이들과 최후의 나날을 보낼 시간은 남아 있다!', 25549),
(122861, 'koKR', '', '강아지에게... 송곳니가 있다니...', 25549),
(122860, 'koKR', '', '너... 자신의 부하들을 죽인 거냐?! 미친 바보 같으니! 이제 네 운명은 정해졌다!', 25549),
(122859, 'koKR', '', '이건 뭐지? 레이븐크레스트가 강아지를 보낸 건가? 윗사람을 존중하는 법을 가르쳐 주마, 꼬마야!', 25549),
(122858, 'koKR', '$n! 카드가! 이렇게 만나서 정말 다행이군요! 믿지 못하겠지만, 우리 형 마그니가 돌아왔어요!', '', 25549),
(122857, 'koKR', '스톰레이지 대장이 기회를 만들었다! 성벽을 확보하라! 탑경비대, 전진!', '', 25549),
(122856, 'koKR', '해야 할 일을 하라! 검은 떼까마귀 요새가 무너지면, 수라마르 전체가 함께 몰락한다!', '', 25549),
(122855, 'koKR', '', '%s|1이;가; 무심하게 어깨를 으쓱하고는 당신을 하늘 높이 차 버립니다.', 25549),
(122854, 'koKR', '', '죽고 싶으면 그렇게 해라.', 25549),
(122853, 'koKR', '', '도둑놈! 감히 내 것을 훔치려 들어?!', 25549),
(122852, 'koKR', '네가 우리의 마지막 희망이다, 일리단!', '', 25549),
(122851, 'koKR', '군단은 우리 병력의 절반을 학살하고 나머지는 사방으로 흩어 놓았다. 여기 있는 건 요새를 지키던 탑경비대의 남은 병력일 뿐이야.', '', 25549),
(122850, 'koKR', '몰락에게 다시 도전하고 싶습니다.', '몰락에게 다시 도전하고 싶습니다.', 25549),
(122849, 'koKR', '잘했다, 일리단. 하지만 전투는 이제 시작이다.', '', 25549),
(122848, 'koKR', '이게 당신의 이름입니까?', '이게 당신의 이름입니까?', 25549),
(122847, 'koKR', '', '내게 무슨 볼일이지, $r?', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122846, 'koKR', '', '건강한 사내 아이가 하나도 아니고 둘이나 태어났어요.', 25549),
(122845, 'koKR', '', '여신을 찬미하세요. 우릴 축복하사, 오늘 밤 새 생명을 주셨어요.', 25549),
(122844, 'koKR', '일리단이 죽고 황금 군대가 우리 이름으로 전 우주에서 끝없는 전쟁을 벌이고 있다니...', '', 25549),
(122843, 'koKR', '빛의 군대와 일리단 문제는... 정말 당황스럽소. 이렇게 무력한 기분은 처음이군.', '', 25549),
(122842, 'koKR', '우린 지금껏 혼자였던 거요. 신은 우리가 태어나기도 전에 죽었고.', '', 25549),
(122841, 'koKR', '참 많은 것이 설명이 되는군. 하지만 벅찬 슬픔이 밀려오는 건... 막을 수 없소.', '', 25549),
(122840, 'koKR', '죽었다고? 티탄들이 죽었다고?', '', 25549),
(122838, 'koKR', '', '말씀하시죠.', 25549),
(122837, 'koKR', '<발트와에게 탈리스라의 징표를 보여줍니다.>', '<발트와에게 탈리스라의 징표를 보여줍니다.>', 25549),
(122836, 'koKR', '', '마법의 메아리가 가라앉았네요. 감사합니다.', 25549),
(122835, 'koKR', '', '저 성가신 유령 마법사들이 날뛰는 마법의 존재를 창조했어요! 본때를 보여 주죠.', 25549),
(122834, 'koKR', '', '잘하셨어요. 이제 쉬셔도 돼요... 잠시는요.', 25549),
(122833, 'koKR', '', '거대한 야수가 물에서 나타났어요. 놈을 심연 속으로 돌려보내세요!', 25549),
(122832, 'koKR', '내가 모든 걸 봤다! 일리단! 레이븐크레스트 님이 내게 지휘권을 넘기셨다! 이젠 공격을 조율해서 질서를 유지해야 해!', '', 25549),
(122831, 'koKR', '널 보직에서 해임한다, 일리단. 로닌, 이제 네가 달빛 수호자를 지휘한다!', '', 25549),
(122830, 'koKR', '무슨 짓을 한 거냐! 이들을 모두 죽였지 않느냐, 일리단!', '', 25549),
(122829, 'koKR', '섀도송 대장과 외부 동맹군을 찾아라! 처음 공격할 때 떨어졌다. 아직 살아 있어야 할 텐데!', '', 25549),
(122828, 'koKR', '설상가상으로, 투기장의 저 괴수를 막지 못하면 요새가 안쪽으로부터 타들어갈 것이다! 달빛 수호자와 함께 검은 떼까마귀 요새에서 악마의 침공을 저지해 다오!', '', 25549),
(122827, 'koKR', '', '티란데... 우리에게 이 세계란 그 안에 존재하는 이들과 같은 의미다. 마지막 순간, 일리단은 처음과 같은 선명함으로 티란데를 보았지. 그는 세계를 외면한 게 아니었다. 너 자신이라면 어디까지 갈 수 있을지, 자문해 보아라.', 25549),
(122826, 'koKR', '', '진실을 보느라 그의 눈은 불타버리고 말았지만, 일리단은 꿈쩍도 하지 않았다. 불타는 군단 군주의 시선을 받으면서도 일리단은 결연하고 당당했어.', 25549),
(122825, 'koKR', '', '힘겨운 결정이었지만, 일리단의 관점을 이해해야만 우리도 임무에서 성공할 수 있다. 너라면 무엇을 다르게 하였겠는가?', 25549),
(122824, 'koKR', '', '그런 실패와 거부를 겪었던 이는 많지 않다. 대부분은 그저 포기했겠지만, 일리단은 보이지 않는 운명의 손에 이끌려 계속 나아갔어. 그의 운명은 다른 곳에 있었지.', 25549),
(122823, 'koKR', '', '일리단의 삶은 잠재력이 가득했다. 그의 운명은 거대한 질서로 벼려져 우주의 바람을 올라탔지. 그 운명은 아제로스에 정착했다. 그 작은 매개체 안에서 거대한 순환이 새롭게 시작됐다.', 25549),
(122822, 'koKR', '', '고대의 기억이 꿈틀거린다. 준비가 되거든 나를 불러라. 함께 일리단의 과거를 한 조각씩 드러내 보자.', 25549),
(122821, 'koKR', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|t말퓨리온의 |cFF00FFFF|Hspell:212630|h[대지 정화]|h|r를 이용하여 |cFFFF0000|Hspell:210279|h[잠식하는 악몽]|h|r을 피하십시오.', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|t말퓨리온의 |cFF00FFFF|Hspell:212630|h[대지 정화]|h|r를 이용하여 |cFFFF0000|Hspell:210279|h[잠식하는 악몽]|h|r을 피하십시오.', 25549),
(122820, 'koKR', '하늘로 솟아오르는 일은 정말 즐겁구나!', '', 25549),
(122819, 'koKR', '그럴 줄 알았어요! 느낄 수 있었다고요!$B$B어서 떠나세요, $n 님! 놈들을 막아야 해요!', '', 25549),
(122818, 'koKR', '', '놈들을 몰아내세요! 달라란이 무너져서는 안 되요!', 25549),
(122817, 'koKR', '빠른 최후를 맞이하게 해 주지!', '', 25549),
(122816, 'koKR', '너흰 승리하지 못해!', '', 25549),
(122815, 'koKR', '저도 당신만큼 놀랐습니다, $n 님.', '', 25549),
(122814, 'koKR', '최후를 맞이하라!', '', 25549),
(122813, 'koKR', '내 검에 정화되어라!', '', 25549),
(122812, 'koKR', '', '최선을 다해 주세요, $n 님. 이 악마들을 얼마나 막아낼 수 있을지 모르니까요.', 25549),
(122811, 'koKR', '난 키린 토의 지도자인 대마법사 카드가요. 악마사냥꾼들이여, 아제로스에 도움이 필요하오.', '', 25549),
(122810, 'koKR', '아주 교묘한 탈옥 계획을 세워뒀었는데, 아무래도 당신들이 더 빨랐던 모양이군.', '', 25549),
(122809, 'koKR', '우린 모두 파멸할 겁니다!', '우린 모두 파멸할 거예요!', 25549),
(122808, 'koKR', '빛이 사라졌습니다! 보이지 않습니까?', '빛이 사라졌어요! 보이지 않나요?', 25549),
(122807, 'koKR', '', '계속 몰려와요!', 25549),
(122806, 'koKR', '어떻게 해도 그들을 막을 순 없습니다!', '어떻게 해도 그들을 막을 순 없어요!', 25549),
(122805, 'koKR', '그가 없다면 모든 걸 잃습니다!', '그가 없다면 모든 걸 잃어요!', 25549),
(122804, 'koKR', '이건 당신 몫이에요, $n 님!', '', 25549),
(122803, 'koKR', '가게에서 손 떼!', '', 25549),
(122802, 'koKR', '그렇겐 안 되지!', '', 25549),
(122801, 'koKR', '', '그대에게 축복을...', 25549),
(122800, 'koKR', '', '어둠 속으로... 돌아간다...', 25549),
(122799, 'koKR', '', '마침내... 자유가...', 25549),
(122798, 'koKR', '', '정말... 고맙네...', 25549),
(122797, 'koKR', '', '길을 잃었네...', 25549),
(122796, 'koKR', '', '빛이 사라졌어...', 25549),
(122795, 'koKR', '', '희망이 없어...', 25549),
(122794, 'koKR', '', '도와... 주게...', 25549),
(122793, 'koKR', '아무도 이걸 통제하지 못하는 겁니까?', '아무도 이걸 통제하지 못하는 겁니까?', 25549),
(122792, 'koKR', '누가 이걸 좀 막아 주세요!', '누가 이걸 좀 막아 주세요!', 25549),
(122791, 'koKR', '이걸 쫓아 주세요!', '이걸 쫓아 주세요!', 25549),
(122790, 'koKR', '전투에 함께하겠습니다, 일리단 님!', '', 25549),
(122789, 'koKR', '[%s]|1이;가; 고해합니다. "전 경매장에 물건을 올릴 땐 늘 최저가에 올려요. 그냥 그러고 싶더라고요."', '[%s]|1이;가; 고해합니다. "전 경매장에 물건을 올릴 땐 늘 최저가에 올려요. 그냥 그러고 싶더라고요."', 25549),
(122788, 'koKR', '[%s]|1이;가; 고해합니다. "그론하고는 싸우고 싶지 않아요. 왠지 처량한 눈빛으로 절 바라보고 있는 것 같다고요."', '[%s]|1이;가; 고해합니다. "그론하고는 싸우고 싶지 않아요. 왠지 처량한 눈빛으로 절 바라보고 있는 것 같다고요."', 25549),
(122787, 'koKR', '드디어, 내 도끼에 맞설 적을 만났군!', '', 25549),
(122786, 'koKR', '[%s]|1이;가; 고해합니다. "전 가로쉬가 괜찮은 친구라고 생각했어요."', '[%s]|1이;가; 고해합니다. "전 가로쉬가 괜찮은 친구라고 생각했어요."', 25549),
(122785, 'koKR', '[%s]|1이;가; 고해합니다. "전 황금골 여관이 정말, 정말 좋아요."', '[%s]|1이;가; 고해합니다. "전 황금골 여관이 정말, 정말 좋아요."', 25549),
(122784, 'koKR', '[%s]|1이;가; 고해합니다. "왜 부서진 섬이라고 하는지 모르겠어요. 섬이란 게 원래 그렇게 조각나 떨어져 있는 거 아닌가요?"', '[%s]|1이;가; 고해합니다. "왜 부서진 섬이라고 하는지 모르겠어요. 섬이란 게 원래 그렇게 조각나 떨어져 있는 거 아닌가요?"', 25549),
(122783, 'koKR', '[%s]|1이;가; 고해합니다. "조선소에 있는 배 중에 파괴되었으면 하고 바라는 게 딱 한 척이 있는데, 걘 늘 임무에 성공하더라고요."', '[%s]|1이;가; 고해합니다. "조선소에 있는 배 중에 파괴되었으면 하고 바라는 게 딱 한 척이 있는데, 걘 늘 임무에 성공하더라고요."', 25549),
(122782, 'koKR', '[%s]|1이;가; 고해합니다. "주둔지에 가 본지도 참 오래됐네요. 추종자들은 잘 살고 있는지 모르겠어요."', '[%s]|1이;가; 고해합니다. "주둔지에 가 본지도 참 오래됐네요. 추종자들은 잘 살고 있는지 모르겠어요."', 25549),
(122781, 'koKR', '[%s]|1이;가; 고해합니다. "전 예전 달라란이 좋아요. 아니, 그거 말고요. 그거요."', '[%s]|1이;가; 고해합니다. "전 예전 달라란이 좋아요. 아니, 그거 말고요. 그거요."', 25549),
(122780, 'koKR', '[%s]|1이;가; 고해합니다. "네, 깜빡하고 치타 무리의 상을 끄지 않은 적이 있어요."', '[%s]|1이;가; 고해합니다. "네, 깜빡하고 치타 무리의 상을 끄지 않은 적이 있어요."', 25549),
(122779, 'koKR', '[%s]|1이;가; 고해합니다. "전 새로운 우두머리 공략법을 논의할 땐, 그냥 한 귀로 듣고 한 귀로 흘려요."', '[%s]|1이;가; 고해합니다. "전 새로운 우두머리 공략법을 논의할 땐, 그냥 한 귀로 듣고 한 귀로 흘려요."', 25549),
(122778, 'koKR', '[%s]|1이;가; 고해합니다. "브리쿨 턱수염이 고양이보다 폭신한 건 아닐까 생각하곤 해요."', '[%s]|1이;가; 고해합니다. "브리쿨 턱수염이 고양이보다 폭신한 건 아닐까 생각하곤 해요."', 25549),
(122777, 'koKR', '[%s]|1이;가; 고해합니다. "귀차니즘 때문에 경매장을 찾아갈 수가 없어서 필요 없는 건 전부 상인에게 팔고 있어요."', '[%s]|1이;가; 고해합니다. "귀차니즘 때문에 경매장을 찾아갈 수가 없어서 필요 없는 건 전부 상인에게 팔고 있어요."', 25549),
(122776, 'koKR', '[%s]|1이;가; 고해합니다. "솔직히 바다에서 스플래쉬란을 찾느라 너무 많은 시간을 낭비하고 있는 것 같아요."', '[%s]|1이;가; 고해합니다. "솔직히 바다에서 스플래쉬란을 찾느라 너무 많은 시간을 낭비하고 있는 것 같아요."', 25549),
(122775, 'koKR', '[%s]|1이;가; 고해합니다. "타우렌의 무기는 정말 지나치게 크다고 생각해요."', '[%s]|1이;가; 고해합니다. "타우렌의 무기는 정말 지나치게 크다고 생각해요."', 25549),
(122774, 'koKR', '[%s]|1이;가; 고해합니다. "군단은 이미 물리친 줄 알았는데..."', '[%s]|1이;가; 고해합니다. "군단은 이미 물리친 줄 알았는데..."', 25549),
(122773, 'koKR', '[%s]|1이;가; 고해합니다. "전 생석이 뭔지 몰라요. 그렇다고 이제 와서 누구에게 물어 볼 수도 없고요."', '[%s]|1이;가; 고해합니다. "전 생석이 뭔지 몰라요. 그렇다고 이제 와서 누구에게 물어 볼 수도 없고요."', 25549),
(122772, 'koKR', '장난은 끝내라, 악마들아! 너흰 날 이길 수 없다!', '', 25549),
(122771, 'koKR', '군단은 아무도 자신들의 계략을 모를 거라고 생각하지만, 우린 준비가 됐다!', '', 25549),
(122770, 'koKR', '하늘에서도 이렇게 침착하게 떨어지는군. 아, 달콤한 쾌감이야.', '', 25549),
(122769, 'koKR', '아무래도 제가 달라란 귀환석을 잃어버린 것 같습니다. 하나 더 받을 수 있을까요?', '아무래도 제가 달라란 귀환석을 잃어버린 것 같아요. 하나 더 받을 수 있을까요?', 25549),
(122768, 'koKR', '너의 희생을 기억해 주마.', '', 25549),
(122767, 'koKR', '해야 할 일을 했을 뿐.', '', 25549),
(122766, 'koKR', '네 검은 늘 적중한다, 제로드. 함께 이 공격을 끝내자!', '', 25549),
(122765, 'koKR', '그들의 희생에 의미가 있길 바랄 뿐입니다.', '', 25549),
(122764, 'koKR', '이곳은 거의 어떤 공격도 견뎌낼 수 있지만, 군단의 힘은 그 누구도 예측할 수 없었을 겁니다.', '', 25549),
(122763, 'koKR', '일리단 님, 정말 강인하게 싸우시는군요!', '', 25549),
(122762, 'koKR', '전 영웅이 아닙니다. 하지만 기꺼이 당신 곁에 서겠습니다.', '', 25549),
(122761, 'koKR', '전 조금 불편하군요, 일리단 님.', '', 25549),
(122760, 'koKR', '가치 있는 전투였습니다. 저 혼자선 공포의 군주를 무찌를 수 없었겠죠.', '', 25549),
(122759, 'koKR', '일리단 님! 묘지 안에 공포의 군주가 있습니다. 그대의 도움이 필요합니다.', '', 25549),
(122758, 'koKR', '불로 정화돼라, 악마야!', '', 25549),
(122757, 'koKR', '하늘은 내가 확보하겠다, 대장. 지상엔 아직 당신이 필요한 것 같으니까.', '', 25549),
(122756, 'koKR', '이 공격이 영영 끝나지 않는 줄 알았건만!', '', 25549),
(122755, 'koKR', '일리단! 용을 다루는 솜씨는 정말 타고났구나!', '', 25549),
(122754, 'koKR', '내 도끼는 자네 것일세.', '', 25549),
(122753, 'koKR', '자네 곁에서 싸우는 것만으로도 전술을 배울 수 있군, 일리단.', '', 25549),
(122752, 'koKR', '이런 적과의 싸움에 도움을 줘서 정말 고맙네.', '', 25549),
(122751, 'koKR', '일리단, 자네는 강인하고 우아하게 싸우는군. 자네가 싸우는 모습을 보는 건 영광이네.', '', 25549),
(122750, 'koKR', '자네는 해야 할 일을 하는군. 존경할 만한 자질이야.', '', 25549),
(122749, 'koKR', '자네는 대체 무슨 마법사인가?', '', 25549),
(122748, 'koKR', '공정한 싸움이 아니군! 나를 상대하려면 지원군이 더 필요할 거다, 악마야!', '', 25549),
(122747, 'koKR', '언젠가 내가 수집한 휘장들을 보여주겠소!', '', 25549),
(122746, 'koKR', '언젠가 내가 수집한 탈것들을 보여주겠소!', '', 25549),
(122745, 'koKR', '언젠가 내가 수집한 동전들을 보여주겠소!', '', 25549),
(122744, 'koKR', '언젠가 내가 수집한 두루마리들을 보여주겠소!', '', 25549),
(122743, 'koKR', '언젠가 내가 수집한 애완동물들을 보여주겠소!', '', 25549),
(122742, 'koKR', '언젠가 내가 수집한 술잔들을 보여주겠소!', '', 25549),
(122741, 'koKR', '언젠가 내가 수집한 장난감들을 보여주겠소!', '', 25549),
(122740, 'koKR', '술을 많이 마실수록 더 훌륭한 전략이 만들어지... 딸꾹!', '', 25549),
(122739, 'koKR', '지난 주 야크 경주에서 2등을 했네. 더 빠른 야크가 필요해!', '', 25549),
(122738, 'koKR', '매일 아침 전 유랑도 둘레길을 뜁니다... 두 번씩! 훈련을 게을리 할 순 없죠.', '', 25549),
(122737, 'koKR', '언젠가 내가 수집한 나뭇잎들을 보여주겠소!', '', 25549),
(122736, 'koKR', '이것만 끝나면 저녁 2차를 먹으러 가야지!', '이것만 끝나면 저녁 2차를 먹으러 가야지!', 25549),
(122735, 'koKR', '$n! 보여줄 물건이 있다! 어서 와 봐라!', '', 25549),
(122734, 'koKR', '', '$n 님! 혹시 잠시 시간이 괜찮으시면 제가 가진 물건들 좀 보세요. 분명히 관심이 있으실 거예요.', 25549),
(122733, 'koKR', '특이한 일은 없습니다. 종종 마력이 느껴지긴 하지만, 위험하다고 할 건 없습니다.', '특이한 일은 없습니다. 종종 마력이 느껴지긴 하지만, 위험하다고 할 건 없어요.', 25549),
(122732, 'koKR', '', '$n 님! 잠시 시간을 내주시면 관심 있어 하실 물건을 좀 보여드릴게요.', 25549),
(122731, 'koKR', '', '$n 님! 잠시 시간을 내주시면 관심 있어 하실 물건을 좀 보여드릴게요.', 25549),
(122730, 'koKR', '', '$n 님! 잠시 시간을 내주시면 관심 있어 하실 물건을 좀 보여드릴게요.', 25549),
(122729, 'koKR', '$n 님! 잠시 시간을 내주시면 관심 있어 하실 만한 물건을 좀 보여드리겠습니다.', '', 25549),
(122728, 'koKR', '', '$n 님! 잠시 시간을 내주시면 관심 있어 하실 물건을 좀 보여드리겠습니다.', 25549),
(122727, 'koKR', '', '뭐라도 발견하면 알려드릴게요.', 25549),
(122726, 'koKR', '$n 님! 잠시 시간을 내주시면 관심 있어 하실 물건을 좀 보여드리겠습니다.', '', 25549),
(122725, 'koKR', '인사를 할 시간도 없겠습니다, 악마사냥꾼이여.$b$b다른 일리다리에게도 말씀드렸지만, 지금은 머리가 좀 복잡해요.$b$b군단에 맞설 병력을 준비시켜야 하는 와중에, 동맹들은 호드에 복수하자는 소리만 하고 있으니까요.', '', 25549),
(122724, 'koKR', '', '지금은 여기도 다 괜찮아진 것 같네요!', 25549),
(122723, 'koKR', '$n|1이여;여;! 혹시 잠시 시간이 괜찮다면 내가 가진 물건들을 좀 보시오. 분명히 관심이 있을 거요.', '', 25549),
(122722, 'koKR', '좋은 물건 있다, 와서 한 번 봐라.', '', 25549),
(122721, 'koKR', '', '$n 님! 혹시 잠시 시간이 괜찮으시면 제가 가진 물건들 좀 보세요. 분명히 관심이 있으실 겁니다.', 25549),
(122720, 'koKR', '', '믿으셔도 돼요. 눈 깜짝할 사이에 다시 내보내 드릴게요!', 25549),
(122719, 'koKR', '', '$n 님! 잠시 시간을 내주시면 관심 있어 하실 물건을 좀 보여드릴게요.', 25549),
(122718, 'koKR', '', '당신이 대충 정리한 것 같네요.', 25549),
(122717, 'koKR', '', '이봐 그린들... 아, 이런. 묻지 않을게요. 모두 당신 몫이에요.', 25549),
(122716, 'koKR', '당신의 지도 하에 은빛 성기사단이 재건되어, 새로운 방향과 지침을 따르고 있습니다.$B$B앞으로 할 일이 많습니다.', '', 25549),
(122715, 'koKR', '', '여기 상황은 어떤가요? 뭔가 특이한 간섭 현상은 없나요?', 25549),
(122714, 'koKR', '', '두 분 다 여기까지 오시는 데 다른 문제는 없었나요? 이 지역의 마력이 상당히 불안정해졌다는 보고를 받았거든요.', 25549),
(122713, 'koKR', '카드가에 대해 다시 말씀해 주십시오.', '카드가에 대해 다시 말씀해 주세요.', 25549),
(122712, 'koKR', '굴단에 대해 다시 말씀해 주십시오.', '굴단에 대해 다시 말씀해 주세요.', 25549),
(122711, 'koKR', '일리단에 대해 다시 말씀해 주십시오.', '일리단에 대해 다시 말씀해 주세요.', 25549),
(122710, 'koKR', '키린 토가 당신에게 감사드립니다.', '', 25549),
(122709, 'koKR', '우리의 성스러운 고향을 되찾아야 합니다.', '', 25549),
(122708, 'koKR', '', '저희와 함께 군단과 맞서 싸울 용기가 있습니까?', 25549),
(122707, 'koKR', '이 숲의 생명이 느껴지시오? 우리는 오랫동안 이 땅을 지켰소. 하지만 우리 힘만으로는 이 땅을 지킬 수 없는 때가 오고 말았구려. 우리를 도와주겠소?', '이 숲의 생명이 느껴지시오? 우리는 오랫동안 이 땅을 지켰소. 하지만 우리 힘만으로는 이 땅을 지킬 수 없는 때가 오고 말았구려. 우리를 도와주겠소?', 25549),
(122706, 'koKR', '', '단단히 준비하십시오, $n 님.$B$B더빈은 고집쟁이 드워프이긴 하지만, 저도 그에게 동의하는 게 하나 있습니다. 여긴 뭔가 이상해요.', 25549),
(122705, 'koKR', '', '좀 더 버텨야 할 것 같아요.', 25549),
(122704, 'koKR', '', '의회에 계획이 있겠죠. 분명히 그럴 거예요!', 25549),
(122703, 'koKR', '', '어서 도시를 옮겨야 할 거예요! 이렇게 계속 버틸 순 없어요!', 25549),
(122702, 'koKR', '', '계속 이럴 수는 없어요! 곧 적에게 압도될 거예요!', 25549),
(122701, 'koKR', '', '끝이 없네요! 적이 계속 몰려와요!', 25549),
(122700, 'koKR', '', '계속 버틸 순 없어요!', 25549),
(122699, 'koKR', '무사하군! 연맹 전당에서 당신이 깨어나지 않자 당신의 용사가 날 찾아왔었소. 당신을 여기로 데려와 의무실에 입원시켰지. 어떻게 된 거요?', '', 25549),
(122698, 'koKR', '', '안녕하세요! 지금 막 여기 오신 건가요? 달리 후유증을 겪고 계신 것 같진 않네요.', 25549),
(122697, 'koKR', '', '안녕하세요, $n 님. 괜찮으세요? 꽤 많은 이들이 현기증과 멀미 때문에 고생을 하고 있더라고요.', 25549),
(122696, 'koKR', '', '고통은 가라앉을 것이다, 용사여. 넌 이제 내 징표를 지녔으니, 나도 그걸 통해 너처럼 보고 느낄 수 있다. 가능할 때 내게 돌아와라. 우린 할 일이 많다.', 25549),
(122695, 'koKR', '아하하하하하!', '', 25549),
(122694, 'koKR', '죽음에서 살아 돌아왔군, $g친구:친구;! 그대는 3일 동안이나 의식이 없었소. 카드가도 마음을 놓겠어. 아주 특별한 친구가 깨어났으니... 아, 그런데 나는 어떻냐고? 나는 아직도 바다표범 신세요.', '', 25549),
(122693, 'koKR', '악마야, 네 정체를 숨길 수 있을 줄 알았더냐?', '악마야, 네 정체를 숨길 수 있을 줄 알았더냐?', 25549),
(122692, 'koKR', '울두아르에서는 참 많은 일이 있었소만, 앞으로도 할 일이 많소.', '', 25549),
(122691, 'koKR', '먼저 들어가시오. 나도 곧 따라가겠소. 잠시... 생각을 정리해야겠소.', '', 25549),
(122690, 'koKR', '생각이 바뀌었습니다. 어떤 유물이 있는지 다시 보여주십시오.', '생각이 바뀌었습니다. 어떤 유물이 있는지 다시 보여주십시오.', 25549),
(122686, 'koKR', '누구도 황혼의 망치단에 맞서지 못한다!', '누구도 황혼의 망치단에 맞서지 못한다!', 25549),
(122685, 'koKR', '우리는 파괴의 전령이다!', '우리는 파괴의 전령이다!', 25549),
(122684, 'koKR', '도와달라고 외쳐봤자... 아무도 대답하지 않는다!', '도와달라고 외쳐봤자... 아무도 대답하지 않는다!', 25549),
(122683, 'koKR', '황혼이 널 덮친다!', '황혼이 널 덮친다!', 25549),
(122682, 'koKR', '나는 너의 파멸이다!', '나는 너의 파멸이다!', 25549),
(122681, 'koKR', '', '이 꽃들이 어떻게 된 건지 모르겠어요! 제가 이 꽃들을 다듬어 주지 않은 건... 음, 꽃들이 스스로 다듬기 시작한 후부터였죠!$B$B정말 이상한 일이죠?', 25549),
(122680, 'koKR', '저 늙은 필마프의 사연은 무엇입니까?', '저 늙은 필마프의 사연은 무엇인가요', 25549),
(122679, 'koKR', '몇 년 뒤, 우리는 노스렌드에서의 활동을 위해 얼음왕관으로 도시를 통째로 옮겼소.$b$b그런데 어느 날 난데없이 늙은 필마프가 보랏빛 탑으로 걸어 들어오는 거요. 그냥 뚜벅뚜벅 걸어서 말이오! 아무 말도 없이... 그리고는 아무 일 없었다는 듯이 책을 분류하고 정리하는 일을 시작했소. 그때부터 쭉 여기서 지냈다오.$b$b<몸을 가까이 기울여 속삭이는 발렌타스>$b$b자신이 죽었는지도 모르는 것 같소.', '', 25549),
(122678, 'koKR', '누구? 필마프 말이오? 저 골동품 같은 늙은이? 그는 수십 년간 달라란에서 기록관으로 일했소. 내 학창시절에도 그가 서류 더미 사이를 돌아다니는 모습을 봤다오. 그는 뭐든 찾아냈지.$b$b그러다 3차 대전쟁이 터졌고 아서스가 도시를 침공했소. 다른 무수한 희생자처럼, 필마프 역시 행방불명이 됐지. 우리는 다른 시체들 틈에 섞였으리라 생각하고 더는 걱정하지 않았소.', '', 25549),
(122677, 'koKR', '아렉시스가 이 에레다르에게 기습을 당했다는 말인가, 발라두르? 그러면 틀림없이 그가 지팡이를 가지고 있을 걸세...\n\n공격한 걸 보니 그는 여기 어딘가에 있거나, 우릴 지켜보고 있겠군. 조금... 무모한 제안을 해 볼까?\n\n아렉시스의 의식을 재현해보세! 침공 거점에서 의식을 거행하면 발라두르가 알아차리게 되고 기습을 계획하겠지. 물론 우리는 그에 대비한 뒤겠지만 말이네.', '', 25549),
(122676, 'koKR', '<아무 말도 없이 경계하는 눈빛으로 당신을 바라봅니다.>', '<아무 말도 없이 경계하는 눈빛으로 당신을 바라봅니다.>', 25549),
(122675, 'koKR', '정 원하신다면.', '정 원하신다면.', 25549),
(122674, 'koKR', '당신이 두렵지 않소.', '당신이 두렵지 않소.', 25549),
(122673, 'koKR', '싸웁시다.', '싸웁시다.', 25549),
(122672, 'koKR', '내겐 아무것도 없소.', '내겐 아무것도 없소.', 25549),
(122671, 'koKR', '저리 가시오.', '저리 가시오.', 25549),
(122670, 'koKR', '뭐지?', '뭐지?', 25549),
(122669, 'koKR', '하.', '하.', 25549),
(122668, 'koKR', '혼자 있고 싶소.', '혼자 있고 싶소.', 25549),
(122667, 'koKR', '당신 비밀을 알고 있습니다.', '당신 비밀을 알고 있습니다.', 25549),
(122666, 'koKR', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t일기노스가 |cFFFF0000|Hspell:223121|h[최후의 무기력증]|h|r을 거의 완료했습니다!', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t일기노스가 |cFFFF0000|Hspell:223121|h[최후의 무기력증]|h|r을 거의 완료했습니다!', 25549),
(122665, 'koKR', '폭풍 군주의 무기를 사용하려거든, 안으로 들어가 그의 위업과 몰락에 대해 배워라...', '', 25549),
(122664, 'koKR', '제가 질문을 했으니, 답을 하십시오!', '제가 질문을 했으니, 답을 하세요!', 25549),
(122663, 'koKR', '안녕하시오, 친구! 사실 이건 진짜 나, 카드가가 아니오. 그저 과도하게 잘 생긴 얼굴과 광활한 지식이 담겨 있을 뿐이지. 어떠한 질문이든지 답을 알고 싶다면, 간단히 묻고 답을 요청하시오.\n\n내 정신적 지평은 너무나도 광활한 탓에, 이곳에 남은 마법 공간에 대답은 몇 마디밖에 담을 수 없었소. 그러니 아주 구체적인 질문을 해 주시오.', '', 25549),
(122662, 'koKR', '급한 용무입니다. 악마가 그대들 사이에 침투했습니다. 제가 보여드리죠.', '급한 용무입니다. 악마가 그대들 사이에 침투했습니다. 제가 보여드리죠.', 25549),
(122661, 'koKR', '<아르두엔은 포로로 잡혀 있던 게 분명합니다. 안색이 유령처럼 창백합니다.>$B$B난... 탈출해서... 달렸소...$B$B거의... 성공했는데...$B$B제발, $n, 구해 주시오... 다른... 일리다리를...', '', 25549),
(122660, 'koKR', '울두아르에는 많은 비밀이 담겨 있습니다.', '', 25549),
(122659, 'koKR', '', '모두들, 행운을 빌게요.', 25549),
(122658, 'koKR', '', '미정', 25549),
(122657, 'koKR', '마나 망령이 혼란에 빠져 있는 동안 이동하십시오!', '마나 망령이 혼란에 빠져 있는 동안 이동하십시오!', 25549),
(122656, 'koKR', '', '경계하지 마라, 필멸자여. 네 의식은 끝없는 어둠 속 내 천상의 존재에 투영되었을 뿐이다.', 25549),
(122655, 'koKR', '', '나는 제라, 우주의 정렬이 일어나는 동안 여기서 벼려진 첫 번째 나루다.', 25549),
(122654, 'koKR', '얘기만 하면 바로 떠날 수 있어요!', '', 25549),
(122653, 'koKR', '즉시 황천빛 사원으로 돌아가겠네.', '', 25549),
(122652, 'koKR', '계시가 실현되었다는 이야기를 듣자마자 달라란으로 돌아왔네.\n\n내가 예견했듯이 자네가 빛을 통합시켰군. 자네의 힘을 통해 우리가 발나자르를 영원히 제거할 수 있기를 기원해 보세.', '', 25549),
(122651, 'koKR', '<시리우스 에본윙은 유령처럼 창백합니다. 가끔 주체할 수 없는 듯 몸을 떱니다.>', '', 25549),
(122650, 'koKR', '<카시엘 나이트쏜의 시체는 거의 알아볼 수가 없습니다. 고문당하고, 그 상처 때문에 숨을 거둔 것 같습니다.>', '', 25549),
(122649, 'koKR', '', '$n 님, 당신이로군요.\n\n저희는 무시무시한 공포의 군주를 쫓고 있었는데, 불행히도 녀석이 준비한 함정에 걸리고 말았습니다.', 25549),
(122648, 'koKR', '이 악마는 투지가 대단하군!', '이 악마는 투지가 대단하군!', 25549),
(122647, 'koKR', '우린 그럴 힘이 없습니다...', '우린 그럴 힘이 없습니다...', 25549),
(122646, 'koKR', '너무 강력합니다! 이건 미친 짓이에요!', '너무 강력합니다! 이건 미친 짓이에요!', 25549),
(122645, 'koKR', '', '일리단 스톰레이지라는 자다.', 25549),
(122644, 'koKR', '', '나는 절박한 임무로 여기에 왔다. 나는 빛과 어둠의 자식을 찾는다. 악마의 시대를 끝낼 운명을 지닌 소년이다.', 25549),
(122643, 'koKR', '', '하지만 이제 황금 군대는 멸망의 언저리에 서 있다. 아르거스에 대한 대장정도 곧 최후를 맞을 것이다. 그들이 쓰러지면, 군단은 다시 불타는 성전을 시작하고, 그와 함께 온 우주가 전율하리라.', 25549),
(122642, 'koKR', '', '그 파괴된 세상의 잿더미에서, 생존자들이 일어나 악마들에게 맞섰다. 그들은 빛의 군대로 알려졌지.', 25549),
(122641, 'koKR', '', '판테온이 쓰러진 후에는 살게라스의 뜻을 거스를 자가 아무도 남지 않았다. 그 암흑 티탄과 불타는 군단은 불타는 성전으로 수많은 세계를 아무런 저항 없이 멸망시켰어.', 25549),
(122640, 'koKR', '', '아주 오래전, 모든 세계의 운명을 결정할 거대한 전투가 벌어졌다. 그 최후의 전투에서 전능한 티탄 판테온이 동족의 손에 쓰러졌어. 바로 살게라스였다.', 25549),
(122639, 'koKR', '', '넌 답을 찾아 모든 피조물의 도가니를 찾아왔구나. 잘 들어라. 그리고 깨달음을 얻어라.', 25549),
(122638, 'koKR', '편히 쉬십시오, 오랜 친구여.', '편히 쉬십시오, 오랜 친구여.', 25549),
(122637, 'koKR', '여기 악몽이 있을 곳은 없고, 우린 무슨 수를 써서든 말로른 님을 지켜야 하오. 그분이 안 계시다면, 자연의 조화 자체가 취약해지니...$B$B그분을 구하는 것보다 중요한 일은 없소... 우리 목숨을 내놓아야 할지라도 말이오.', '', 25549),
(122636, 'koKR', '', '야생 신이 이 순간을 다시 경험하기는 쉽지 않을 거예요. 그렇게 오래전 군단이 침공하던 순간의 공포를 전 상상할 수도 없네요.', 25549),
(122635, 'koKR', '', '여긴 정말 너무 싫어요! 어서 저 괴물들을 없애버리자고요, 대드루이드님!', 25549),
(122634, 'koKR', '', '우리 적과 악몽은 모두 영리하군. 수천 년 전 야생 신이 전투에서 쓰러졌던 순간을 선택했네. 그들이 불타는 군단에 맞서 아제로스를 지키기 위해 일어섰던 바로 그때야.', 25549),
(122633, 'koKR', '시리우스, 괜찮으십니까?', '시리우스, 괜찮으십니까?', 25549),
(122632, 'koKR', '아샤, 당신은 자유입니다.', '아샤, 당신은 자유입니다.', 25549),
(122631, 'koKR', '자가노스가 널... 없애리라...', '', 25549),
(122630, 'koKR', '도둑이다!', '', 25549),
(122629, 'koKR', '조심하십시오, $c...', '', 25549),
(122628, 'koKR', '', '전 이런 일이 일어날 거라고 얘기했어요.\n\n얘기했다고요.\n\n왜들 듣지 않은 거죠?!', 25549),
(122627, 'koKR', '이봐, $c. 달라란의 놀라운 상품들은 만나 봤어? 혹시라도 네가 찾는 게 없다면, 누구와 얘기해야 할지 내가 아마 알고 있을 거라고.', '', 25549),
(122626, 'koKR', '', '내 상자야, 저리 꺼져!', 25549),
(122625, 'koKR', '', '네가 군단과 한 편이라는 거 안다아아아. 그래, 바로 너야. 네 목소리가 맞아아아아.', 25549),
(122624, 'koKR', '안녕하십니까, 동료 시민이여. 무슨 문제라도 있습니까?', '', 25549),
(122623, 'koKR', '래리가 널 맛 좋은 고기덩어리로 짓뭉개 줄게.', '', 25549),
(122622, 'koKR', '하, 이 녀석은 끝장이야.', '', 25549),
(122621, 'koKR', '영광을 위하여!', '영광을 위하여!', 25549),
(122620, 'koKR', '놈들은 우리의 위세에 벌벌 떨게 될 것이다.', '놈들은 우리의 위세에 벌벌 떨게 될 것이다.', 25549),
(122619, 'koKR', '오딘께 목숨을 바치리라!', '오딘께 이 한목숨 바치리라!', 25549),
(122618, 'koKR', '발샤라', '발샤라', 25549),
(122617, 'koKR', '내 힘을 보태도록 하지.', '내 힘을 보태도록 하지.', 25549),
(122616, 'koKR', '발키르여, 이제 때가 되었다! 전장으로!', '발키르여, 이제 때가 되었다! 전장으로!', 25549),
(122615, 'koKR', '발키르여! 신호를 보냈다! 준비해라!', '발키르여! 신호를 보냈다! 준비해라!', 25549),
(122614, 'koKR', '높은산', '높은산', 25549),
(122613, 'koKR', '아즈스나', '아즈스나', 25549),
(122612, 'koKR', '여길 떠나는 비행편을 제공해 주실 수 있겠습니까?', '여길 떠나는 비행편을 제공해 주실 수 있나요?', 25549),
(122611, 'koKR', '아, 당신을 찾고 있던 $c|1을;를; 만난 적이 있습니다. 무슨 고대의 무기에 대한 얘기를 하더군요. 부서진 섬으로 가기 전에 먼저 만나 보는 게 좋겠습니다. 뭐든 지원을 받으면 좋을 테니까요.\n\n그게... 정말 원하신다면 비행을 준비해 드릴 수도 있습니다만, 그러지 않는 게 좋겠습니다.', '', 25549),
(122610, 'koKR', '상처가 충분히 회복된 것 같습니다. 정찰을 계속하겠습니다. 몸조심하세요, 릴리아.', '', 25549),
(122609, 'koKR', '', '으아! 날 정말 화나게 하는군!', 25549),
(122608, 'koKR', '', '왜 싸우냐고 물었던가?', 25549),
(122607, 'koKR', '심각하긴 하지만, 그래도 말로른 님의 경고를 받아서 다행이다. 에메랄드의 꿈이 정말 걱정되는구나. 꿈이 타락하면, 그게 아제로스에 어떤 영향을 미칠지는 누구도 알 수 없다.', '', 25549),
(122606, 'koKR', '', '잘 싸웠어요! 어둠감시자의 적은 배반의 대가를 치를 거예요.', 25549),
(122605, 'koKR', '흐뤼츠할을 공격할 준비가 되었습니다.', '흐뤼츠할을 공격할 준비가 되었습니다.', 25549),
(122604, 'koKR', '', '사원에서 가장 강한 마법사들이 어둠감시자에 맞서고 있어요. 우리에게 맞서면 어떻게 되는지 보여 주세요!', 25549),
(122603, 'koKR', '', '영혼들도 힘은 알아보죠. 잘하셨습니다!', 25549),
(122602, 'koKR', '', '천 갈래 빛의 사원에는 광기 어린 영혼이 가득합니다. 놈들 버릇을 고쳐 줘야 해요.', 25549),
(122601, 'koKR', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 사용하여 모듈을 활성화합니다.>', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 사용하여 모듈을 활성화합니다.>', 25549),
(122600, 'koKR', '이 모듈은 오래전에 동력을 잃은 듯합니다.', '', 25549),
(122599, 'koKR', '달라란으로 돌아가고 싶다면, 내 박쥐를 타고 가시오.', '', 25549),
(122598, 'koKR', '무슨 두끼끼지?', '', 25549),
(122597, 'koKR', '히드락시안 물의 군주가 널 따른다. 불타는 군단을 막아내겠다!', '', 25549),
(122596, 'koKR', '앞쪽 동굴에서 수상한 울부짖음이 들립니다.', '앞쪽 동굴에서 수상한 울부짖음이 들립니다.', 25549),
(122595, 'koKR', '영광입니다.', '영광입니다.', 25549),
(122594, 'koKR', '제가 함께 싸우겠습니다.', '제가 함께 싸우겠습니다.', 25549),
(122593, 'koKR', '제가 지키겠습니다.', '제가 지키겠습니다.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122592, 'koKR', '아래층 차원문으로부터 뭔가 파지직거리는 수상한 소리가 들려옵니다.', '아래층 차원문으로부터 뭔가 파지직거리는 수상한 소리가 들려옵니다.', 25549),
(122591, 'koKR', '', '무관의 연맹은 종말을 위한 수단이다. 군단의 종말 말이야.', 25549),
(122590, 'koKR', '공포뿔', '공포뿔', 25549),
(122589, 'koKR', '히드라', '히드라', 25549),
(122588, 'koKR', '강물하마', '강물하마', 25549),
(122587, 'koKR', '라일라크', '라일라크', 25549),
(122586, 'koKR', '기계', '기계', 25549),
(122585, 'koKR', '마지막 무기를 추적할 준비가 됐습니다.', '마지막 무기를 추적할 준비가 됐어요.', 25549),
(122584, 'koKR', '', '조용히 하렴. 곧 집에 갈 거야.', 25549),
(122583, 'koKR', '', '네가 뭔가 부수면, 엄마가 그걸 사야 한단 말이야.', 25549),
(122582, 'koKR', '', '유리는 만지면 안 돼. 엄마랑 약속했지?', 25549),
(122581, 'koKR', '', '조용히 해. 엄마 물건 좀 보게.', 25549),
(122580, 'koKR', '', '아무것도 손대면 안 돼, 알겠지?', 25549),
(122579, 'koKR', '', '엄마는 뭐 깨지는 소리 듣고 싶지 않다.', 25549),
(122578, 'koKR', '남은 유물 무기에 대해 알아낸 정보를 확인해 보고 싶습니다.', '남은 유물 무기에 대해 알아낸 정보를 확인해 보고 싶어요.', 25549),
(122577, 'koKR', '균열 핵이 충전되었어요. 원하는 대로 균열 대포를 발사하시면 돼요.', '균열 핵이 충전되었어요. 원하는 대로 균열 대포를 발사하시면 돼요.', 25549),
(122576, 'koKR', '명령이 떨어졌어요. 즉시 균열 핵 충전을 시작하겠습니다.', '명령이 떨어졌어요. 즉시 균열 핵 충전을 시작하겠습니다.', 25549),
(122575, 'koKR', '미미론이 비상시에 사용할 순간이동 판을 줬지요. 이거면 될 것 같아요!', '', 25549),
(122574, 'koKR', '마그니를 어서 다시 만나고 싶군. 정말 너무 오랜만이오.', '', 25549),
(122573, 'koKR', '사공을 불렀으니 뱃삯을 치러라! 너의 영원한 영혼을 내놓아라!', '', 25549),
(122572, 'koKR', '헬하임으로 가고 싶나? 그렇다면 보내 주지! 아하하하하!', '', 25549),
(122571, 'koKR', '사공을 부르는 자는 뱃삯을 치러야 한다!', '', 25549),
(122570, 'koKR', '영혼들이여! 이 필멸자들을 해일로 휩쓸어라!', '', 25549),
(122569, 'koKR', '순록', '순록', 25549),
(122568, 'koKR', '고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 50을 소비합니다. 계속하시겠습니까?', '고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 50을 소비합니다. 계속하시겠습니까?', 25549),
(122567, 'koKR', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 50을 소비하여 지옥결속 마나호랑이를 해방합니다.>', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 50을 소비하여 지옥결속 마나호랑이를 해방합니다.>', 25549),
(122566, 'koKR', '빛이 당신을 태울 것입니다!', '', 25549),
(122565, 'koKR', '제가 국왕인 건 알고 계시겠죠?', '', 25549),
(122564, 'koKR', '수라마르가 승천합니다.', '수라마르가 승천합니다.', 25549),
(122563, 'koKR', '<이 마나호랑이는 군단에게 구속당해 있습니다. 고대 마나로 수정을 과부하 시키면 풀어줄 수 있을 것 같습니다.>', '', 25549),
(122562, 'koKR', '제 인내심을 시험하시는군요.', '', 25549),
(122561, 'koKR', '지금은 장난이나 칠 때가 아니에요.', '', 25549),
(122560, 'koKR', '빛의 이름으로 승리하세요.', '', 25549),
(122559, 'koKR', '편안한 여행이 되길 빌게요.', '', 25549),
(122558, 'koKR', '희망을 잃지 마세요.', '', 25549),
(122557, 'koKR', '스톰윈드에 오신 것을 환영합니다.', '', 25549),
(122556, 'koKR', '경계를 늦추지 마세요.', '', 25549),
(122555, 'koKR', '국왕의 자격은, 국민을 섬기는 마음에서 나오는 거예요.', '', 25549),
(122554, 'koKR', '그 무엇보다, 얼라이언스를 위하여.', '', 25549),
(122553, 'koKR', '정당한 목표가 있다면, 싸울 수 있겠죠.', '', 25549),
(122552, 'koKR', '때로는 믿음을 위해 싸워야 할 때도 있어요.', '', 25549),
(122551, 'koKR', '반갑습니다, 친구여.', '', 25549),
(122550, 'koKR', '스톰윈드는 영원할 겁니다.', '', 25549),
(122549, 'koKR', '스톰윈드와 얼라이언스를 대표하여 감사드립니다.', '', 25549),
(122548, 'koKR', '불타는 군단은 4인 기사단의 힘 앞에 전율하리라!', '', 25549),
(122547, 'koKR', '기사단이여! 우리 운명이 다가왔다!', '', 25549),
(122546, 'koKR', '안 돼! 칠흑의 기사단이 쓰러지게 하진 않겠다!', '', 25549),
(122545, 'koKR', '이렇게 죽을 순 없어! 난 부자라고!', '이렇게 죽을 순 없어! 난 부자라고!', 25549),
(122544, 'koKR', '경비병, 우리가 왜 월급을 주는지 알고 있겠지? 이 야수를 죽여!', '경비병, 우리가 왜 월급을 주는지 알고 있겠지? 이 야수를 죽여!', 25549),
(122543, 'koKR', '수에쉬가 풀려났다! 도망가!', '수에쉬가 풀려났다! 도망가!', 25549),
(122542, 'koKR', '우린 모두 죽을 거야!', '우린 모두 죽을 거야!', 25549),
(122541, 'koKR', '내 섬을 차지하고 싶다고?! 좋아! 섬을 온통 네 피로 칠해 주마! ', '', 25549),
(122540, 'koKR', '', '은빛 성기사단을 위해 명예롭게 싸우겠습니다, $ct님.', 25549),
(122539, 'koKR', '뭐지?', '뭐지?', 25549),
(122538, 'koKR', '하! 너의 마나마귀들은 어디에 있나?!', '하! 너의 마나마귀들은 어디에 있나?!', 25549),
(122537, 'koKR', '청소할 거 있나?', '', 25549),
(122536, 'koKR', '이야기할 시간 없다. 청소해야 된다.', '', 25549),
(122535, 'koKR', '바빠. 아주 바빠. 일... 일 해야 돼.', '', 25549),
(122534, 'koKR', '준비됐습니다. 울두아르로 갑시다!', '준비됐어요. 울두아르로 가요!', 25549),
(122533, 'koKR', '어서 갑시다, $n!', '', 25549),
(122532, 'koKR', '내 섬을 빼앗진 못해!', '', 25549),
(122531, 'koKR', '슬픈 일이지만, 해야만 하는 일이었소. 내가 엘룬의 눈물을 준비하겠소. 보랏빛 성채에서 다시 만납시다.', '', 25549),
(122530, 'koKR', '네 망할 섬이나 찾아 봐라!', '', 25549),
(122529, 'koKR', '이건 내 섬이다!', '', 25549),
(122528, 'koKR', '경비병이 코를 킁킁대더니 작게 꿍얼거립니다.', '', 25549),
(122527, 'koKR', '기꺼이.', '기꺼이.', 25549),
(122526, 'koKR', '놀랍군요! 당신처럼 젊은 영웅이 역사에 시간을 쏟아주다니 정말 기분 좋습니다. 결국, 우리가 무엇을 남기는지가 중요하다고 말하는 이들이 있을 겁니다.\n\n정말 수고해주셨으니 보답으로 여기 완전히 다른 책을 한 권 드리겠습니다. 어떠십니까?', '', 25549),
(122525, 'koKR', '전권을 모았습니다.', '전권을 모았습니다.', 25549),
(122524, 'koKR', '용사여, 한참 찾았소! 아, 수정구 안의 머리 말이오? 내가 뭔가 새로운 걸 시도하는 중이오.', '', 25549),
(122523, 'koKR', '<홀로 남은 방랑자에게 뭔가 끔찍한 일이 벌어졌습니다.>\n\n<안타깝게도, 풀어줄 방법이 없습니다.>', '', 25549),
(122522, 'koKR', '<홀로 남은 방랑자에게 뭔가 끔찍한 일이 벌어졌습니다.>', '', 25549),
(122521, 'koKR', '은빛 성기사단 기사단원을 모집합니다.', '은빛 성기사단 기사단원을 모집합니다.', 25549),
(122520, 'koKR', '은빛 성기사단 기사를 모집합니다.', '은빛 성기사단 기사를 모집합니다.', 25549),
(122519, 'koKR', '오늘은 무엇을 도와드릴까요?', '오늘은 무엇을 도와드릴까요?', 25549),
(122518, 'koKR', 'Gamer timer', 'Gamer timer', 25549),
(122517, 'koKR', 'End current round', 'End current round', 25549),
(122516, 'koKR', 'Tier 4 Defended', 'Tier 4 Defended', 25549),
(122515, 'koKR', 'Tier 3 Defended', 'Tier 3 Defended', 25549),
(122514, 'koKR', 'Tier 2 Defended', 'Tier 2 Defended', 25549),
(122513, 'koKR', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 소비하여 삼지창에 힘을 불어넣습니다.>', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 소비하여 삼지창에 힘을 불어넣습니다.>', 25549),
(122512, 'koKR', 'Tier 1 Defended', 'Tier 1 Defended', 25549),
(122511, 'koKR', '이 평범한 무기에는 숨겨진 힘이 있을 것 같습니다.', '', 25549),
(122510, 'koKR', '동부 내륙지 관문 쪽에서 수상한 야생의 비명이 들립니다.', '동부 내륙지 관문 쪽에서 수상한 야생의 비명이 들립니다.', 25549),
(122509, 'koKR', '페랄라스 관문 쪽에서 수상한 야생의 비명이 들립니다.', '페랄라스 관문 쪽에서 수상한 야생의 비명이 들립니다.', 25549),
(122508, 'koKR', '그늘숲 관문 쪽에서 수상한 야생의 비명이 들립니다.', '그늘숲 관문 쪽에서 수상한 야생의 비명이 들립니다.', 25549),
(122507, 'koKR', '', '제대로 죽이고 싶으면, 직접 죽이는 게 제일이지...', 25549),
(122506, 'koKR', '', '군단의 힘을 똑똑히 보여 주마!', 25549),
(122505, 'koKR', '이 한목숨, 빛을 위하여.', '이 한목숨, 빛을 위하여.', 25549),
(122504, 'koKR', '당신을 위해 싸우겠습니다.', '당신을 위해 싸우겠습니다.', 25549),
(122503, 'koKR', '등 뒤에서 뭔가 휙 지나가는 소리가 들리더니 고요해집니다.', '등 뒤에서 뭔가 휙 지나가는 소리가 들리더니 고요해집니다.', 25549),
(122502, 'koKR', '좋은... 싸움이었어...', '', 25549),
(122501, 'koKR', '너를... 저주한다...', '', 25549),
(122500, 'koKR', '아, 연습하기 전에 준비 운동으로 딱 좋은 상대로군.', '', 25549),
(122499, 'koKR', '나는 주인님의 아들이다. 넌 나와 상대도 안 돼.', '', 25549),
(122498, 'koKR', '빛의 이름으로 아군을 돕고 황천빛 사원을 지켜야 합니다. 차원문으로!', '', 25549),
(122497, 'koKR', '무장을 갖추고 싸울 준비를 마쳤습니다, 대사제님.', '', 25549),
(122496, 'koKR', '불타는 군단이 공격을 시작했습니다. 황천빛 사원을 방어해야 합니다!', '불타는 군단이 공격을 시작했어요. 황천빛 사원을 방어해야 해요!', 25549),
(122495, 'koKR', '때맞춰 도착한 것 같군요.', '', 25549),
(122494, 'koKR', '폭탄! 폭탄이 필요해! 폭탄 더 가져와!', '', 25549),
(122493, 'koKR', '이놈들! 놈리건은 내 꺼란 말이야!', '', 25549),
(122492, 'koKR', '기사단이여! 우리의 때가 왔다!', '', 25549),
(122491, 'koKR', '네가 준비를 마치면, 난 상층에서 기다리고 있겠다, 죽음군주여.', '', 25549),
(122490, 'koKR', '내가 4인 기사단의 지도자가 되어야 할 때가 왔다.', '', 25549),
(122489, 'koKR', '공포흉터는 네 것이다, 대군주.\n\n적의 세계가 네 발 아래 쓰러지길.', '', 25549),
(122488, 'koKR', '', '신하들아! 의식을 계속하는 동안 우릴 지켜라!', 25549),
(122487, 'koKR', '걱정하지 마십시오. 제가 밤샘의 힘을 끌어내 놈들을 없애겠습니다!', '', 25549),
(122486, 'koKR', '침입자다!', '', 25549),
(122485, 'koKR', '침입했다는 사실이 발각되었습니다. 하지만 의식은 계속됩니다.', '침입했다는 사실이 발각되었습니다. 하지만 의식은 계속됩니다.', 25549),
(122484, 'koKR', '|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s|1이;가; |cFFFF0000|Hspell:226089|h[어둠의 환영]|h|r을 소환했습니다! 추방하십시오!', '|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s|1이;가; |cFFFF0000|Hspell:226089|h[어둠의 환영]|h|r을 소환했습니다! 추방하십시오!', 25549),
(122483, 'koKR', '준비됐습니다.', '준비됐습니다.', 25549),
(122482, 'koKR', '대드루이드님, 세월의 씨앗으로 저를 찾아오십시오. 그대의 무기에 얽힌 또 다른 비밀을 함께 파헤칩시다.', '', 25549),
(122481, 'koKR', '악몽이 당신을 덮칩니다!', '악몽이 당신을 덮칩니다!', 25549),
(122480, 'koKR', '때가 왔다! 은빛 성기사단의 선봉대여. 진격하라!', '때가 왔다! 은빛 성기사단의 선봉대여. 진격하라!', 25549),
(122479, 'koKR', '명예와 영광을 위해!', '명예와 영광을 위해!', 25549),
(122478, 'koKR', '네, 돌려보내 주십시오. 먼저 해야 할 일이 많습니다.', '네, 돌려보내 주세요. 먼저 해야 할 일이 많아요.', 25549),
(122477, 'koKR', '이곳에서의 임무는 매우 중요합니다. 하지만 추가로 준비하셔야 할 게 있다면, 제가 에테리움으로 돌려보내 드릴 수도 있습니다. 돌아가시겠습니까?', '이곳에서의 임무는 매우 중요합니다. 하지만 추가로 준비하셔야 할 게 있다면, 제가 에테리움으로 돌려보내 드릴 수도 있습니다. 돌아가시겠습니까?', 25549),
(122476, 'koKR', '아직 준비되지 않았습니다.', '아직 준비되지 않았어요.', 25549),
(122475, 'koKR', '<차원문이 마법으로 윙윙거립니다.>', '', 25549),
(122474, 'koKR', '해독 중', '해독 중', 25549),
(122473, 'koKR', '기꺼이 힘을 보태겠습니다.', '기꺼이 힘을 보태겠습니다.', 25549),
(122472, 'koKR', '은빛 성기사단의 성기사들이여, 앞으로 나가 전투에 임하라!', '은빛 성기사단의 성기사들이여, 앞으로 나가 전투에 임하라!', 25549),
(122471, 'koKR', '가세. 수호자의 가열로에서 만나세.', '', 25549),
(122470, 'koKR', '이 악마들이 무슨 끔찍한 피조물을 풀어 놓은 거지?! 어머니 달이여, 도와주소서!', '', 25549),
(122469, 'koKR', '저승바람 고개 위 달라란에서 만납시다. 계획이 있소. 끔찍하게 위험한 계획이지만... 그래도 계획은 계획이지!', '', 25549),
(122468, 'koKR', '악마들을 뒤틀린 황천으로 돌려보내고 이 세계를 구하려면, 창조의 근원이 필요하오.', '', 25549),
(122467, 'koKR', '달라란이 공격받고 있소! 군단이 우릴 하늘에서 떨어뜨리려 하오!', '', 25549),
(122466, 'koKR', '', '당당하게 휘장을 착용하세요, $n 님. 붉은색이 상처를 감춰 줄 겁니다.', 25549),
(122465, 'koKR', '하! 전 딱 일곱 마디까지만 쓸 수 있습니다.', '', 25549),
(122464, 'koKR', '당신의 글에 대해 자세히 알려 주십시오.', '당신의 글에 대해 자세히 알려 주세요.', 25549),
(122463, 'koKR', '휴식이 필요합니다.', '휴식이 필요합니다.', 25549),
(122462, 'koKR', '달빛 수호자여, 내게 마력을 집중해라! 이 괴물들에게 비전의 힘을 보여주자!', '', 25549),
(122461, 'koKR', '뒤쪽입니다! 다른 지옥아귀가 열렸습니다!', '', 25549),
(122460, 'koKR', '이게 마법의 문제입니다. 언제 역효과를 발휘할지 알 수 없다니까요!', '', 25549),
(122459, 'koKR', '전 늘 물의 정령이 싫었습니다... 이렇게 커다란 녀석은 특히 그랬죠!', '', 25549),
(122458, 'koKR', '낚시는 나중에 해도 됩니다. 이 정령을 처치할 수 있게 도와주십시오!', '', 25549),
(122457, 'koKR', '찡찡대는 겁쟁이처럼 쳐다만 보지 말고, 먼저 한 대 쳐보는 게 어떠냐?', '', 25549),
(122456, 'koKR', '', '덤벼라, 더러운 이방인 녀석. 네가 먼저 한 대 치게 해주마. 아주 잘 쳐야 할 거다.', 25549),
(122455, 'koKR', '축복 요청', '축복 요청', 25549),
(122454, 'koKR', '', '우리가 당신과 함께할 것입니다.', 25549),
(122453, 'koKR', '', '엘리산드는 배반의 대가를 치를 거예요.', 25549),
(122452, 'koKR', '감옥 관문을 파괴했다! 달라란으로 가는 길이 뚫렸어!', '', 25549),
(122451, 'koKR', '처음부터 내 말을 듣고, 이런 일이 일어나기 전에 사티로스를 모두 없앴어야 했다.\n\n고맙다, $p. 네가 날 자비우스의 광기로부터 구했다.', '', 25549),
(122450, 'koKR', '', '밤샘의 힘이 저를 부르는군요.', 25549),
(122449, 'koKR', '', '집으로 돌아오려고 정말 오랫동안 기다렸어요...', 25549),
(122448, 'koKR', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 사용하여 지맥 에너지를 일부 추출합니다.>', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 사용하여 지맥 에너지를 일부 추출합니다.>', 25549),
(122447, 'koKR', '전진하시오. 여기서 시간을 끌 순 없소.', '', 25549),
(122446, 'koKR', '수호물이 넘치는 에너지로 고동칩니다.', '', 25549),
(122445, 'koKR', '군단은 오늘 무너질 거요, 용사여.', '', 25549),
(122444, 'koKR', '굴단이 의식을 마치기 전에 막아야 하오.', '', 25549),
(122443, 'koKR', '고야 마님은 남은 물건을 챙겨서 떠나셨다. 여기는 내가 맡으라고 하셨다. 하늘 도시가 어쩌고 말씀하셨다. 하! 도시는 날지 못하는데!', '', 25549),
(122441, 'koKR', '청명의 정수의 힘이 우릴 악몽의 중심으로 이끌어 줄 수 있겠습니까?', '청명의 정수의 힘이 우릴 악몽의 중심으로 이끌어 줄 수 있을까요?', 25549),
(122440, 'koKR', '황천빛 사원을 방어할 준비를 마쳤습니다.', '황천빛 사원을 방어할 준비를 마쳤어요.', 25549),
(122439, 'koKR', '더는 기다릴 수 없네. 군단에 정면으로 맞서야 하네.', '', 25549),
(122438, 'koKR', '정찰을 계속해야 합니다. 이와 같은 공격이 어디에서 얼마나 더 계속될지는 알 수 없습니다.', '', 25549),
(122437, 'koKR', '악마들이 이보다는 강할 줄 알았는데. 지옥의 군주를 찾아보세. 난 늘 지옥의 군주의 정수를 차지하고 싶었거든.', '', 25549),
(122436, 'koKR', '의식이 중단되었습니다. 밤샘 안에 머무는 형체가 깨어납니다.', '의식이 중단되었습니다. 밤샘 안에 머무는 형체가 깨어납니다.', 25549),
(122435, 'koKR', '첩탑 내에서 복잡한 의식과 관련된 차분한 주문과 걸음 소리가 들립니다.', '첩탑 내에서 복잡한 의식과 관련된 차분한 주문과 걸음 소리가 들립니다.', 25549),
(122434, 'koKR', '악몽의 수호자가 쓰러졌습니다. 자비우스에게 가는 길을 열려면 또 어떻게 해야 합니까?', '악몽의 수호자가 쓰러졌어요. 자비우스에게 가는 길을 열려면 또 어떻게 해야 하죠?', 25549),
(122433, 'koKR', '해냈구나, 영웅이여! 눈동자가 해제됐다. 준비되면 말해라. 바로 열어주겠다.', '', 25549),
(122432, 'koKR', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 20을 공물로 바칩니다.>', '<고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 20을 공물로 바칩니다.>', 25549),
(122431, 'koKR', '엑슈로투스의 아들인 잿망울, 새로운 서리불꽃의 격노가 너에게 요긴한 것을 내리려고 하노라.', '', 25549),
(122430, 'koKR', '$ct, 너는 부름을 받았다. 날 따라와라.', '', 25549),
(122429, 'koKR', '이 샘은 한동안 아무도 사용하지 않은 것처럼 보입니다.', '', 25549),
(122421, 'koKR', '얼라이언스의 영웅들이여, 아제로스의 위기를 맞아 이 편지를 쓴다. 지옥의 아귀에서, 군단의 불타는 악마들이 돌아왔다.', '', 25549),
(122420, 'koKR', '훌륭하네. 그 무기에 노련함까지... 제아무리 발라리아르여도 어린 종족들에게 배울 게 있다는 걸 깨달았네. 긴 세월을 살았지만, 처음 보는 적들에 새로운 전투 기술까지 모르는 것 투성이로군. 해야 할 일이 많아졌어. 고맙네.', '', 25549),
(122419, 'koKR', '적을 막으십시오! 도시를 잃을 순 없습니다!', '', 25549),
(122418, 'koKR', '방심한 사이에 당했다네! 저 악마들을 진짜로 끝장내야겠어!', '', 25549),
(122417, 'koKR', '자비우스를 막지 못하면, 악몽이 온 아제로스를 집어삼킬 것이다.', '', 25549),
(122416, 'koKR', '지연되더라도 해야 할 일이다. 숨을 쉬는 자는 모두 싸워라! 다들 준비됐-', '', 25549),
(122415, 'koKR', '가만히 서 계시지 마세요, $n 님! 악마들은 스스로 물러나지 않아요!', '', 25549),
(122414, 'koKR', '전쟁군주!', '', 25549),
(122413, 'koKR', '|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|t$n|1이;가; 죽으면서 |cFFFF0000|Hspell:202663|h[폭발]|h|r합니다!', '', 25549),
(122412, 'koKR', '사라져라!', '사라져라!', 25549),
(122411, 'koKR', '', '어서 그 모조 혼합을 마무리해라! 부서진 해변으로 가져가야 해!', 25549),
(122410, 'koKR', '이 악몽에서 깨워주십시오!', '이 악몽에서 깨워주세요!', 25549),
(122409, 'koKR', '이곳은... 내 생각보다도 더 끔찍하군.', '', 25549),
(122408, 'koKR', '|TInterface\\Icons\\sha_spell_shadow_shadesofdarkness_nightmare:20|t%s|1이;가; |cFFFF0000|Hspell:214876|h[악몽의 괴수]|h|r를 부릅니다!', '', 25549),
(122407, 'koKR', '', '실버문이 그대를 지지합니다, $n 님. 신성한 힘으로 그대의 무기를 축복할 수 있게 허락해 주십시오.', 25549),
(122406, 'koKR', '$n, 악마의 칼날은 방어구에 난 가장 작은 갈라짐도 찾아낸다네. 모두 수리하지 않으면 험한 꼴을 당하게 될 거야.', '', 25549),
(122405, 'koKR', '<방어막에 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 20을 넣습니다.>', '<방어막에 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 20을 넣습니다.>', 25549),
(122404, 'koKR', '<이 방어막은 동력을 잃은 것 같습니다.>', '', 25549),
(122403, 'koKR', '지상으로 돌아가고 싶습니다.', '지상으로 돌아가고 싶습니다.', 25549),
(122402, 'koKR', '이제부터 걸어야 할 길에 확신이 없다면, 제가 위로 올려보내 드릴 수 있습니다. 그렇게 하시겠습니까?', '', 25549),
(122401, 'koKR', '', '제 실력은 최고라고요!$b$b그런데 최근 경쟁자가 생겼단 소문이 들리더군요. 도시 바깥에서 누군가 대장장이 일을 하고 있다던데.$b$b도전은 언제나 환영입니다. 덤비라 하세요! 하하하!', 25549),
(122400, 'koKR', '', '저런.$b$b당신 방어구, 수리가 필요해 보이는데요.', 25549),
(122399, 'koKR', '반갑습니다. 무엇이 필요하신가요?', '', 25549),
(122398, 'koKR', '', '앉아서 좀 쉬시죠!', 25549),
(122397, 'koKR', '', '안타깝게도 포도주는 떨어졌어요. 하지만 먹을 것도 마실 것도, 쓰라린 발을 쉬게 할 곳도 충분하답니다!', 25549),
(122396, 'koKR', '', '오, 안녕하세요!$b$b무엇을 도와 드릴까요?', 25549),
(122395, 'koKR', '', '수정이 충전되었습니다. 원하는 대로 사용하세요.', 25549),
(122394, 'koKR', '<썩은창자가 당신을 향해 크게 트림합니다.>$b$b썩은창자... 썩은... 창자!', '', 25549),
(122393, 'koKR', '', '창조술사들이여, 정신을 집중하십시오!', 25549),
(122392, 'koKR', '그하니르의 수호자여! 그대를 믿습니다, $n 님.', '그하니르의 수호자여! 그대를 믿습니다, $n 님.', 25549),
(122391, 'koKR', '$n 님이다! 그하니르에서 타락을 걷어낸 영웅이시지!', '$n 님이다! 그하니르에서 타락을 걷어낸 영웅이시지!', 25549),
(122390, 'koKR', '그하니르가 선한 이의 손에 들어가서 기쁩니다.', '그하니르가 선한 이의 손에 들어가서 기쁩니다.', 25549),
(122389, 'koKR', '그하니르의 수호자다! 엘룬이 그대를 축복하길, $n 님!', '그하니르의 수호자다! 엘룬이 그대를 축복하길, $n 님!', 25549),
(122388, 'koKR', '세나리온 의회에 그대가 있어서 기쁩니다, 송곳니를 휘두르는 자여!', '세나리온 의회에 그대가 있어서 기쁩니다, 송곳니를 휘두르는 자여!', 25549),
(122387, 'koKR', '달라란은 동부 왕국을 지키기 위해 자리를 옮겼소. 저승바람 고개의 카라잔 바로 위에 있으니, 여기로 와 주시오.', '', 25549),
(122386, 'koKR', '$n, 그 단검들이 뭔지 압니다. 아샤메인의 송곳니 아닙니까? 그걸 지니고 계신 걸 보니 잿빛 드루이드들에게 대단히 큰일을 해주셨나 봅니다.', '$n, 그 단검들이 뭔지 압니다. 아샤메인의 송곳니 아닙니까? 그걸 지니고 계신 걸 보니 잿빛 드루이드들에게 대단히 큰일을 해주셨나 봅니다.', 25549),
(122385, 'koKR', '그런 중요한 일을 방해하고 싶진 않지만, 외교상의 문제에 당신 도움이 필요하오. 내 잘못으로 옛 친구가 화를 내지는 않을지 걱정이라오.', '', 25549),
(122384, 'koKR', '안녕하시오, 영웅이여. 당신이 군단의 침략에 맞서 싸우고 있다는 풍문은 들었소.', '', 25549),
(122383, 'koKR', '아샤메인의 송곳니! 잿빛 드루이드들이 그 성물을 자기들 눈 닿지 않는 곳에 둘 리가 없다고 생각했는데!', '아샤메인의 송곳니! 잿빛 드루이드들이 그 성물을 자기들 눈 닿지 않는 곳에 둘 리가 없다고 생각했는데!', 25549),
(122382, 'koKR', '이상하게 생긴 단검이로군요. 혹시... 이빨입니까?', '이상하게 생긴 단검이로군요. 혹시... 이빨입니까?', 25549),
(122381, 'koKR', '아샤메인의 송곳니! 잿빛 성소가 공격받았단 소문이 사실이었군요!', '아샤메인의 송곳니! 잿빛 성소가 공격받았단 소문이 사실이었군요!', 25549),
(122380, 'koKR', '', '테시스가 자신의 배 중 한 척을 내줄 거예요. 육지가 보이지 않는 곳까지 그 배를 타고 간 후에 물 위로 어둠과 안개가 짙게 깔리면, 테시스가 작은 배로 우리를 해안에 데려다줄 거예요.\n\n출발 준비가 되면 말씀해주세요, $n 님.', 25549),
(122379, 'koKR', '우르속의 선택을 받은 대드루이드 $n 님께 경례!', '우르속의 선택을 받은 대드루이드 $n 님께 경례!', 25549),
(122378, 'koKR', '우리의 용사가 우르속의 발톱을 지니고 있군요! 군단이 활개 치고 다닐 날도 얼마 남지 않았습니다!', '우리의 용사가 우르속의 발톱을 지니고 있군요! 군단이 활개 치고 다닐 날도 얼마 남지 않았습니다!', 25549),
(122377, 'koKR', '$n 님이 우르속의 발톱을 휘두른다는 소문이 사실이었군요!', '$n 님이 우르속의 발톱을 휘두른다는 소문이 사실이었군요!', 25549),
(122376, 'koKR', '엄청나게 날카로워 보이는 발톱이로군요. 그대가 우리 편이어서 기쁩니다!', '엄청나게 날카로워 보이는 발톱이로군요. 그대가 우리 편이어서 기쁩니다!', 25549),
(122375, 'koKR', '반갑습니다, 샨도. 낫의 주인을 만나다니 영광입니다.', '반갑습니다, 샨도. 낫의 주인을 만나다니 영광입니다.', 25549),
(122374, 'koKR', '엘룬의 낫이라니! 살기 위해 그런 무기의 힘을 빌려야 할 정도라니, 정말 종말의 날이 가까운가 봅니다.', '엘룬의 낫이라니! 살기 위해 그런 무기의 힘을 빌려야 할 정도라니, 정말 종말의 날이 가까운가 봅니다.', 25549),
(122373, 'koKR', '들고 계신 게 엘룬의 낫이 아닙니까? 그게 정말 그대를 야수로 바꾸나요?', '들고 계신 게 엘룬의 낫이 아닙니까? 그게 정말 그대를 야수로 바꾸나요?', 25549),
(122372, 'koKR', '샨도, 낫을 조심해서 다뤄 주십시오. 전 제정신을 잃고 싶지 않습니다.', '샨도, 낫을 조심해서 다뤄 주십시오. 전 제정신을 잃고 싶지 않습니다.', 25549),
(122371, 'koKR', '엘룬 아도... 잠깐, 지금 들고 계신 건 엘룬의 낫 아닙니까? 놀랍군요!', '엘룬 아도... 잠깐, 지금 들고 계신 건 엘룬의 낫 아닙니까? 놀랍군요!', 25549),
(122370, 'koKR', '', '의식이 완료되었네. 어서 담게!', 25549),
(122369, 'koKR', '', '좋아, 좋아! 작동하는군!', 25549),
(122368, 'koKR', '', '소환사들이여, 의식을 시작해라!', 25549),
(122367, 'koKR', '', '과거에 저질렀던 만행은 내가 오롯이 짊어져야 할 짐입니다. 하지만 불타는 군단은 붉은십자군을 타락시켜 정의의 길에서 멀어지게 만들었어요.$b$b불타는 군단의 배신에 대한 죄를 반드시 물을 것입니다.', 25549),
(122366, 'koKR', '고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 20을 소비합니다. 계속하시겠습니까?', '고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 20을 소비합니다. 계속하시겠습니까?', 25549),
(122365, 'koKR', '<버림받은 나이트본에게 5의 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t고대 마나를 공급합니다.>', '<버림받은 나이트본에게 5의 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t고대 마나를 공급합니다.>', 25549),
(122364, 'koKR', '샬아란을 새로운 집으로 삼으시겠습니까?', '샬아란을 새로운 집으로 삼으시겠습니까?', 25549),
(122363, 'koKR', '이곳을 귀환 지점으로 삼고 싶습니다.', '이곳을 귀환 지점으로 삼고 싶습니다.', 25549),
(122362, 'koKR', '물건을 보고 싶습니다.', '물건을 보고 싶습니다.', 25549),
(122361, 'koKR', '', '저리 가버려, 이 말썽꾸러기야!', 25549),
(122360, 'koKR', '비행선이 고장 났어요! 다들 바짝 긴장해요!', '', 25549),
(122359, 'koKR', '비켜요! 비행선이 제멋대로 움직이고 있어요!', '', 25549),
(122358, 'koKR', '조심해요! 비행선이 말을 안 들어요!', '', 25549),
(122357, 'koKR', '비켜요! 이 녀석에게 안전은 안중에도 없어요!', '', 25549),
(122356, 'koKR', '비켜요, 비켜! 여기 뭐가 씌었는지 알 수 없으니까요!', '', 25549),
(122355, 'koKR', '뭘 찾소?', '', 25549),
(122354, 'koKR', '', '내가 도와줄 일이라도 있어?', 25549),
(122353, 'koKR', '으스러진 손이 호드의 예전 명예를 되찾을 걸세!', '', 25549),
(122352, 'koKR', '무얼 도와드릴까요, $n 님?', '', 25549),
(122351, 'koKR', '', '이 정령들은 불타는 군단과의 전투에서 쓸 만한 아군이 될 거예요.', 25549),
(122350, 'koKR', '안녕하세요.', '', 25549),
(122349, 'koKR', '뭘 찾소?', '', 25549),
(122348, 'koKR', '무슨 일로 오셨나요?', '', 25549),
(122347, 'koKR', '', '임프들이 황천군주님을 잘 모셨으면 좋겠군요.', 25549),
(122346, 'koKR', '', '이 궁수들은 백발백중이니 걱정하지 마세요.', 25549),
(122345, 'koKR', '이 발라리아르 지원자들은 불타는 군단과의 전투에서 우리를 도울 것이다!', '', 25549),
(122344, 'koKR', '시시하구나!', '', 25549),
(122343, 'koKR', '지옥불을 받아라!', '', 25549),
(122342, 'koKR', '보이지도 않는 노움 주제에! 그렇게 까불더니 무덤을 파는구나!', '', 25549),
(122341, 'koKR', '뼈에서 살을!', '', 25549),
(122340, 'koKR', '불타는 군단의 에레다르 군주, 자락서스 님이 상대해주마!', '', 25549),
(122339, 'koKR', '세상에... 출납원 지에게 제가 아직도 여기서 어서 상황이 평소로 돌아가길 기다리고 있다고 전해 주십시오. 감사합니다.', '', 25549),
(122338, 'koKR', '소중하신 고객님이시네요! 어서 오십시오!', '', 25549),
(122337, 'koKR', '아무 문제 없습니다! 평소처럼 생활하십시오. 저희가 상황을 잘 통제하고 있습니다.', '', 25549),
(122336, 'koKR', '지에게 제가 추가 급료를 요청할 거라고 전해 주십시오. 엄밀히 말하면 아직 카운터 뒤에 있으니까요.', '', 25549),
(122335, 'koKR', '곧 모두 해결하겠습니다! 조금만 기다려 주십시오.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122334, 'koKR', '매우 정상적인 상황입니다. 괜히 걱정하지 마십시오!', '', 25549),
(122333, 'koKR', '저희는 상황을 잘 파악하고 있으며, 문제를 완벽히 통제하고 있습니다!', '', 25549),
(122332, 'koKR', '', '재대결할 준비가 됐나? 언제 어디서든 대환영이다.', 25549),
(122330, 'koKR', '안전한 곳으로 가겠습니다. 다시는 잡히지 않을 거예요!', '안전한 곳으로 가겠습니다. 다시는 잡히지 않을 거예요!', 25549),
(122329, 'koKR', '정말... 감사합니다. 저놈들 배가 고프기 시작한 것 같았어요...', '정말... 감사합니다. 저놈들 배가 고프기 시작한 것 같았어요...', 25549),
(122328, 'koKR', '그 끔찍한 곳에서 절 구해 주셔서 감사해요.$b$b전 물건을 고치는 데 꽤나 재능이 있답니다. 혹시 뭔가 수리할 게 있으신가요?', '', 25549),
(122327, 'koKR', '사운드 카드가 정상 작동하고 있습니다.', '', 25549),
(122326, 'koKR', '전망이 불확실하오. 에펙시스 수정 4289개를 모은 후 다시 물어보시오.', '', 25549),
(122325, 'koKR', '이 시간의 길에서는 안 되오.', '', 25549),
(122324, 'koKR', '내 정보원과 상의해 보겠소... 그렇소.', '', 25549),
(122323, 'koKR', '내 정보원과 상의해 보겠소... 아니오.', '', 25549),
(122322, 'koKR', '당신은 아마 살아남을 거요. 그럴 가능성이 크지.', '', 25549),
(122321, 'koKR', '대답이... 흐릿하군... 다시 하겠소?', '', 25549),
(122320, 'koKR', '패배가 확실하오.', '', 25549),
(122319, 'koKR', '결과는 명백하오. 분명히 죽을 거요!', '', 25549),
(122318, 'koKR', '아니... 지 않소.', '', 25549),
(122317, 'koKR', '', '그리고 일어나, 모두의 방패이자 헌신의 손, 징벌의 검으로 다시 태어나겠습니다.', 25549),
(122316, 'koKR', '나는 내 왕국과 백성을 실망시켰소... 이 세계까지 잃진 않겠소.', '', 25549),
(122315, 'koKR', '며칠 후에 다시 찾아 주십시오. 저희는 고객의 자산을 소중하게 생각합니다...', '', 25549),
(122314, 'koKR', '여러분 자산을 보호하기 위해 저희 직원들이 쉴 틈 없이 일하고 있습니다! 마음 푹 놓으셔도 됩니다.', '', 25549),
(122313, 'koKR', '전혀 걱정할 일이 아닙니다. 거대 마법 도시를 이동시키는 데 따르는 부작용일 뿐입니다.', '', 25549),
(122312, 'koKR', '네, 네. 겉보기에는 불안하다는 거 잘 압니다. 영업이 정상화되고 나면 여러분께서 맡기신 자산도 모두 이곳에 있을 겁니다. 제가 약속하지요.', '', 25549),
(122311, 'koKR', '여러분! 여러분! 부탁드립니다... 이상해 보이겠지만, 저희가 상황을 잘 통제하고 있습니다. 물품 분실을 방지하기 위해 경비를 추가로 배치했습니다.', '', 25549),
(122310, 'koKR', '모두 물러서십시오! 도시가 이동하면서 발생하는 부작용일 뿐입니다. 곧 영업을 재개할 것입니다!', '', 25549),
(122309, 'koKR', '가지고 있는 물건을 보고 싶습니다.', '가지고 있는 물건을 보고 싶습니다.', 25549),
(122308, 'koKR', '반갑군, $n. 여기 쓸 만한 물건이 좀 있다.', '', 25549),
(122307, 'koKR', '', '황금은 이렇게 어두침침한 곳이라도 환하게 밝혀 준다고요.', 25549),
(122306, 'koKR', '어떤 물건을 팔고 있습니까?', '어떤 물건을 팔고 있습니까?', 25549),
(122305, 'koKR', '어떤 물건을 팔고 있습니까?', '어떤 물건을 팔고 있습니까?', 25549),
(122304, 'koKR', '', '당신의 불길이 활활 타오르고 있군요, $n 님.', 25549),
(122303, 'koKR', '방해하지 *딸꾹* 마라! 밤샘의 힘이 필요해...', '방해하지 *딸꾹* 마라! 밤샘의 힘이 필요해...', 25549),
(122302, 'koKR', '뭘 하시든 그릇 안에 든 과일은 먹지 마십시오.$b$b정말 형편없는 품질입니다. 수라마르 최고의 음식을 맛보고 싶다면, 제가 파는 진미를 한번 살펴보시죠.', '', 25549),
(122301, 'koKR', '가지고 있는 물건을 보고 싶습니다.', '가지고 있는 물건을 보고 싶습니다.', 25549),
(122300, 'koKR', '', '어서 오세요, $n 님! 오늘은 뭘 도와드릴까요?', 25549),
(122299, 'koKR', '가지고 있는 물건을 보고 싶습니다.', '가지고 있는 물건을 보고 싶습니다.', 25549),
(122298, 'koKR', '', '어서 오세요, $n 님! 오늘은 뭘 도와드릴까요?', 25549),
(122297, 'koKR', '', '우리가 그냥 보내진 않겠다, 켈리트레스!', 25549),
(122296, 'koKR', '가지고 있는 물건을 보고 싶습니다.', '가지고 있는 물건을 보고 싶습니다.', 25549),
(122295, 'koKR', '잘 오셨습니다, $n 님. 여기 쓸 만한 물건이 좀 있습니다.', '', 25549),
(122294, 'koKR', '성공!', '', 25549),
(122293, 'koKR', '원소가 그대와 함께하기를.', '', 25549),
(122292, 'koKR', '', '환영합니다, $n 님. 천상의 신들께서 당신을 굽어살피시길.', 25549),
(122291, 'koKR', '가지고 있는 물건을 보고 싶습니다.', '가지고 있는 물건을 보고 싶습니다.', 25549),
(122290, 'koKR', '음... 오늘은 특별한 양이 없다고요? 젠장! 내일은 운이 좀 좋으려나?', '', 25549),
(122289, 'koKR', '', '종자들은 교육시키는 데 오래 걸리긴 하지만, 이 명령만큼은 빨리 수행하도록 재촉해보겠습니다.', 25549),
(122288, 'koKR', '', '저들은 어떻게 전령의 거짓말을 믿을 수 있는 거죠? 명심하세요, 이곳에는 어둠의 마법이 서려있어요.\n\n할 수만 있다면, 무슨 방법을 써서라도 이걸 멈춰주세요. 무고한 희생이 너무나 많았어요...', 25549),
(122287, 'koKR', '토릴이 네가 우릴 도와주러 여기 왔다고 했으니, 넌 우리 불가에서 쉴 자격이 충분하다. 우리 고기와 벌꿀술도 먹어도 된다!', '', 25549),
(122286, 'koKR', '이런, 이런! 전혀 다른 모습이 되었군요.', '', 25549),
(122285, 'koKR', '제가 어렸을 땐, 이 나무들이 지금보다 더 푸르렀지요.', '', 25549),
(122283, 'koKR', '가지고 있는 물건을 보고 싶습니다.', '가지고 있는 물건을 보고 싶습니다.', 25549),
(122282, 'koKR', '쓸 만한 물건이 좀 있습니다, $n 님.', '', 25549),
(122281, 'koKR', '전투군주여, 속여서 미안하구나. 내가 직접 선택한 용사라 해도, 나는 시험에 관여해선 안 된다!', '', 25549),
(122280, 'koKR', '이 구울들은 죽음군주님의 명을 받들 것입니다.', '', 25549),
(122279, 'koKR', '천신의 메아리를 모집합니다.', '천신의 메아리를 모집합니다.', 25549),
(122278, 'koKR', '안녕하세요!', '안녕하세요!', 25549),
(122277, 'koKR', '가지고 있는 물건을 보고 싶습니다.', '가지고 있는 물건을 보고 싶습니다.', 25549),
(122276, 'koKR', '어떻게 도와주면 되겠소, $n|1이여;여;?', '', 25549),
(122275, 'koKR', '발라리아르여, 오딘의 영광이 너와 함께하길.', '', 25549),
(122274, 'koKR', '전쟁의 고대정령을 영입합니다.', '전쟁의 고대정령을 영입합니다.', 25549),
(122273, 'koKR', '<바스락거리는 나뭇잎>', '<바스락거리는 나뭇잎>', 25549),
(122272, 'koKR', '여기다, 내 $c 친구! 좋은 물건 많이 있다. 와서 보라고!', '', 25549),
(122271, 'koKR', '의식 시작', '의식 시작', 25549),
(122270, 'koKR', '서리고룡이 꿈틀대는군요.', '', 25549),
(122269, 'koKR', '자네의 위대한 업적에 대한 얘기들을 들었지. 과연 그 명성에 걸맞은 사람인지 볼까?', '', 25549),
(122268, 'koKR', '자네가 바로 오딘의 용사로군!', '', 25549),
(122266, 'koKR', '당신께 목숨을 두 번이나 빚졌군요... 가진 건 별로 없지만, 필요한 게 있다면 얼마든지 가져가십시오.', '', 25549),
(122265, 'koKR', '신발을 아낀다면 조금 물러서는 게 좋을 겁니다.', '', 25549),
(122264, 'koKR', '가지고 있는 물건을 보고 싶습니다.', '가지고 있는 물건을 보고 싶습니다.', 25549),
(122263, 'koKR', '', '옹이진 가지에 오신 걸 환영해요, $n 님.', 25549),
(122262, 'koKR', '이 아수라장을 좀 보시오! 물건이 다 이리저리 흩어지고 난리가 났소! 책은 바닥에 떨어지고, 공구도 사방팔방에 널려 있고... 제발 도시를 통째로 옮기기 전에는 미리 알려 줬으면 좋겠군!$B$B게다가 저기 도리안 좀 보시오. 아직도 충격에서 헤어나지 못하고 있다오.', '', 25549),
(122261, 'koKR', '', '$n 님, 미안하지만 당분간은 수련생을 받지 말라는 지시가 있었어요. 최종 목적지에 도착하고 나면 평소로 돌아가겠죠.', 25549),
(122260, 'koKR', '용사의 무장을 주문합니다.', '용사의 무장을 주문합니다.', 25549),
(122259, 'koKR', '시체를 가져오면 요긴하게 쓰겠소.', '', 25549),
(122258, 'koKR', '메마른 자들이에요! 우릴 덮칠 겁니다. 제발 도와주세요!', '', 25549),
(122257, 'koKR', '잠깐... 들리십니까?', '', 25549),
(122256, 'koKR', '가지고 있는 물건을 보고 싶습니다.', '가지고 있는 물건을 보고 싶습니다.', 25549),
(122255, 'koKR', '가... 감사합니다... 전... 어찌할 바를 모르겠어요... 너무 많은 것을 잃었습니다.', '', 25549),
(122254, 'koKR', '뭐가 필요해, 작은 $n?', '', 25549),
(122253, 'koKR', '<로리안에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 공급합니다.>', '<로리안에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 공급합니다.>', 25549),
(122252, 'koKR', '용사의 무장을 주문합니다.', '용사의 무장을 주문합니다.', 25549),
(122251, 'koKR', '', '빛의 축복이 함께하시길.', 25549),
(122250, 'koKR', '놈들이 죽였어요... 메마른 자들이 나의 루니엘을 죽였어요. 이제... 제게 남은 건 아무것도 없습니다.', '', 25549),
(122249, 'koKR', '이 악마사냥꾼 얘기를 들어봐야겠어요.', '', 25549),
(122248, 'koKR', '난 이 표본 작업을 마쳐야 하네, $n! 지난번 물건이 너무 불안정해서 이동 중에 모두 죽을 뻔했어!$B$B방금 그 이야긴 아무한테도 하지 말게.', '', 25549),
(122247, 'koKR', '의식 시작', '의식 시작', 25549),
(122246, 'koKR', '', '때가 되었나?', 25549),
(122244, 'koKR', '망치 충전을 시작합니다.', '망치 충전을 시작합니다.', 25549),
(122243, 'koKR', '', '네?', 25549),
(122241, 'koKR', '용사의 무장을 주문합니다.', '용사의 무장을 주문합니다.', 25549),
(122240, 'koKR', '어떻게 도와드리면 될까요?', '어떻게 도와드리면 될까요?', 25549),
(122239, 'koKR', '신호를 내려 주십시오.', '신호를 내려 주십시오.', 25549),
(122238, 'koKR', '', '뭘 원하나?', 25549),
(122237, 'koKR', '루니엘... 사랑스러운 루니엘... 왜 난 너에게 이런 일이 생기는 걸 막지 못했을까?', '', 25549),
(122236, 'koKR', '용사의 무장을 주문합니다.', '용사의 무장을 주문합니다.', 25549),
(122235, 'koKR', '뭐지?', '', 25549),
(122232, 'koKR', '신호를 보내 선봉대를 부릅니다.', '신호를 보내 선봉대를 부릅니다.', 25549),
(122231, 'koKR', '명령은?', '', 25549),
(122230, 'koKR', '|TInterface\\Icons\\spell_deathknight_necroticplague.blp:20|t 당신은 |cFFF00000|Hspell:206480|h[썩어가는 역병]|h|r에 걸렸습니다!', '', 25549),
(122229, 'koKR', '부탁드립니다... 이 괴물들을 마지막 하나까지 없애 주세요.', '부탁드립니다... 이 괴물들을 마지막 하나까지 없애 주세요.', 25549),
(122228, 'koKR', '자유... 드디어 자유로군요. 여기서 어떻게 빠져나가면 될까요?', '자유... 드디어 자유로군요. 여기서 어떻게 빠져나가면 될까요?', 25549),
(122227, 'koKR', '전... 도망칠 수 있을 것 같아요. 감사합니다.', '전... 도망칠 수 있을 것 같아요. 감사합니다.', 25549),
(122226, 'koKR', '무서워... 너무 무서워...', '무서워... 너무 무서워...', 25549),
(122225, 'koKR', '전... 안 되겠어요...', '전... 안 되겠어요...', 25549),
(122224, 'koKR', '전... 이미 너무 약해졌습니다...', '전... 이미 너무 약해졌습니다...', 25549),
(122223, 'koKR', '아직 이곳 판다리아에서 비행하는 법을 익히지 못하셨다면, 여기서 그라독을 빌려 골짜기 위를 날아볼 수 있다네.', '', 25549),
(122222, 'koKR', '상자가 다시 한 번 번쩍입니다. 한 번만 더 하면 완전히 활성화될 것입니다!', '상자가 다시 한 번 번쩍입니다. 한 번만 더 하면 완전히 활성화될 것입니다!', 25549),
(122221, 'koKR', '종 소리가 점점 커집니다.', '종 소리가 점점 커집니다.', 25549),
(122220, 'koKR', '상자에서 기분 좋은 종 소리가 연이어 울리기 시작합니다.', '상자에서 기분 좋은 종 소리가 연이어 울리기 시작합니다.', 25549),
(122219, 'koKR', '상자가 환하게 빛납니다.', '상자가 환하게 빛납니다.', 25549),
(122218, 'koKR', '다음에 누가 마법으로 도시를 옮기겠다고 얘기하면, 무슨 일이 일어나도 버틸 수 있게 준비해야 해요. 정말이지 무슨 일이 일어날지 모른다니까요!', '', 25549),
(122217, 'koKR', '"이 단추를 누르지 마시오"라고 적힌 큰 적색 단추 좀 눌러줄래?', '', 25549),
(122216, 'koKR', '하지만... 동시에 시스템이 완전히 망가질 "사소한" 위험이 있는지도 몰라.', '', 25549),
(122215, 'koKR', '도로시를 보러 오셨다면 안에 있습니다. 하지만 물건을 사러 오셨다면, 당분간은 주문을 받기가 좀 어렵습니다. 죄송합니다.', '', 25549),
(122214, 'koKR', '', '사람들이 와서 부작용에 잘 듣는 약을 찾더군요.$B$B옛날에 쓰던 조제법을 찾을 수만 있다면... 여기 어딘가에 있을 텐데!', 25549),
(122213, 'koKR', '', '그는 신경 쓰지 마세요. 건망증이 심하거든요. 출발하기 전까지만 해도 옛날 물건들이 다 잘 보관되어 있었어요.$B$B가게 정리가 좀 끝나고 나면 꼭 다시 와 주세요! 곧 최종 목적지에 도착할 테니까요!', 25549),
(122212, 'koKR', '치즈 반이 못쓰게 됐습니다! 반이요!$B$B포도주는 넘쳐 나는데 맛있는 치즈는 부스러기뿐이라면 대체 장사를 어떻게 하란 겁니까? 이건 용납할 수 없습니다! 게다가...$B$B이런! 이제 현기증까지 나는군요. 대체 세상이 어떻게 돌아가는 건지...', '', 25549),
(122211, 'koKR', '', '이제 거의 다 찾았어요! 달라란을 옮기는 게 이렇게 골치 아픈 일일 줄 누가 알았겠어요? 펜 하나하고 새만 찾으면 모든 게 평소로 돌아갈 거예요!$B$B<방을 둘러보는 타시아>$B$B어항에 든 저 불쌍한 친구만 빼면요. 곧 방법을 찾기를 바라요.', 25549),
(122210, 'koKR', '', '난장판이 따로 없네요!', 25549),
(122209, 'koKR', '', '약자를 지키겠습니다. 정의를 실현하겠습니다. 옳은 길을 걷겠습니다.', 25549),
(122208, 'koKR', '', '모두의 방패이자 헌신하는 손, 징벌의 검이 되겠습니다.', 25549),
(122207, 'koKR', '', '빛의 전사로.', 25549),
(122206, 'koKR', '', '이 맹세와 함께, 저는 다시 태어납니다.', 25549),
(122205, 'koKR', '', '형제자매와 겸허하게 섬길 것을 맹세합니다.', 25549),
(122204, 'koKR', '', '은빛 성기사단에 목숨을 바칠 것을 맹세합니다.', 25549),
(122202, 'koKR', '', '영원의 용사들이 함께하는 이곳에서, 신성한 서약을 맺습니다.', 25549),
(122201, 'koKR', '<마나호랑이에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 10을 공급합니다.>', '<마나호랑이에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 10을 공급합니다.>', 25549),
(122200, 'koKR', '<마나호랑이가 먹이를 달라는 눈으로 당신을 쳐다봅니다.>', '', 25549),
(122198, 'koKR', '떠나기 전에 어항을 비운 게 다행이에요. 안 그랬으면 전혀 다른 문제가 됐겠죠!', '', 25549),
(122197, 'koKR', '이 상황은 전혀 감이 안 잡히네요. 그냥 기다려요! 어떻게든 방법을 찾을 테니까.', '', 25549),
(122196, 'koKR', '생각할 시간이 더 필요해요. 상황이 상당히 특이하잖아요. 이런 일은... 반쪽만 할 수는 없는 일이라고요.', '', 25549),
(122195, 'koKR', '걱정하지 마요. 순식간에 꺼내 줄 테니까. 내가 왜 이것한테 계속 말을 하고 있는 거지?', '', 25549),
(122194, 'koKR', '시계 방향으로 한 번 돌리면... 아냐. 시계 반대 방향인가...', '', 25549),
(122193, 'koKR', '준비가 되면 제단에서 맹세하십시오.', '준비가 되면 제단에서 맹세하십시오.', 25549),
(122192, 'koKR', '뭐, 또 이동할 때까지 기다리는 것도 괜찮겠죠. 혹시 알아요? 그러면 저절로 해결될지!', '', 25549),
(122191, 'koKR', '', '반티르는 우리가 여기 있는 게 더 안전할 거라고 했지요. 하지만 우리 코린한테 생긴 일을 생각해 보면 동의하기 어렵군요.\n\n나이트폴른은 힘든 삶을 살아내고 있지만, 우린 견뎌낼 거예요.\n\n제 딸을 살려 주셔서 다시 한 번 감사드립니다.', 25549),
(122190, 'koKR', '집중의 수정 강화', '집중의 수정 강화', 25549),
(122189, 'koKR', '', '시작할 준비가 되었습니다.', 25549),
(122188, 'koKR', '뭐죠? 그만해요! 누군가 반대쪽에서 날 찌르고 있어요!', '', 25549),
(122187, 'koKR', '다시 점멸을 할 때까지 기다려야 할지도 모른다니, 그게 무슨 소리예요? 난 계속 여기 있을 순 없어요! 할 일이 있다고요!', '', 25549),
(122186, 'koKR', '지금껏 몰랐는데, 이 바닥의 돌은 정말 관리가 잘 돼 있네요.', '', 25549),
(122185, 'koKR', '그래요. 대신 악마라도 나타나면 날 지켜 주겠다고 약속해야 해요. 난 지금 내 몸을 지킬 수가 없거든요.', '', 25549),
(122184, 'koKR', '이런, 이런. 또 구경꾼이네. 그래요... 재미있죠? 다들 이 불쌍한 노움을 구경하러 오라고요. 여기서 내려가기만 하면...', '', 25549),
(122183, 'koKR', '속도 좀 늦춰 줘요! 가능하다면 내 다리는 멀쩡했으면 좋겠는데... 엇! 내가 지금 여기 있다면, 나머지 나는 어디 있죠?', '', 25549),
(122182, 'koKR', '전문가라고요? 난 여기 몇 시간째 갇혀 있다고요!', '', 25549),
(122181, 'koKR', '마나호랑이가 나직하게 가르랑거리며 당신이 더 가까이 오길 바라는 것 같습니다.', '', 25549),
(122180, 'koKR', '', '전 남을 돕기 위해 여사제가 되었지만, 요즘 들어서는 뭔가 더 할 수 있는 게 있지 않을까 하는 생각이 들더군요.', 25549),
(122179, 'koKR', '승천자를 영입합니다.', '승천자를 영입합니다.', 25549),
(122178, 'koKR', '승천자들은 풀어줄 수만 있지 명령으로 제어할 수는 없습니다.', '승천자들은 풀어줄 수만 있지 명령으로 제어할 수는 없습니다.', 25549),
(122177, 'koKR', '<화염술사 오빈에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 15를 공급합니다.>', '<화염술사 오빈에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 15를 공급합니다.>', 25549),
(122176, 'koKR', '내 불꽃이... 사그라집니다. 곧 이 세계를 뜨게 될 것 같군요...', '', 25549),
(122175, 'koKR', '부서진 운명의 인장을 주문합니다.', '부서진 운명의 인장을 주문합니다.', 25549),
(122174, 'koKR', '세련된 첩자의 색안경을 쓰고 피의 흔적을 찾으십시오!', '세련된 첩자의 색안경을 쓰고 피의 흔적을 찾으십시오!', 25549),
(122173, 'koKR', '무관의 연맹은 우리가 가장 뛰어난 분야인 책략과 간계, 기만, 그리고 정치를 모두 동원하여 불타는 군단을 무너뜨리기 위해 노력해야 합니다.\n\n군단을 쓰러뜨릴 때까지 $n 님, 당신과 지속적으로 협조하는 것이 저의 최우선 과제입니다. 당신에게도 그러리라 믿습니다.', '', 25549),
(122172, 'koKR', '<가속술사 비린야에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 15를 공급합니다.>', '<가속술사 비린야에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 15를 공급합니다.>', 25549),
(122171, 'koKR', '', '도와주세요... 제발. 머리가... 잘 안 돌아가요...', 25549),
(122170, 'koKR', '기꺼이 도움을 받아들이겠습니다, 델라스. 빛은 함께 빛날 때 더 강해지니까요.', '', 25549),
(122169, 'koKR', '찾았습니다! 즉시 이 지역의 방어를 강화하십시오.', '', 25549),
(122168, 'koKR', '군단은 내 앞에 전율하리라! 모든 것이 내 앞에 전율하리라!', '', 25549),
(122167, 'koKR', '너의 생명이 내 생명을 증폭시킨다! 누구도 날 막을 수 없어!', '', 25549),
(122166, 'koKR', '내가 아제로스의 징벌을 완수하겠다!', '', 25549),
(122165, 'koKR', '네가 죽어야 내가 살 수 있다! 난 운명을 실현해야 한다! 세계를 구해야 해!', '', 25549),
(122164, 'koKR', '희생해 줘서 고맙다. 너의 죽음은 헛되지 않을 것이다.', '', 25549),
(122163, 'koKR', '다른 방법이 있으면 좋겠지만, 우리가 살아남으려면 내게 힘이 필요하다.', '', 25549),
(122162, 'koKR', '네 생명의 힘이 우리 세계에 기회를 줄 것이다, 수행사제여.', '', 25549),
(122161, 'koKR', '이런 짐을 짊어지기를 원한 건 아니지만, 이게 운명의 뜻이다...', '', 25549),
(122160, 'koKR', '어둠의 길을 가시는군요, 일리단 님. 이제 돌이킬 순 없습니다...', '어둠의 길을 가시는군요, 일리단 님. 이제 돌이킬 순 없습니다...', 25549),
(122159, 'koKR', '어머니 달이여, 저를 데려가소서!', '어머니 달이여, 저를 데려가소서!', 25549),
(122158, 'koKR', '일리단 님... 왜?', '일리단 님... 왜?', 25549),
(122157, 'koKR', '우리가 살아남기 위해 내가 얼마나 희생하는지 모르겠다는 거냐?', '', 25549),
(122156, 'koKR', '너희 가족은 내가 책임지고 돌보겠다, 친구여.', '', 25549),
(122155, 'koKR', '군단의 위협은 목숨을 앗아간다. 너희 목숨을!', '', 25549),
(122154, 'koKR', '난 심판의 대상이 아니다! 나는 아제로스를 위해 움직일 뿐!', '', 25549),
(122153, 'koKR', '이 세계가 살아남으려면 너희가 죽어야 한다!', '', 25549),
(122152, 'koKR', '이런 기회를 누릴 수 있다는 것에 감사해야 한다!', '', 25549),
(122151, 'koKR', '주위를 봐라! 이게 유일한 방법이다!', '', 25549),
(122150, 'koKR', '넌 이제 더 큰 과업의 일부다, 충직한 수행사제여!', '', 25549),
(122149, 'koKR', '해야만 하는 일이다!', '', 25549),
(122148, 'koKR', '내 마법을 원한다고? 자, 맛봐라!', '내 마법을 원한다고? 자, 맛봐라!', 25549),
(122147, 'koKR', '대가를 치르게 될 거다, 일리단!', '대가를 치르게 될 거다, 일리단!', 25549),
(122146, 'koKR', '배신자!', '배신자!', 25549),
(122145, 'koKR', '우릴 공격하는 악마들과 다를 게 없어!', '넌 우릴 공격하는 악마들과 다를 게 없어!', 25549),
(122144, 'koKR', '내 마나가 필요하다고? 와서 가져가 봐라!', '내 마나가 필요하다고? 와서 가져가 봐라!', 25549),
(122143, 'koKR', '넌 우리 모두를 배신했다!', '넌 우리 모두를 배신했다!', 25549),
(122142, 'koKR', '넌 이제 대장이 아니다, 일리단! 죽어라!', '넌 이제 대장이 아니다, 일리단! 죽어라!', 25549),
(122141, 'koKR', '탑경비대! 이 악마들을 더러운 주인에게 돌려 보내자! 아즈샤라를 위하여! 칼림도어를 위하여!', '', 25549),
(122140, 'koKR', '싸우지도 않고 죽진 않겠다!', '싸우지도 않고 죽진 않겠다!', 25549),
(122139, 'koKR', '넌 괴물이다, 일리단!', '넌 괴물이다, 일리단!', 25549),
(122138, 'koKR', '내 사슬이 널 속박하리라...', '', 25549),
(122137, 'koKR', '용사의 무장을 주문합니다.', '용사의 무장을 주문합니다.', 25549),
(122136, 'koKR', '귀중한 물건을 확보하도록 도와드리지요.', '귀중한 물건을 확보하도록 도와드리지요.', 25549),
(122135, 'koKR', '그만! 이러다 죽을 수도 있습니다!', '그만! 이러다 죽을 수도 있습니다!', 25549),
(122134, 'koKR', '이러지 마십시오, 일리단 님.', '이러지 마십시오, 일리단 님.', 25549),
(122133, 'koKR', '움직일 수 없어... 힘이...', '움직일 수 없어... 힘이...', 25549),
(122132, 'koKR', '힘이 약해진다...', '힘이 약해진다...', 25549),
(122131, 'koKR', '대... 대장님, 이러다 죽겠...', '대... 대장님, 이러다 죽겠...', 25549),
(122130, 'koKR', '하수도 상어? 끔찍한 생물들이지. 나도 한 번밖에 본 적이 없어!', '', 25549),
(122129, 'koKR', '뜨끈한 맥주와 시원한 소세지 챙겨! 그리고 스키드마크한테 조가 보냈다고 해!', '', 25549),
(122128, 'koKR', '우리 형 대릴 본 사람?', '', 25549),
(122127, 'koKR', '이거 무슨 냄새지?', '', 25549),
(122126, 'koKR', '일이 계속 나빠지라는 법은 없지. 안 그래?', '', 25549),
(122125, 'koKR', '오른쪽으로 돌리고! 왼쪽으로 돌리고!', '', 25549),
(122123, 'koKR', '스탠키 본 사람 없어? 슬슬 걱정이 되는데.', '', 25549),
(122122, 'koKR', '혼자 놀기도 쉬운 게 아냐!', '', 25549),
(122120, 'koKR', '아내가 가자미 때문에 날 버렸어.', '', 25549),
(122119, 'koKR', '친구여, 여긴 지상에서 아주 높은 곳이다.\n\n내려가는 데 도움이 필요한가?', '', 25549),
(122118, 'koKR', '', '아, 안녕하세요. 뭔가 필요하거나, 누굴 시켜서 뭔가 해야 하나요?\n\n물론 그냥 이야기하고 싶은 거라도 니키가 들어 드릴게요.', 25549),
(122117, 'koKR', '예? 무슨 일이시죠?$B$B말이 짧아서 죄송하지만, 도시를 통째로 옮기기로 결정하기 전에는 미리 좀 알려 달라고 수도 없이 민원을 넣었습니다. 그런데 가게 꼴을 좀 보십시오... 사방팔방에 물건이 널려 있지 않습니까! 일다인과 바네사가 몇 달은 고생할 겁니다!$B$B실례지만 전 이제 또 도시를 옮기기로 정하기 전에 이 마법부여를 마쳐야겠습니다.', '', 25549),
(122116, 'koKR', '고마워요!', '', 25549),
(122115, 'koKR', '말씀만 하십시오. 제가 적을 드러내겠습니다!', '', 25549),
(122114, 'koKR', '', '잘 견디세요, $n 님. 우리가 필요하신 때를 대비하여 준비하고 있을게요.', 25549),
(122113, 'koKR', '', '최고의 장인에게도 때로는 휴식이 필요한 법이지요. 모피를 덮고 안전한 제 화로 곁에서 잠을 청하십시오.', 25549),
(122112, 'koKR', '바로 그롬마쉬 요새로 가 보게, $n.', '', 25549),
(122111, 'koKR', '고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 소비합니다. 계속하시겠습니까?', '고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 25를 소비합니다. 계속하시겠습니까?', 25549),
(122110, 'koKR', '<지맥직공 케로린에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 15를 공급합니다.>', '<지맥직공 케로린에게 고대 마나 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t 15를 공급합니다.>', 25549),
(122109, 'koKR', '뭔가 달라진 느낌이에요. 공기는 괜찮은데, 어딘지 이상한 느낌이 있어요.$B$B우리가 여기 도착하고서부터 사람들이 계속 이상하게 행동하고 있다고요. 그냥 이동의 여파로 어지럽다거나 한 게 아니라, 사람들의 거동이나 거리를 떠도는 속삭임 소리에 뭔가가 있어요.', '', 25549),
(122108, 'koKR', '정신이... 메말라 가는... 도움이... 필요합니다.', '', 25549),
(122107, 'koKR', '멋진 최종 영상 재생!', '멋진 최종 영상 재생!', 25549),
(122106, 'koKR', '당신에게 가격을 치를 수 있을 때 다시 오겠습니다, 알루인.', '당신에게 가격을 치를 수 있을 때 다시 오겠습니다, 알루인.', 25549),
(122105, 'koKR', '저는 문득 감정이 북받쳐 오르면 글을 씁니다.', '', 25549),
(122104, 'koKR', '', '드로그바의 공격 때문에 드릴 수 있는 건 없지만, 저희가 가진 건 모두 그대 것이기도 합니다.', 25549),
(122103, 'koKR', '', '어서오세요, 이방인이여.$b$b그대와 같은 부족은 이렇게 산 높이까지 오는 일이 많진 않지만, 그래도 언제든 환영이에요.', 25549),
(122102, 'koKR', '누가 또 이 칼날 맛을 보고 싶은 거냐?', '', 25549),
(122100, 'koKR', '응? 아, 거기 있는 줄 몰랐어요! 언제부터 $c들이 이렇게 엉큼해졌죠?$B$B곧 떠날 예정인지 알아야겠어요. 그래야 물건을 챙길 테니까요.', '', 25549),
(122099, 'koKR', '여행자여, 이리 오십시오.$b$b우리의 보금자리를 당신의 보금자리로 삼으십시오.$b$b여기 계십시오. 저희와 함께하십시오.$b$b함께하십시오...', '', 25549),
(122098, 'koKR', '악마사냥꾼? 끔찍하군! 날개는 거죽처럼 번들거리고 징그럽군요!', '악마사냥꾼? 끔찍하군! 날개는 거죽처럼 번들거리고 징그럽군요!', 25549),
(122097, 'koKR', '', '엘리아스, 당신 말이 거짓이 아니었군요. 악마사냥꾼들이 돌아다닌다는 말이요. 조심하세요. $n|1은;는; 저 눈으로 못 보는 게 없대요.', 25549),
(122096, 'koKR', '다시 만나 반갑습니다, $n 님. 잘 지내고 계시겠지요?\n\n<주위를 둘러본 후 작은 목소리로 얘기하는 마티아스>\n\n무관의 연맹 일은 어떻게 되고 있습니까? SI:7의 수장으로서, 전 공공연하게 당신을 지지할 순 없습니다.\n\n하지만 불타는 군단과의 전쟁이 끝날 때까지, 전적으로 당신을 지지하겠습니다. 비밀을 유지해야 하더라도요.\n\n다시 만날 때까지, 안녕히...', '', 25549),
(122095, 'koKR', '방패여전사를 모집하고 싶습니다.', '방패여전사를 모집하고 싶습니다.', 25549),
(122094, 'koKR', '발키르를 모집하고 싶습니다.', '발키르를 모집하고 싶습니다.', 25549),
(122093, 'koKR', '아무 돌에나 앉아도 좋아, 브룰. 나바로그가 넌 여기서 쉬어도 좋다고 했어.', '', 25549),
(122092, 'koKR', '', '악마사냥꾼이라니! 완벽합니다. 제게 딱 필요한 분이에요.', 25549),
(122091, 'koKR', '$n... 적인가요, 아군인가요? 악마의 마력이 느껴지는군요...', '', 25549),
(122090, 'koKR', '', '당신의 그... 능력을, 이 신성한 장소에서는 좀 자제해 줬으면 좋겠군요, 악마사냥꾼. 저희가 지켜볼 겁니다.', 25549),
(122089, 'koKR', '무슨 짓을 한 거요, $n? 당신은 $r|1이라기보다;라기보다; 악마 같잖소.', '무슨 짓을 한 거요, $n? 당신은 $r|1이라기보다;라기보다; 악마 같잖소.', 25549),
(122088, 'koKR', '<투덜거리는 나타노스>', '', 25549),
(122087, 'koKR', '', '용사가 허투루 핑계나 대고 있구나!', 25549),
(122086, 'koKR', '전 당신의 용사입니다, 어둠의 여왕님. 당신의 체면을 세워 드리는 게 제 의무입니다.', '', 25549),
(122085, 'koKR', '제이스 다크위버의 말이 맞았군요. 알드라치 전투검을 손에 넣으시다니... $n 님, 당신이 우리의 지도자인 이상 누구도 일리다리를 막을 수 없을 것입니다!', '제이스 다크위버의 말이 맞았군요. 알드라치 전투검을 손에 넣으시다니... $n 님, 당신이 우리의 지도자인 이상 누구도 일리다리를 막을 수 없을 것입니다!', 25549),
(122084, 'koKR', '', '내가 너보다 훨씬 더 많은 적을 처치했다, 나타노스. 실력이 많이 녹슬었구나!', 25549),
(122083, 'koKR', '$n 님! 베레디스 펠소울의 검을 손에 넣으셨군요. 그대라면 내면의 악마를 더 잘 제어하실 수 있기를 빌겠습니다.', '$n 님! 베레디스 펠소울의 검을 손에 넣으셨군요. 그대라면 내면의 악마를 더 잘 제어하실 수 있기를 빌겠습니다.', 25549),
(122082, 'koKR', '봉화를 자주 사용해라. 빛의 힘은 무한하며 항상 네게 응답할 것이다.', '', 25549),
(122081, 'koKR', '승선을 환영해, $n.\n\n필요한 물품을 모두 실었으니 이제 자네만 준비되면 즉시 출항할 수 있어.', '', 25549),
(122080, 'koKR', '네 지팡이는, 벨렌의 수정과 마찬가지로, 우리가 파멸에서 지켜주고자 하는 이들에게 내려준 선물이다. 그 수가 많지 않으니, 공허의 손에 들어가지 않도록 조심하거라.', '', 25549),
(122079, 'koKR', '역대 봉화의 주인 중 그 물건을 가장 잘 사용했던 건 드레나이였다. 다른 자들은 살아남을 수 없던 때도, 드레나이는 살아남았다.', '', 25549),
(122078, 'koKR', '봉화는 한동안 조용했었다. 도움 요청도 없었지. 네가 그것을 복원했다니, 잘 됐구나.', '', 25549),
(122077, 'koKR', '어머니... 아버지...', '', 25549),
(122076, 'koKR', '', '이 두 영웅에 대해 많은 얘길 들었습니다. 이 전언이 정말 엄청난 중요성을 지닌 것임을 전혀 의심하지 않아요.', 25549),
(122075, 'koKR', '아라토르 말대롭니다. 투랄리온과 알레리아는 온갖 역경을 무릅쓰고 이 경고를 보낸 겁니다. 대영주님, 당신이 길을 알려주십시오. 어찌해야 하겠습니까?', '', 25549),
(122074, 'koKR', '내 눈으로 직접 보지 않았다면 믿지 못했을 거요.', '', 25549),
(122073, 'koKR', '', '투랄리온과 알레리아... 그들이 그 오랜 세월 동안 살아 있었다니 믿을 수가 없군요...', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122072, 'koKR', '', '빛이여... 이건 대체 무슨 의미일까요?', 25549),
(122071, 'koKR', '', '말씀만 하시면 제가 숨은 적을 드러내겠습니다!', 25549),
(122070, 'koKR', '코코아 버터는 왜 이렇게 미끄러운 거지? 수건 가져와! 나한테 미끄러운 코코아 버터 가져온 놈, 넌 해고야!', '', 25549),
(122069, 'koKR', '가게에 잘 오셨습니다, $n님. 이렇게 엉망진창인 건 양해해 주십시오. 아직 청소를 하는 중이거든요.$B$B이번 순간이동으로 정말 제대로 한 방 먹었어요!', '', 25549),
(122068, 'koKR', '', '죄송해요. 머리가 자꾸만 어질어질해서요. 도착하고 얼마 안 있다가 증상이 시작됐어요.', 25549),
(122067, 'koKR', '', '사방팔방에 흩어진 종이 좀 보세요. 전에는 대체 어떻게 관리했던 건지도 모르겠네요.$B$B다시 정리하려면 몇 주는 걸릴 거예요!', 25549),
(122066, 'koKR', '', '아, 거기 계신 줄 몰랐네요!$B$B정리하느라 너무 바쁘거든요. 저희가 정신 좀 차리고 나면 오세요.', 25549),
(122065, 'koKR', '가게가 난장판인 건 양해해 주십시오. 얼마 전부터 열심히 치우는 중입니다.$B$B<가게를 둘러보는 라파엘> 아직 별로 티는 안 나는군요. 마치 질풍이 휩쓸고 간 것 같아요. 상품도 다 손상됐고요. 저런 물건을 누가 사려고 하겠습니까?$B$B다음에 도시를 옮긴다고 하면 다 미리미리 끈으로 고정해 놔야겠습니다.', '', 25549),
(122064, 'koKR', '흐음... $n, 지금은 물건이 아예 없소. 추후 공지가 있을 때까지 배송이 불가능하거든. 도시를 순간이동시키다니... 누가 그 따위 생각을 한 건지. 이 아수라장이 제자리를 찾으려면 몇 주는 걸릴 거요.', '', 25549),
(122063, 'koKR', '', '당분간은 이 여관에 묵지 않는 게 좋을지도 모르네. 다음에 돌아오려고 할 때는 여기 있지 않을지도 모르거든.', 25549),
(122062, 'koKR', '', '아아!', 25549),
(122061, 'koKR', '무슨 일이 벌어지고 있는 건지 아십니까?', '무슨 일이 벌어지고 있는 건지 아십니까?', 25549),
(122060, 'koKR', '', '그대도 느껴지나요? 온몸에 소름이 돋는군요...', 25549),
(122059, 'koKR', '', '으읔. 그 검... 뭘 들고 계시는 거죠? 죽음의 기사여, 그대 주위에 질병과 썩은 기운이 맴돌고 있어요!', 25549),
(122058, 'koKR', '', '죽음의 기사, 당신이 들고 있는 악마의 칼에서 타락의 기운이 새어 나오고 있습니다. 어서 볼일을 마치고 그 칼날을 이 신성한 신전으로부터 멀리 옮겨놓으십시오.', 25549),
(122057, 'koKR', '죽음의 기사여, 질병과 전염병의 기운이 그 검을 감싸고 있다. 세네고스에게서 멀리 떨어져라.', '', 25549),
(122056, 'koKR', '', '언더시티에 도는 소문이 사실이었군. 서리한이 다시 벼려졌다니! 몸조심하게, $n|1이여;여;. 그 칼날은 자아를 가지고 있네.', 25549),
(122055, 'koKR', '어찌 이런 불경스러운... 어떻게 감히 그 저주받은 칼날을 다시 벼릴 수 있단 말인가, $n? 그 검은 로데론과 그 왕자를 파멸시킨 물건이잖나? 난 과거에도 아서스에게 서리한과 접촉하지 말라고 했고, 지금 자네에게도 말하겠네. 우리 모두를 파멸시키기 전에 그 물건을 당장 바닷속에 던져버리게.', '', 25549),
(122054, 'koKR', '', '그건... 저주받은 자의 아귀가 아닙니까? 군단의 무기로 그들에게 맞선다는 건가요? 멋진 생각입니다, $n 님!', 25549),
(122053, 'koKR', '누군지 몰라도 쓴맛을 보여주겠어! 떡대들! 도둑 잡아! 도둑 잡아!!', '', 25549),
(122052, 'koKR', '잠깐... 내 열쇠가... 으아! 누군가 내 금고 열쇠를 훔쳐갔잖아!', '', 25549),
(122051, 'koKR', '아... 점점 후끈해지는군. 잠깐 낮잠을 좀 즐겨야겠어...', '', 25549),
(122050, 'koKR', '좋아! 누구 해골이라도 부술 준비가 됐네!', '', 25549),
(122049, 'koKR', '떡대들! 내 코코아 버터는 어떻게 된 거지?! 코코아랑 버터 중에 뭘 못 알아듣는 거야?!', '', 25549),
(122048, 'koKR', '이제, 잠깐 사우나를 즐기며 피로를 풀어야겠어... 사우나로 프로즌 칵테일하고 코코아 버터 가져와!', '', 25549),
(122047, 'koKR', '당신이 쥔 그 도끼... 군단의 무기군요. 그 굶주림을 통제할 수 있다고 확신하십니까?', '', 25549),
(122046, 'koKR', '임시.', '', 25549),
(122045, 'koKR', '잘 들어, 떡대들! 아방궁은 출입 금지 구역이야! 아무도 내 사유지에 못 들어오게 해!', '', 25549),
(122044, 'koKR', '대사 없음.', '', 25549),
(122043, 'koKR', '지금 갤리윅스 님은 열쇠를 안 가지고 있을 테니, 사우나에 숨어들어가면 훔칠 수 있을 거야!', '', 25549),
(122042, 'koKR', '아주 운이 좋은 친구네! 우리가 얘기를 나누는 바로 지금, 갤리윅스 님은 전용 사우나에서 휴식을 즐기고 계시거든.', '', 25549),
(122041, 'koKR', '군단에 죽음을.', '', 25549),
(122040, 'koKR', '', '당신이 가진 그 검은... 저주받은 거예요. 제발 이 신성한 곳에 죽음의 냉기를 끌어들이지 마세요!', 25549),
(122039, 'koKR', '', '아제로스를 잃을 순 없습니다.', 25549),
(122038, 'koKR', '', '당신이랑 얘기하지 않으려고 하거든, "그때 그 일" 때문에 저한테 빚진 게 있지 않냐고 하세요... 아셨죠?', 25549),
(122037, 'koKR', '', '바텐더인 이자크하고 말해 보세요. 어떻게 해야 금고 열쇠를 얻을지 알 거예요.', 25549),
(122036, 'koKR', '', '일리단 님이 길을 알려주실 거예요.', 25549),
(122035, 'koKR', '', '점멸만 했다 하면 며칠씩 수집품을 정리해야 돼요. 이 난장판을 쉽게 정리할 수 있는 방법이 있으면 좋겠네요.', 25549),
(122034, 'koKR', '조만간 사랑에 빠진 바보들이 우리에게 돈을 바칠 거라고!', '', 25549),
(122033, 'koKR', '이건 일생일대의 강도질이 될 거야!', '', 25549),
(122032, 'koKR', '', '군단을 막을 수 있는 건 우리뿐입니다.', 25549),
(122031, 'koKR', '', '죽음의 기사여, 제발 이 신성한 곳을 그 사악한 도끼로 더럽히지 말아 주시기 바랍니다. 그 굶주림이 여기까지 느껴집니다.', 25549),
(122030, 'koKR', '', '네 것이 아니다... 그 홀의 주인은 네가 될 수 없다...', 25549),
(122029, 'koKR', '', '네가 어떻게 감히 우리 여왕님의 홀을 그 손에...', 25549),
(122028, 'koKR', '살금살금 돌아다녔으니 혼나야 돼!', '', 25549),
(122027, 'koKR', '', '그 홀은 우리 여왕님의 것이다...', 25549),
(122026, 'koKR', '침입자다!', '', 25549),
(122025, 'koKR', '넌 여기 있으면 안 된다!', '', 25549),
(122024, 'koKR', '', '그 홀은 네 것이 아니다, 주술사여. 홀을 내놓아라!', 25549),
(122023, 'koKR', '이렇게 숨어들다니, 나 진짜 화났어!', '', 25549),
(122022, 'koKR', '납작하게 두들겨 패 주마!', '', 25549),
(122021, 'koKR', '찾았다! 너 이제 죽는다!', '', 25549),
(122020, 'koKR', '거기 있구나! 혼날 줄 알아라!', '', 25549),
(122019, 'koKR', '누군가 숨어서 돌아다닌다!', '', 25549),
(122018, 'koKR', '너 거기 있는 거 다 안다... 나와라!', '', 25549),
(122017, 'koKR', '모습을 드러내라! 이 겁쟁이야!', '', 25549),
(122016, 'koKR', '근처에 누가 몰래 돌아다닌다!', '', 25549),
(122015, 'koKR', '이방인 하나가 접근하고 있소. 여왕 아즈샤라의 징표가 새겨진 무기를 들고 있군.', '이방인 하나가 접근하고 있습니다. 여왕 아즈샤라의 징표가 새겨진 무기를 들고 있습니다.', 25549),
(122014, 'koKR', '무슨 소리지?', '', 25549),
(122013, 'koKR', '누군가 몰래 돌아다닌다!', '', 25549),
(122012, 'koKR', '누가 몰래 숨어 다니는 거야?!', '', 25549),
(122011, 'koKR', '몸조심하게.', '', 25549),
(122010, 'koKR', '준비됐습니다.', '준비됐습니다.', 25549),
(122009, 'koKR', '내 생각엔 분위기가 아무래도 이상하네. 우리가 여기 도착한 후로 사람들이 온갖 이상한 짓을 하고 있어. 게다가 의회도... 자주 회동을 하고 있지. 그냥 별일 없기를 바랄 뿐이야.', '', 25549),
(122008, 'koKR', '', '이사 후로 이상하게 조용하네요. 다들 아직 여파를 느끼고 있는 건지도 모르죠. 달라란을 통째로 옮기는 건 쉬운 일이 아니니까요!$B$B빨리 모든 게 평소로 돌아갔으면 좋겠네요.', 25549),
(122007, 'koKR', '광기가 나를 부르는구나...', '', 25549),
(122006, 'koKR', '심연이 네 이름을 속삭인다.', '', 25549),
(122005, 'koKR', '그것이 꿈틀거린다. 얼굴도 기억도 없이... 죽음도 없이.', '', 25549),
(122004, 'koKR', '희망이 없으면 절망도 없지.', '', 25549),
(122003, 'koKR', '어리석긴! 넌 이길 수 없다...', '', 25549),
(122002, 'koKR', '주인님이 네 영혼을... 파괴하시리라!', '', 25549),
(122001, 'koKR', '저 너머의 어둠이... 날 기다린다.', '', 25549),
(122000, 'koKR', '주인님을... 위하여...', '', 25549),
(121999, 'koKR', '네 마음을 비틀지 못한다면 몸을 망가뜨리겠다.', '', 25549),
(121998, 'koKR', '영웅들이 어떤 꼴을 당하는지 보여 주지.', '', 25549),
(121997, 'koKR', '날 기쁘게 해라... 비명을 질러라!', '', 25549),
(121996, 'koKR', '운명은 막을 수 없다. 꿈에서조차도.', '', 25549),
(121995, 'koKR', '악몽이 너를 사로잡을 것이다!', '', 25549),
(121994, 'koKR', '너의 고통은 끝이 없으리라!', '', 25549),
(121993, 'koKR', '너를 영원히 잠재워 주마.', '', 25549),
(121992, 'koKR', '', '미안해요, $n 님. 상황을 보니 당분간은 머리를 못 자르겠어요. 다른 상인들도 대부분 가게를 달았더라고요.$B$B<다른 상인들을 둘러보는 키지>$B$B거리의 소문을 듣자 하니, 이곳뿐만 아니라 다른 곳에서도 심상찮은 일이 일어나고 있는 모양이에요. 도시들이... 음, 저도 잘 모르니까 함부로 이야기하지 말아야겠네요. 괜히 다른 사람까지 불안하게 만들고 싶진 않으니까요. 불안감은 이미 차고 넘쳐요.', 25549),
(121991, 'koKR', '어둠의 먹이가 되어라!', '', 25549),
(121990, 'koKR', '트릭시니가 보내서 왔습니다. 금고 열쇠가 필요합니다... 트릭시니 말로는 당신이 그녀에게 "빚을 졌다"고 하던데요.', '트릭시니가 보내서 왔어요. 금고 열쇠가 필요해요... 트릭시니 말로는 당신이 그녀에게 "빚을 졌다"고 하던데요.', 25549),
(121989, 'koKR', '어리석은 것... 이 땅은 이미 끝이다...', '', 25549),
(121988, 'koKR', '여기서 문제를 일으킬 거라면, 난 좀 빼줘... 내가 무슨 소리를 하는 거지? 뭘 해도 이 짓거리보단 잘 벌 거라고!', '', 25549),
(121987, 'koKR', '악몽에 온 걸 환영한다!', '', 25549),
(121986, 'koKR', '악몽이 나를... 부른다...', '', 25549),
(121985, 'koKR', '이 하찮은 땅을 위해 죽으려는 거냐?', '', 25549),
(121984, 'koKR', '안타깝군. 우리 편이 될 수도 있었는데 말이야...', '', 25549),
(121983, 'koKR', '싸우자는 건가? 내가 상대해 주지...', '', 25549),
(121982, 'koKR', '과연 나이트 엘프들이 네 죽음을 애도할까?', '', 25549),
(121981, 'koKR', '너흰 우릴 막을 수 없어. 우리는 군단이다!', '', 25549),
(121980, 'koKR', '난 이미 경고했다.', '', 25549),
