INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(116167, 'koKR', '당신의 역사 지식을 시험해보기 위한 문제: 스랄을 던홀드 요새에 가둬두고 노예로 부리던 인간의 이름은?', '', 25549),
(116166, 'koKR', '조심해! 초록색 놈들 온다! 우끼우끼 해 버려! 오늘을 제삿날로 만들어!', '', 25549),
